/* ÇEVİRİ it · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("it","olay",{
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Mehmed IV rinunciò alla caccia — l'ultimo sussulto alla vigilia della deposizione", "7daa904b"], "d": ["Dopo la disfatta di Mohács (agosto 1687) l'esercito, a cui non era stata pagata la paga (ulûfe), si ribellò e marciò su Istanbul. Mehmed IV fece uccidere Süleyman Pascià, che aveva fatto sparire il sigillo del gran vizierato, e ne mostrò la testa ai soldati e, disperdendo gli attrezzi da caccia e i levrieri, annunciò di essersi pentito — ma questo gesto non bastò a salvare il suo trono e pochi mesi dopo fu deposto.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Resa della fortezza di Munkács (Mukačevo) all'Austria dopo tre anni di assedio", "ca2efc3d"], "d": ["La fortezza di Munkács, assediata dalle forze imperiali alla fine del 1685, resistette per tre anni sotto la guida di Ilona Zrínyi, moglie di Imre Thököly; secondo numerose opere di consultazione pubblicate la fortezza fu consegnata il 17 gennaio 1688 al generale Antonio Caraffa. Fu la caduta di una delle ultime grandi fortezze della resistenza filo-ottomana in Ungheria sul fronte ottomano-asburgico.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Baltacı Mehmed Pascià e la tradizione della zarina Caterina", "c1b739f1"], "d": ["Il racconto popolare che lega la salvezza dell'esercito russo assediato sul Prut ai doni/alla tangente inviati da Caterina I a Baltacı Mehmed Pascià fu ripetuto per secoli.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["La discussione sull'«occasione perduta» sul Prut — due opinioni", "61ee699c"], "d": ["Che ci si accontentasse della pace mentre l'esercito ottomano aveva completamente circondato l'esercito russo fu oggetto di discussione tra gli storici subito dopo il trattato — nelle parole stesse del TDV, 'si è compreso che era stata perduta una grande occasione e questa tesi è stata sviluppata intensamente da chi era di opinione contraria.' Secondo i critici lo zar poteva essere catturato e le armi dell'esercito russo requisite; secondo i difensori, invece, per impedire il rafforzamento della Svezia nell'Europa settentrionale era una 'politica più saggia' indebolire la Russia in modo limitato. Il TDV riporta entrambe le opinioni senza prendere posizione.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Istituito il comitato di trentadue persone per la scienza e la traduzione", "0e3a713c"], "d": ["Durante il gran vizierato di Damad İbrahim Pascià fu istituito a Istanbul un comitato di trentadue dotti-scribi, che, nelle parole del TDV, 'si può considerare l'accademia dell'epoca'. Il comitato rese in turco opere di storia, filosofia e geografia dall'arabo, dal persiano, dal greco e dal latino — tra queste la traduzione della Fisica di Aristotele da parte di Yanyalı Esad Efendi con una squadra di venticinque persone e la presidenza del poeta Nedim di un comitato di traduzione storica. Il giorno non è indicato nel TDV, l'anno è dichiarato.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Mahmud I attirò Patrona Halil a palazzo facendolo cadere in una trappola", "6147059f"], "d": ["Sette settimane dopo l'ascesa al trono Mahmud I, tramite uomini di fiducia — a palazzo Hacı Beşir Agha, fuori il khan di Crimea Kaplan Giray I — attirò dalla propria parte i capi militari e spezzò l'influenza di Patrona Halil. Il 25 novembre 1730 a Topkapı Patrona Halil, Muslu Beşe e Kel Mehmed Agha, convocati a una riunione nella Camera della Circoncisione, furono fatti entrare; al cenno del gran visir Silâhdar Mehmed Pascià trentadue uomini armati, nascosti in precedenza, uscirono e li uccisero tutti e tre. Mahmud I prese così completamente il controllo della rivolta.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Humbaracı Ahmed Pascià (Bonneval) posto a capo del Corpo degli Humbaracı", "27b0b1d7"], "d": ["L'ufficiale di origine francese, il cui vero nome era Claude-Alexandre conte di Bonneval, dopo aver servito dapprima negli eserciti francese e austriaco, si convertì all'Islam a Sarajevo prendendo il nome di Ahmed e nel 1729 si rifugiò presso lo Stato ottomano. Ahmed Pascià, posto nel 1731 sotto Mahmud I a capo del Corpo degli Humbaracı, addestrò circa 300 soldati portati dalla Bosnia nella caserma da lui fatta costruire a Üsküdar Ayazma; il loro numero superò presto i 600 e lui stesso diede anche lezioni di matematica. Il tentativo di rivolta intrapreso in Ungheria con Rákóczi a favore della Francia scosse la sua influenza e nel 1738 fu esiliato a Kastamonu. Morì a Istanbul il 23 maggio 1747 e la sua tomba si trova nel cimitero della Mevlevîhâne di Galata.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Ripresa di Smederevo (Semendire) dalle mani degli Asburgo (corona del Regno d'Ungheria) — Guerra del 1737-39", "63dcf604"], "d": ["Secondo la voce Semendire del TDV, la fortezza, lasciata all'Austria nel 1717 con Passarowitz, fu ripresa con l'avanzata ottomana sul fronte Danubio-Sava della guerra ottomano-austriaca iniziata nel 1737; le forze asburgiche (corona del Regno d'Ungheria) poterono resistere nella regione fino all'agosto 1738, dopo di che Smederevo rientrò nell'amministrazione ottomana. Il trattato di Belgrado firmato un anno dopo (18-09-1739) avrebbe sancito questo guadagno — insieme a Belgrado e alla Serbia settentrionale.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Ritorno della valle della Morava all'amministrazione ottomana — Jagodina, Kragujevac e Čačak", "b219d3c9"], "d": ["Con la ripresa di Smederevo nell'agosto 1738 anche la valle della Morava, rimasta tra Smederevo e il corpo principale ottomano, tornò all'amministrazione ottomana: Jagodina, Kragujevac e Čačak sono considerate ottomane da questa data. Le fonti non datano né ricordano separatamente il ritorno di questi tre luoghi; la mappa si basa sul giorno di Smederevo. Il trattato di Belgrado (18-09-1739) sancì questa situazione.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Abdülhamid I muore di paralisi leggendo la notizia della caduta di Očakov (Özi)", "6ac60365"], "d": ["Secondo la voce abdulhamid-i del TDV İslâm Ansiklopedisi, Abdülhamid I, la cui salute si era aggravata per l'andamento duro della guerra russo-austriaca, morì per una paralisi improvvisa mentre leggeva il rapporto del gran visir che annunciava l'occupazione della fortezza di Özi da parte dei Russi (11 Rajab 1203 / 7 aprile 1789). Il suo corpo fu sepolto a Istanbul, a Bahçekapı, nel mausoleo da lui fatto costruire. Lo stesso giorno salì al trono il nipote Selim III.", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Alleanza difensiva ottomano-russa — difesa comune contro la Francia", "c87079d1"], "d": ["Con l'invasione dell'Egitto da parte di Napoleone, Selim III e lo zar russo Paolo I stipularono un'alleanza difensiva di quattordici articoli e otto anni. Le parti si impegnarono ad avere amici e nemici comuni, all'aiuto reciproco e a non fare paci separate.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Alleanza difensiva ottomano-Due Sicilie (Napoli) — causa comune contro la Francia", "1d2be816"], "d": ["Di fronte all'occupazione francese dell'Italia, di Malta e dell'Egitto lo Stato ottomano e il Regno delle Due Sicilie stipularono un'alleanza difensiva di nove articoli. Le parti si impegnarono a condurre la guerra insieme, a non fare paci separate e a darsi reciproco aiuto per terra e per mare.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Fondata la Repubblica delle Sette Isole — le Isole Ionie sotto protezione russo-ottomana", "08839694"], "d": ["Nel 1799 la flotta congiunta russo-ottomana aveva scacciato i Francesi dalle Isole Ionie (la fortezza di Corfù cadde il 5 marzo 1799); con la convenzione di dodici articoli del 21 marzo 1800 le isole furono costituite come Cezâyir-i Seb'a-i Müctemia Cumhuru (Repubblica delle Sette Isole), autonoma negli affari interni e legata agli Ottomani in quelli esterni. Il periodo tra il 05-03-1799 e questo giorno è un periodo di occupazione congiunta.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Tilsit — i diritti russi sulla Repubblica delle Sette Isole ceduti alla Francia", "98a78beb"], "d": ["Con l'accordo raggiunto a Tilsit tra Russia e Francia la Russia lasciò alla Francia i propri diritti sulle Sette Isole; le truppe francesi si stabilirono sulle isole nell'estate del 1807 e la Repubblica delle Sette Isole scomparve.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Passaggio di Santa Maura (Leucade) e delle Isole Ionie sotto protezione britannica — assetto post-napoleonico", "0af821dc"], "d": ["Santa Maura e le altre Isole Ionie, passate alla Francia nel 1797, dopo la sconfitta definitiva di Napoleone con un trattato speciale firmato a Parigi il 5 novembre 1815 tra Inghilterra, Russia, Austria e Prussia furono lasciate sotto protezione britannica con il nome di 'Stati Uniti delle Sette Isole' — è un documento distinto dal trattato generale di Parigi del 20 novembre 1815. La protezione sarebbe durata fino al 1864, poi le isole sarebbero state cedute alla Grecia.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Conquista di Prizren — centro di sanjak ottomano in Kosovo", "f84c220f"], "d": ["Il 4 Rajab 859 (20 giugno 1455) l'esercito ottomano al comando di Mehmed il Conquistatore prese Prizren dopo la guerra con il despota serbo Đurađ Branković — nelle fonti ottomane Vılkoğlu. La città a metà del XIII secolo era passata da Bisanzio al Regno serbo ed era stata residenza reale sotto il re Milutin, lo zar Dušan e il re Uroš; dopo la morte di Dušan la sua importanza era diminuita. Dopo la conquista fu fatta centro di un sanjak e conservò questa qualità per quattro secoli e mezzo, fino al 1912. Prizren, prima della dissoluzione della Jugoslavia, era l'unica città dei Balcani in cui si parlavano insieme tre lingue — albanese, turco e serbo.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["La caduta della Bastiglia — inizio della Rivoluzione francese", "96e931f1"], "d": ["Nel clima di furia e di crisi economica provocato dal licenziamento del ministro delle finanze Necker da parte di re Luigi XVI (11 luglio 1789), il popolo di Parigi marciò sulla fortezza della Bastiglia chiedendo armi e polvere da sparo. Negli scontri iniziati nel pomeriggio, la fortezza, difesa da un centinaio di guardie soltanto contro oltre tremila insorti, si arrese verso le 17:00; alcuni funzionari, tra cui il governatore Bernard-René de Launay, furono uccisi e sette prigionieri liberati. Quasi vuota e già destinata alla demolizione, la fortezza era il simbolo della tirannia regia — si racconta che a Luigi XVI fu riferito: «No, sire, non è una rivolta, è una rivoluzione». Il 14 luglio è oggi la festa nazionale francese e l'evento è considerato l'inizio simbolico del movimento popolare, che si estese rapidamente a tutto il paese, e della Rivoluzione francese (1789-1799) — la quale, nel decennio successivo, abbattendo la monarchia assoluta avrebbe cambiato in modo duraturo la carta politica dell'Europa e gli equilibri internazionali di cui faceva parte anche l'Impero ottomano.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["L'esercito mamelucco entra a Malatya — la città passa dagli Ilkhanidi all'amministrazione mamelucca", "2540363d"], "d": ["I Mamelucchi inviarono su Malatya un esercito al comando di Seyfeddin Tengiz, vice di Damasco; l'esercito entrò in città il 22 Muharram 715 (28 aprile 1315). Malatya fino ad allora era sotto il dominio ilkhanide ed era il punto chiave della linea ad ovest dell'Eufrate in cui si toccavano le sfere di influenza ilkhanide e mamelucca. Il passaggio di mano della città mostra l'avanzata dei Mamelucchi verso l'Alto Eufrate nella lunga contesa tra i due Stati. Dopo questa data Malatya sarebbe passata per un certo tempo sotto l'amministrazione degli Eretnaoğlu e, dal 1338, sarebbe tornata di nuovo sotto il dominio mamelucco.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Fine del beylik degli Eşrefoğlu — Beyşehir e Seydişehir passano agli Hamidoğlu", "e4e70846"], "d": ["Demirtaş, figlio dell'emiro Çoban, governatore generale ilkhanide dell'Anatolia, si mosse contro i beylik turcomanni che avevano dichiarato la propria indipendenza ed entrò a Beyşehir facendo uccidere Eşrefoğlu Süleyman Şah, che un tempo si era lamentato di lui (9 ottobre 1326). Il beylik degli Eşrefoğlu, fondato alla fine del XIII secolo nella zona di Beyşehir e Seydişehir, ebbe così fine. La voce Hamîdoğulları del TDV dà il seguito: Beyşehir, Seydişehir, Akşehir e Doğanhisar, appartenenti agli Eşrefoğlu eliminati da Demirtaş, furono aggiunte ai confini del beylik di Hamid. Nello stesso anno anche Dündar Bey degli Hamidoğlu fu consegnato a Demirtaş e ucciso. Questi territori nel 1381 sarebbero stati venduti a Murad I per 80.000 monete d'oro e sarebbero passati all'amministrazione ottomana.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Malatya torna sotto il dominio mamelucco — fine dell'amministrazione degli Eretnaoğlu", "08b80aa2"], "d": ["Malatya, entrata nell'amministrazione mamelucca nel 1315, negli anni della dissoluzione dello Stato ilkhanide era passata per un certo tempo nelle mani degli Eretnaoğlu. La voce Malatya del TDV dà il ritorno in una frase: dal 1338 la città fu di nuovo dominata dai Mamelucchi. È uno spaccato degli anni in cui nell'Anatolia sud-orientale il vuoto post-ilkhanide era spartito tra Mamelucchi ed Eretna.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Perdita del porto di Smirne a favore della flotta crociata — spezzata la potenza navale degli Aydınoğlu", "775c65fe"], "d": ["La flotta crociata, composta da navi di Venezia, Genova, del Regno di Cipro, dei cavalieri di Rodi e del duca di Nasso su incoraggiamento di papa Clemente VI, tolse il porto di Smirne agli Aydınoğlu (28 ottobre 1344). Il porto era stato preso nel 1328-1329 dal padre di Umur Bey, Mehmed Bey, al genovese Martino Zaccaria ed era la base della potenza navale degli Aydınoğlu nell'Egeo. Nel settembre del 1334 una flotta crociata giunta con lo stesso scopo aveva dovuto ritirarsi; questa seconda spedizione ebbe successo. Umur Bey continuò la resistenza e, unito agli altri beylik turchi, sconfisse la flotta crociata il 17 gennaio 1345, ma il porto non poté essere ripreso.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Alâeddin Bey dei Karamanoğlu aggiunge Konya, Aksaray e Niğde ai territori dei Karaman", "2b8b0f70"], "d": ["Alâeddin Bey dei Karamanoğlu, che volle approfittare del fatto che il Sultanato mamelucco avesse posto fine al Regno armeno annettendo tutta la Cilicia e dei disordini scoppiati nello Stato degli Eretna nell'Anatolia centrale, aggiunse ai territori karamanidi, in primo luogo Konya (1366-1367), poi Niğde Karahisarı (Yeşilhisar), Aksaray, Akşehir, Ilgın, İshaklı e Kayseri. Konya, per il peso che portava come capitale selgiuchide, per i Karamanoğlu non era solo una città ma una pretesa di legittimità.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Uzun Hasan pose fine allo Stato dei Qaraquyunlu — il bacino del lago di Van passa agli Aqquyunlu", "d8d6c2e8"], "d": ["Il sovrano aqquyunlu Uzun Hasan, nel 1467, cogliendo di sorpresa il suo implacabile nemico, il sovrano qaraquyunlu Jahan Shah, che marciava contro di lui, pose fine allo Stato dei Qaraquyunlu. Con la scomparsa di Jahan Shah, che regnava dal 1438, il bacino del lago di Van — Van, Bitlis, Bargiri (Muradiye), Hoşap e Kotur — passò dai Qaraquyunlu all'amministrazione aqquyunlu. Questa vittoria fece dello Stato aqquyunlu l'unica grande potenza in Anatolia orientale e in Iran e mise Uzun Hasan sulla strada che una generazione dopo lo avrebbe portato a fronteggiare gli Ottomani.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Cem Sultan portato a Roma — diplomazia degli ostaggi e 40.000 ducati l'anno", "1c6715a8"], "d": ["Papa Innocenzo VIII, d'accordo con Pierre d'Aubusson, capo dei cavalieri di Rodi, fece portare Cem Sultan a Roma (4 marzo 1489). Cem si era rifugiato a Rodi il 29 luglio 1482, da lì era passato in territorio sabaudo e infine sotto la custodia papale. Bayezid II aveva accettato di pagare ai cavalieri 40.000 ducati l'anno e di concedere loro libertà di commercio nei territori ottomani in cambio della custodia del fratello. Questo pagamento non era un tributo, ma il prezzo per tenere immobile in Europa il legittimo rivale al trono: se Cem fosse stato libero avrebbe potuto raccogliere un esercito in Anatolia e per di più diventare fonte di legittimità di una crociata. Così una questione dinastica divenne per trent'anni il principale vincolo della politica estera ottomana — è la ragione della prudenza di Bayezid in Occidente. Con la morte di Cem nel 1495 questo vincolo venne meno.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Il Regno di Georgia diviso in tre — Kartli, Kakheti e Imereti con centro Kutaisi", "f9c5f798"], "d": ["Il Regno unito di Georgia, governato dalla dinastia dei Bagratidi, dopo una lunga lotta interna fu ufficialmente diviso in tre regni: a est Kartli, con centro Tbilisi, a nord-est Kakheti e a ovest Imereti, con centro Kutaisi. La voce Gürcistan del TDV conferma la divisione — 'la Georgia fu divisa in tre regni (Kartli, Kakheti, Imereti) e cinque principati'. La divisione fu decisiva nella contesa ottomano-safavide del secolo successivo: secondo il trattato di Amasya del 1555 Imereti, Dadiani, Gurieli e Daveli furono lasciati agli Ottomani; Kartli, Kakheti e Meskheti ai Safavidi. Cioè il fatto che l'atlante leghi la Georgia occidentale e quella orientale a padroni diversi nasce da questa divisione. Selim il Severo, quando era ancora governatore di Trebisonda, nel 1508 aveva reso il Regno di Imereti (Açıkbaş) vassallo e tributario.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Occupazione di Tripoli di Barberia da parte degli Spagnoli — fine del dominio hafside", "de319d23"], "d": ["Dopo gli Ammaridi, il dominio degli Hafsidi a Tripoli di Barberia durò fino al 1510. In quell'anno la città fu occupata dagli Spagnoli al comando di don Pedro Navarro, conte di Oliveto; i musulmani scampati al massacro lasciarono la città. L'occupazione fu l'estremità orientale della catena di fortezze spagnole sulla costa nordafricana, da Melilla a Tripoli. La popolazione di Tripoli di Barberia nel 925 (1519) avrebbe inviato una delegazione a Istanbul per chiedere aiuto agli Ottomani contro l'invasione spagnola e la città nel 1551 sarebbe stata presa da Turgut Reis e Sinan Pascià ed entrata nell'amministrazione ottomana.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Malta e Tripoli date ai cavalieri di San Giovanni — nuova base dell'ordine cacciato da Rodi", "2595729e"], "d": ["I cavalieri di San Giovanni (Hospitalier), scacciati da Rodi da Solimano il Legislatore nel 928 (1522), dopo otto anni senza patria furono stabiliti a Malta da Carlo V, re di Spagna e Germania; con la stessa donazione fu affidata all'ordine anche la difesa di Tripoli di Barberia. Malta, con i suoi porti ideali, divenne una base adatta ai cavalieri, efficaci sui mari: si stabilirono dapprima a Birgu, fortificarono il Forte Sant'Angelo e costruirono il Forte San Michele sulla punta di Senglea. Questo insediamento generò una base nemica permanente al centro del Mediterraneo, che tagliava le rotte marittime ottomane; i conflitti, iniziati con l'incursione di Turgut Reis a Gozo nel 947 (1540), sarebbero durati fino all'assedio di Malta del 1565.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Pace di Westfalia — finisce la guerra dei Trent'anni, l'unità del Sacro Romano Impero si dissolve", "d7719f05"], "d": ["I trattati che posero fine alla guerra dei Trent'anni (1618-1648) furono firmati lo stesso giorno a Münster e a Osnabrück (24 ottobre 1648). Circa trecento principati del Sacro Romano Impero ottennero il diritto di condurre una politica estera propria; l'impero cessò di essere uno Stato e divenne una cornice. La Svezia prese la Pomerania Occidentale e Stettino, il Brandeburgo ottenne la Pomerania Orientale e l'aspettativa sull'arcivescovato di Magdeburgo — qui inizia l'accumulo di territori degli Hohenzollern che nel 1701 avrebbe marciato verso la monarchia. L'indipendenza dei Paesi Bassi e della Svizzera fu ufficialmente riconosciuta. Per gli Ottomani l'importanza è indiretta ma grande: quando gli Asburgo si ritirarono dal fronte occidentale nacque in Europa centrale una potenza in grado di rivolgersi di nuovo a est.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Proclamato il Regno di Prussia — Federico I incoronato a Königsberg", "337a9f74"], "d": ["Federico III, elettore di Brandeburgo, con l'assenso dell'imperatore Leopoldo I si fece incoronare a Königsberg e assunse il titolo di «Re in Prussia» (18 gennaio 1701). Il titolo era tratto dalla Prussia Orientale, perché essa era al di fuori del Sacro Romano Impero e un elettore soggetto all'imperatore poteva essere re solo fuori dai confini dell'impero. I territori sparsi della dinastia degli Hohenzollern da questa data cominciarono a essere designati con il nome di un solo Stato.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["La Sardegna passa dalla Spagna alla dinastia dei Savoia — nasce il Regno di Sardegna", "adf778b7"], "d": ["Nell'ultimo anello degli assetti che chiusero la guerra di successione spagnola l'isola di Sardegna fu tolta alla Spagna e data alla dinastia dei Savoia; il duca di Savoia in cambio lasciò la Sicilia e assunse il titolo di re di Sardegna. Cagliari e Sassari uscirono così da due secoli di amministrazione spagnola. Il Regno di Sardegna che ne nacque è il nucleo dello Stato che un secolo e mezzo dopo avrebbe fondato l'unità italiana — cioè la radice del Regno d'Italia che entrò a Roma nel 1870 discende da qui.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"b": ["La Corsica venduta da Genova alla Francia — Trattato di Versailles", "770343df"], "d": ["La Repubblica di Genova cedette alla Francia la Corsica, che teneva da secoli ma che a causa delle rivolte non riusciva di fatto a controllare. La voce Korsika del TDV dà l'evento in una frase: Genova nel 1768 vendette alla Francia quest'isola di cui non riusciva a prendersi molta cura. La cessione segna il ritiro di Genova dall'ultimo grande possedimento territoriale nel Mediterraneo; l'isola nel 1796 sarebbe passata per un certo tempo in mano inglese, poi sarebbe stata restituita alla Francia. Il fatto che l'isola fosse territorio francese rese suddito francese Napoleone Bonaparte, che sarebbe nato a Ajaccio un anno dopo. In quest'anno (1768) la Corsica, compresa Bastia, fu venduta da Genova alla Francia (TDV Korsika; giorno non confermato).", "c6214397"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Trattato di Tilsit — la Prussia perde metà dei suoi territori, fondato il Ducato di Varsavia", "d30bb2cc"], "d": ["Dopo la disfatta di Jena-Auerstedt la Prussia dovette accettare con Napoleone a Tilsit una pace gravosa (9 luglio 1807). Lasciò tutti i territori a ovest dell'Elba e i territori polacchi ottenuti con le spartizioni del 1793 e del 1795; da questi ultimi fu costituito il Ducato di Varsavia e la zona di Białystok fu data alla Russia. La Prussia perse circa metà della popolazione e del territorio e il suo esercito fu limitato a 42.000 uomini. Nell'atlante Poznań e Toruń da questo giorno passano al Ducato di Varsavia e Białystok alla Russia. Con questo trattato Łódź e Częstochowa (province polacche passate alla Prussia dopo il 1772) passarono al Ducato di Varsavia; Danzica (Gdańsk) divenne città libera indipendente.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Le truppe italiane entrano a Roma — fine dello Stato Pontificio e compimento dell'unità italiana", "a3689f2e"], "d": ["Quando, con la caduta di Napoleone III nella guerra franco-prussiana, la guarnigione francese a protezione di Roma si ritirò, le truppe italiane entrarono in città e il papa si ritirò in Vaticano. Così lo Stato Pontificio, esistente da oltre mille anni, ebbe fine e il Regno d'Italia, che includeva nell'unità anche Roma, si affacciò come forza politica sulla scena europea e mondiale. È un evento con conseguenze dirette per l'ultimo mezzo secolo dell'atlante: l'Italia unificata è lo Stato che nel 1911 avrebbe preso agli Ottomani Tripoli di Barberia e il Dodecaneso.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Battaglia di Chelenqo — fine dell'Emirato di Harar e occupazione abissina", "5671a0d9"], "d": ["Quando Dawud divenne imam di Aussa, Harar, rimasta in mezzo ai territori governati dagli Oromo, era tornata a essere un emirato indipendente e aveva conservato questa condizione fino all'occupazione abissina del 1887. L'emiro Abdullah, dichiarato il jihad, il 7 gennaio 1887 con 5000 uomini affrontò gli Abissini a Chelenqo (Shelenko); capito che sarebbe stato sconfitto, fuggì nella regione dell'Ogaden, a sud di Harar. La battaglia mostrò lo squilibrio tra l'esercito abissino dotato di armi da fuoco e le forze dell'emirato e fece scomparire uno degli ultimi emirati musulmani indipendenti al di là del Mar Rosso. Harar, Jijiga e Degehabur furono così annesse all'Abissinia.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Presa di Derbent da parte di Shah Ismail — il dominio safavide raggiunse la porta del Caucaso", "305542c4"], "d": ["Con la sconfitta e l'uccisione dello Shirvanshah Farrukh Yassar nel 1500 Baku e Shamakhi erano passate ai Safavidi, mentre Derbent era rimasta separata ancora per un po'. Shah Ismail nel 1509 prese la città e vi insediò una delle tribù rumlu; così il dominio safavide raggiunse la porta settentrionale del Caucaso, lo stretto passaggio tra il Caspio e le montagne. Con l'ingresso dello Shirvan nel 1538 sotto l'amministrazione safavide diretta il legame si stabilizzò. Derbent sarebbe passata agli Ottomani nella campagna del 1578 e fino al 1607 sarebbe stata il centro di un beylerbeylik di sette sanjak. L'annotazione del TDV è questa: \\\"La fondazione e lo sviluppo dello Stato safavide segnarono l'inizio di una nuova epoca a Derbent. Shah Ismail nel 1509 prese la città e vi insediò una delle tribù rumlu. Quando nel 1538 lo Shirvan entrò sotto il dominio safavide diretto...\\\"", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Annessione definitiva di Kars ai territori ottomani — il chiodo della frontiera orientale", "6235c85a"], "d": ["Dopo la distruzione dello Stato aqquyunlu da parte dei Safavidi, Kars per un certo tempo era rimasta in mano a Sevündük Khan Kurçibaşı, dei turcomanni Afshar. Durante la campagna dei Due Iraq (Irakeyn) di Solimano il Legislatore (940/1534), mentre le fortezze di Pasin, Şüregel e Oltu erano prese, è molto probabile che anche la fortezza di Kars fosse stata legata agli Ottomani; tuttavia la definitiva annessione della città avvenne tre anni dopo. L'annotazione del TDV è questa: \\\"Kars fu annessa definitivamente ai territori ottomani nel 944 (1537) da Dulkadırlı Mehmed Khan, entrato al servizio ottomano.\\\" Poiché la città e la fortezza erano in gran parte in rovina per le lunghe lotte, si intraprese una rapida riparazione; mentre nel 955 (1548) la fortezza era in riparazione i Safavidi attaccarono la città e distrussero di nuovo la fortezza. Kars sarebbe poi rimasta per trecentoquaranta anni la chiave della frontiera nord-orientale ottomana e dopo la guerra del 1877-78 sarebbe stata lasciata alla Russia.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Ripresa di Nikopol — fine dell'occupazione russa di sei mesi", "7fb299d7"], "d": ["Le forze russe, passate sulla riva meridionale del Danubio nella guerra ottomano-russa del 1806-1812, avevano preso Nikopol nell'ottobre 1810 al comando del generale Kutuzov. Sei mesi dopo, vedendo di non poter tenere la linea del Danubio, abbandonarono la città; prima di partire fecero saltare in aria gran parte della fortezza. L'annotazione del TDV è questa: \\\"Nell'ottobre dell'anno 1810 (nel periodo della guerra turco-russa del 1808-1812) Nikopol fu presa dalle forze del celebre generale russo Michail Kutuzov. I Russi, prima di lasciare la città, nell'aprile 1811 fecero saltare in aria gran parte della fortezza e arrecarono gravi danni alla città.\\\" Dopo il ritiro delle forze russe gli Ottomani fecero ricostruire la fortezza; l'iscrizione del 1813-1814 è la registrazione di questa riparazione.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Evacuazione di Silistra — la fortezza centrale del Danubio abbandonata con le mura demolite", "561628bb"], "d": ["Silistra, una delle più forti fortezze ottomane sul Danubio, nel 1810 era stata bombardata dall'artiglieria russa e per l'esplosione di un deposito di armi la fortezza e il sobborgo avevano subito gravi danni. Dopo aver preso la città i Russi scelsero, invece di tenerla, di distruggerne le fortificazioni: il generale Kutuzov ordinò la demolizione delle mura e nel maggio 1811 comunicò allo zar che le mura di Silistra erano state fatte saltare. L'annotazione del TDV: \\\"Nel 1810 la città fu bombardata dai Russi… Dopo la presa della città da parte dei Russi e prima del loro ritiro il generale Kutuzov ordinò la distruzione di Silistra. Nel maggio 1811 comunicò allo zar che le mura di Silistra erano state fatte saltare.\\\" La stessa fortezza sarebbe stata ripresa dai Russi nella guerra del 1827-1828 e Helmuth von Moltke avrebbe descritto in dettaglio quell'assedio.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Fine della dinastia Zand — dominio qajar in Iran", "5dda30a4"], "d": ["Con la sconfitta dell'ultimo sovrano della dinastia Zand, Lotf Ali Khan, la dinastia fondata nel 1751 ebbe fine e tutto l'Iran passò nelle mani di Agha Mohammad Khan. La fondazione ufficiale dello Stato qajar si data a due anni dopo, all'incoronazione di Agha Mohammad Khan a Teheran con la corona di shahanshah (1796); tuttavia il controllo fu assunto nel 1794.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Differenze tra Losanna e Sèvres: da una pace imposta a una pace tra pari", "4b578583"], "d": ["Sèvres (10 agosto 1920) fu un documento imposto al governo di Istanbul e mai entrato in vigore; Losanna (24 luglio 1923) è invece la pace che Ankara firmò come parte paritaria e che la Grande Assemblea Nazionale Turca ratificò il 23 agosto 1923 (Losanna artt. 1, 143). Quanto ai confini, Sèvres riporta la frontiera europea della Turchia sulla linea di Çatalca e cede alla Grecia la Tracia orientale, Adrianopoli (Edirne) compresa, insieme a Imbro e Tenedo (Sèvres artt. 27, 84); Smirne e il suo circondario restano nominalmente sotto sovranità turca ma l'amministrazione passa alla Grecia, e dopo cinque anni il parlamento locale può chiedere l'annessione (artt. 65-83). Losanna traccia la linea Maritza-Arda, Edirne e Karaağaç restano alla Turchia, Imbro e Tenedo sono turche (Losanna artt. 2, 12, 14; Protocollo di Karaağaç). Per gli Stretti, Sèvres istituisce una commissione internazionale con competenza su tutte le acque, in cui il membro turco ha un solo voto; le fortificazioni vengono demolite e la zona è aperta all'uso degli Alleati (Sèvres artt. 36-61, 178-180). Losanna conserva il principio del libero transito ma prevede una commissione a presidenza turca, zone smilitarizzate e una guarnigione di 12.000 uomini a Istanbul (Losanna art. 23; Convenzione degli Stretti). Il riconoscimento dell'Armenia, l'arbitrato del presidente degli Stati Uniti sui confini e il piano di autonomia curda (Sèvres artt. 62-64, 88-93) non compaiono a Losanna. Per i territori arabi, l'Egitto, il Sudan e Cipro, Sèvres detta disposizioni dettagliate di cessione (Sèvres artt. 94-97 mandati, artt. 98-100 Hegiaz, artt. 101-122 rinuncia a Egitto, Sudan, Cipro, Marocco, Tunisia e Libia; anche gli intervalli di articoli del TDV sono questi); Losanna formula la rinuncia in modo più breve: il Dodecaneso va all'Italia, Cipro all'Inghilterra, il confine di Mossul è rinviato (Losanna artt. 3, 15-21). Sèvres ristabilisce ed estende le capitolazioni, controlla il bilancio e l'indebitamento turchi tramite la Commissione Finanziaria, limita la forza armata (gendarmeria e unità di rinforzo) a 50.000 uomini e vieta l'aviazione militare e navale (Sèvres artt. 155, 164, 191-195, 231-264, 261-263). Losanna abolisce le capitolazioni, ripartisce i debiti e non pone alcun limite separato all'esercito (Losanna artt. 28, 46-63; l'art. 113 abolisce anche gli uffici postali stranieri). Le disposizioni sulle minoranze a Sèvres sono più ampie e aperte all'intervento alleato, mentre a Losanna sono garantite dalla Società delle Nazioni e reciproche (Sèvres artt. 140-151; Losanna artt. 37-45).\n\nConfronto asse per asse:\n• Tracia orientale, Edirne, Çatalca — Sèvres: confine sulla linea di Çatalca; Tracia orientale ed Edirne alla Grecia (artt. 27, 84-85) | Losanna: confine lungo la Maritza e l'Arda; Edirne e Karaağaç restano alla Turchia (art. 2; Protocollo di Karaağaç)\n• Regione di Smirne — Sèvres: sovranità turca, amministrazione ed esercito greci, richiesta di annessione dopo cinque anni (artt. 65-83) | Losanna: nessun articolo di statuto speciale per Smirne; l'Anatolia rientra nei confini della Turchia (artt. 2-3 confine generale; nessuna prova di articolo specifico su Smirne)\n• Stretti e Istanbul — Sèvres: Commissione Internazionale degli Stretti, 1 voto turco; demolizione delle fortificazioni, zona a uso alleato; Istanbul resta in mano turca ma subordinata alla clausola sulle minoranze (artt. 36-61, 178-180) | Losanna: principio del libero transito; commissione a presidenza turca, zone smilitarizzate, guarnigione di 12.000 uomini a Istanbul (art. 23; Convenzione degli Stretti)\n• Armenia e Kurdistan — Sèvres: l'Armenia è riconosciuta, il suo confine è fissato dal presidente degli Stati Uniti; autonomia curda, richiesta di indipendenza dopo un anno (artt. 62-64, 88-93) | Losanna: nessuna disposizione in merito (non compare nei sommari degli artt. 1-143)\n• Isole dell'Egeo, Dodecaneso — Sèvres: Imbro, Tenedo e le isole dell'Egeo alla Grecia; Dodecaneso e Castellorizo (Meis) all'Italia (artt. 84, 122) | Losanna: Imbro e Tenedo alla Turchia, isole dell'Egeo orientale alla Grecia, Dodecaneso e Castellorizo all'Italia (artt. 12-15)\n• Cipro, Egitto, Sudan, territori arabi — Sèvres: mandato su Siria/Mesopotamia e Palestina, Hegiaz indipendente; protettorato sull'Egitto, Sudan, riconoscimento dell'annessione di Cipro (artt. 94-98, 101-117) | Losanna: confine siriano secondo l'accordo franco-turco del 1921, confine iracheno rinviato; rinuncia a Egitto, Sudan, Cipro (artt. 3, 16-20)\n• Capitolazioni — Sèvres: ristabilite ed estese; piano di riforma giudiziaria presso la commissione alleata (artt. 136, 261-263, 308-309) | Losanna: del tutto abolite; scompaiono gli uffici postali stranieri e il Consiglio Superiore di Sanità (artt. 28, 113-114)\n• Controllo finanziario e debiti — Sèvres: la Commissione Finanziaria Alleata controlla bilancio e indebitamento, il Debito Pubblico Ottomano (Düyun-ı Umumiye) si amplia, le risorse sono date in garanzia (artt. 231-264) | Losanna: il Debito Pubblico è ripartito tra gli Stati; i danni di guerra sono reciprocamente condonati (artt. 46-63, 58)\n• Limitazioni militari — Sèvres: esercito di 50.000 uomini, forza aerea e carri armati vietati, Commissioni Alleate di Controllo (artt. 152-207) | Losanna: nessuna limitazione generale; smilitarizzazione solo per le isole greche e le zone degli Stretti e della Tracia (art. 13; Convenzioni degli Stretti e della Tracia)\n• Minoranze — Sèvres: garanzia e diritto di intervento degli Alleati, annullamento dei beni abbandonati (Emval-i Metruke), restituzione (artt. 140-151, 86, 142-144) | Losanna: diritti garantiti dalla Società delle Nazioni alle minoranze non musulmane, diritti musulmani reciproci in Grecia; scambio di popolazioni greco-turco (artt. 37-45; Convenzione sullo scambio)\n• Status giuridico — Sèvres: firmato dal governo di Istanbul, rifiutato da Ankara, mai entrato in vigore (TDV) | Losanna: parte paritaria; ratifica della Grande Assemblea Nazionale il 2 agosto 1923, 213 voti favorevoli e 14 contrari (TDV; artt. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Conio del primo akçe ottomano", "38d2d638"], "d": ["Il primo akçe d'argento coniato a nome di Orhan Gazi è la proclamazione monetaria della sovranità indipendente del beylik; l'akçe rimase per cinque secoli l'unità monetaria di base.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Istituito il Beylerbeylik di Rumelia", "ffa16089"], "d": ["Le conquiste sulla sponda europea furono riunite sotto un unico tetto militare e amministrativo; il sistema dei beylerbeylik divenne l'ossatura dell'organizzazione provinciale dell'impero.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Matrimonio di Yıldırım Bayezid con Despina Hatun", "4b10dc6c"], "d": ["Il vassallaggio stabilito con il despotato serbo dopo il Kosovo fu sigillato dal matrimonio di Olivera, figlia di Lazar, con Bayezid — esempio tipico di diplomazia matrimoniale delle origini.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Istituito il Beylerbeylik d'Anatolia", "5ef8d3a7"], "d": ["Per l'amministrazione dei territori dei beylik annessi fu organizzato il Beylerbeylik d'Anatolia; l'ordinamento amministrativo a doppia ala Rumelia-Anatolia fu completato.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Completata la Grande Moschea di Bursa", "27bcc4a5"], "d": ["La grande moschea a venti cupole, costruita con il bottino di Nicopoli, è l'esempio monumentale dell'architettura ottomana delle origini e un museo a cielo aperto della calligrafia.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Destituzione ed esecuzione di Çandarlı Halil Pascià", "5e19438f"], "d": ["Dopo la conquista fu giustiziato il gran visir della nobile famiglia Çandarlı, che si era mostrato distante dall'assedio; per la prima volta un gran visir veniva ucciso per ordine del sultano e si apriva l'epoca dei visir di origine devşirme.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["La Moldavia resa tributaria", "25bd3693"], "d": ["Il voivodato di Moldavia accettò di pagare tributo; insieme a Valacchia e Transilvania la triplice cintura vassalla a nord del Danubio divenne il cuscinetto settentrionale dell'impero. Altri luoghi annessi nella stessa data: Iași.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Tributo di Dubrovnik (Ragusa)", "d127c78a"], "d": ["La repubblica mercantile di Ragusa, in cambio di un tributo, si garantì l'autonomia e i privilegi commerciali; si arricchì come finestra ottomana sull'Adriatico. Anche l'isola di Mljet, territorio della repubblica, condivise questo status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Campagna di Valacchia: il Voivoda Impalatore", "fd4530bb"], "d": ["Con la campagna organizzata contro Vlad Țepeș, che aveva rifiutato di pagare il tributo e ucciso gli ambasciatori, la Valacchia fu ricondotta al vassallaggio; l'attacco notturno e le scene di terrore degli impalamenti divennero leggenda in Europa. Altri luoghi annessi nella stessa data: Bucarest.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Inaugurato il complesso del Conquistatore (Fatih Külliyesi)", "a150ea55"], "d": ["Il complesso, con le sue otto madrase (Sahn-ı Semân), fu il primo grande passo del programma di trasformazione di Costantinopoli in centro del sapere del mondo islamico.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu a Costantinopoli", "8508229d"], "d": ["Ali Kuşçu, l'ultimo grande rappresentante dell'osservatorio di Samarcanda, su invito del Conquistatore divenne müderris alla Madrasa di Santa Sofia; fondò a Costantinopoli la tradizione della matematica e dell'astronomia.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunnâme del Conquistatore", "b08944c9"], "d": ["Il primo kanunname consuetudinario completo, che raccoglie l'organizzazione dello Stato, il protocollo e le pene; è discusso per il celebre articolo che consente il fratricidio «per l'ordine del mondo».", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Conio della prima moneta d'oro ottomana (sultanî)", "2fd5c0dd"], "d": ["Fu coniata la prima moneta d'oro ottomana, equivalente al ducato veneziano; le finanze imperiali entrarono nell'ordine monetario internazionale.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Trasferimento al Palazzo di Topkapı", "b9cd6a5e"], "d": ["Con il completamento del Nuovo Palazzo (Topkapı) il centro dell'amministrazione dello Stato vi fu trasferito; il palazzo restò per quattro secoli il cervello dell'impero.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["La Repubblica di Firenze divenne ducato — Alessandro de' Medici", "c08764e1"], "d": ["Per la pressione di papa Clemente VII la commissione di governo di Firenze (Balìa) adottò una nuova costituzione; il regime repubblicano di cinque secoli fu abolito e Alessandro de' Medici fu proclamato duca ereditario, salendo di fatto al trono il 1° maggio. Firenze passò così da città-repubblica indipendente a ducato ereditario della dinastia Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Nozze di Solimano con Hürrem Sultan", "abc05f26"], "d": ["La celebrazione del nikâh ufficiale di Solimano con Hürrem cambiò radicalmente la tradizione di palazzo; nacque l'istituzione della «Haseki Sultan» e si aprì la porta all'epoca delle donne nella politica dinastica.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Prime capitolazioni complete alla Francia", "e2264e48"], "d": ["Come parte dell'alleanza con la Francia contro la morsa asburgica furono firmati privilegi commerciali tra Jean de la Forest e Makbul İbrâhim Pascià; le capitolazioni, allora strumento diplomatico, nel corso dei secoli sarebbero diventate la porta della dipendenza finanziaria.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Campagna dell'Oceano Indiano: assedio di Diu", "fcd1217a"], "d": ["La flotta partita da Suez attraversò il Mar Rosso e assediò Diu nel Gujarat; benché la fortezza non venisse presa, la potenza ottomana si estese per la prima volta all'Oceano Indiano e il monopolio portoghese fu scosso.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Viaggio in India di Seydi Ali Reis", "e5da3b2c"], "d": ["Seydi Ali Reis, incaricato di portare in Egitto la flotta di Bassora, fu trascinato dalle tempeste fino in India; il Mir'âtü'l-memâlik, in cui racconta l'avventura del ritorno, è uno dei primi resoconti di viaggio ottomani.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Esecuzione di Pîrî Reis", "63026444"], "d": ["Il grande navigatore e cartografo, tornato dalla campagna di Hormuz dopo aver lasciato la flotta a Bassora, fu giustiziato a 84 anni — una delle decisioni più discusse della nostra storia della scienza.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Inaugurato il complesso della Süleymaniye", "1c6458b2"], "d": ["Il complesso che l'architetto Sinan chiamava «opera da compagno» divenne, con le sue madrase, il suo ospedale e la sua biblioteca, il più grande complesso educativo e caritatevole del periodo classico.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Assedio di Malta", "f57f6a85"], "d": ["Malta, chiave del Mediterraneo, fu assediata per quattro mesi; Turgut Reis cadde martire e l'assedio fu tolto. Fu il primo grande passo indietro della marineria dell'epoca di Solimano.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Completata la Moschea Selimiye", "3b0484e1"], "d": ["La Selimiye, che Sinan chiamava «opera da maestro» e in cui un'unica cupola domina lo spazio, è considerata il culmine dell'architettura classica ottomana (Patrimonio mondiale UNESCO).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Fondato l'Osservatorio di Costantinopoli", "169bdf5d"], "d": ["L'osservatorio di Takiyyüddin, uno dei meglio attrezzati dell'epoca, fu fatto demolire nel 1580 dopo le polemiche seguite alla cometa del 1577; l'astronomia istituzionale fu ritardata di tre secoli.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Vittoria di Çıldır — inizio della guerra orientale", "13125a54"], "d": ["Con la sconfitta dell'esercito safavide a Çıldır si aprirono le porte del Caucaso; fu presa Tbilisi e la Georgia entrò sotto il dominio ottomano.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Battaglia delle Torce — lo Shirvan definitivamente ottomano", "3bbc23bc"], "d": ["Nella battaglia così chiamata perché proseguì di notte alla luce delle torce i Safavidi furono sconfitti in modo definitivo; il dominio ottomano sullo Shirvan e su Baku fu consolidato.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grande svalutazione — crisi dell'akçe", "9205c3d4"], "d": ["Sotto la pressione delle lunghe guerre e dell'argento americano il contenuto d'argento dell'akçe fu dimezzato; la rivoluzione dei prezzi alimentò la dissoluzione del sistema dei sipahi e il caos dei Celâlî.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Conquista di Tabriz", "6506bdb9"], "d": ["Il serdar Özdemiroğlu Osman Pascià entrò a Tabriz; l'antica capitale dei Safavidi fu posta sotto amministrazione ottomana. Osman Pascià morì poche settimane dopo nell'accampamento.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Pace di Ferhad Pascià — i confini più estesi a oriente", "c429972f"], "d": ["Con il trattato che pose fine alla guerra di 12 anni, concluso dopo l'arrivo a Costantinopoli dell'ambasciatore dello shah Abbas, Haydar Mirza (18 gennaio 1590), a condizione che i luoghi conquistati restassero agli Ottomani, Tabriz, Karabakh, Shirvan, Georgia e Luristan rimasero agli Ottomani; l'impero raggiunse a oriente i confini più estesi della sua storia.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Inizio della guerra ottomano-safavide (1603-1612) — controffensiva di Shah Abbas, perdita di Tabriz", "abf27dd8"], "d": ["Shah Abbas, che aveva riorganizzato il proprio esercito, approfittando dei disordini dei Celâlî passò all'offensiva; Tabriz cadde e le conquiste del Caucaso andarono perdute nel giro di pochi anni. Altri insediamenti perduti nella stessa campagna e subito dopo: Nakhchivan, Khoy, Marand, Salmas; anche i bey di Karacadağ (Ahar) e di Mukri tornarono dalla parte safavide.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Nascita di Evliya Çelebi", "2b6051ff"], "d": ["Evliya Çelebi, che raccolse i suoi viaggi di oltre cinquant'anni nel Seyahatnâme in dieci volumi, lasciò un panorama senza pari del mondo ottomano del XVII secolo.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Pace di Nasuh Pascià", "bb69e388"], "d": ["Con il trattato che pose fine alla guerra in corso dal 1603 si rinunciò alle conquiste del 1590 e si tornò al confine di Amasya del 1555; fu ristabilito l'equilibrio sul fronte orientale.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Inaugurata la Moschea del Sultano Ahmed", "e39dfd43"], "d": ["La «Moschea Blu», con i suoi sei minareti e le piastrelle blu di İznik, è l'ultimo grande complesso imperiale del periodo classico.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Uccisione del sultano İbrahim", "bc4eb452"], "d": ["Con la motivazione della prodigalità e della crisi di governo l'alleanza tra il corpo dei giannizzeri e gli ulema depose İbrahim; dieci giorni dopo fu fatto strangolare con una fatwa. Salì al trono il settenne Mehmed IV; il potere passò di fatto nelle mani della valide sultan Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Morte di Kâtib Çelebi", "e167e89d"], "d": ["Vertice della storia del sapere ottomano con la bibliografia Keşfü'z-zunûn e la geografia Cihannümâ; è noto per l'approccio pionieristico che usava fonti europee.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Evento di Edirne — deposizione di Mustafa II", "0291c1cd"], "d": ["La permanenza del sultano a Edirne e la collera per l'influenza di Feyzullah Efendi si trasformarono in una grande rivolta di esercito e artigiani; lo şeyhülislam fu linciato, il sultano fu deposto e il palazzo tornò a Costantinopoli.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambasciatore a Parigi: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["La grande ambasciata inviata in Francia fu la prima osservazione sistematica dell'Occidente sul posto; il suo Sefâretnâme ispirò il rinnovamento dell'Età dei Tulipani.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Fondata la prima stamperia ottomana", "4943f7e5"], "d": ["Fu concesso il permesso di stampare libri in turco; la prima opera, il Vankulu Lügati, fu stampata nel 1729. La stamperia è l'eredità più duratura del rinnovamento dell'Età dei Tulipani.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Le capitolazioni rese permanenti", "d044a79e"], "d": ["I privilegi concessi alla Francia non furono più limitati al sultano ma vincolati a un trattato permanente; il regime delle capitolazioni, divenuto non denunciabile unilateralmente, poté essere abolito solo a Losanna.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Fondata la Mühendishâne-i Bahrî-i Hümâyun", "9bf3f439"], "d": ["Fondata dopo il disastro di Çeşme per formare ufficiali di marina moderni, la scuola di ingegneria è la prima istituzione duratura di istruzione tecnica all'occidentale; la scuola di ingegneria terrestre seguì nel 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Prima ambasciata permanente a Londra", "6b5630eb"], "d": ["Nell'ambito del programma del Nizâm-ı Cedîd furono aperte ambasciate permanenti nelle capitali europee; la diplomazia ottomana passò al principio di reciprocità.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Morte di Alemdar Mustafa Pascià", "4426534e"], "d": ["Nella rivolta dei giannizzeri iniziata la notte del 15 novembre 1808, il gran visir riformatore, assediato alla Sublime Porta, non vedendo giungere l'aiuto atteso il giorno dopo fece esplodere l'arsenale e morì insieme a centinaia di assalitori; con lui furono sepolti l'ordinamento del Sened-i İttifak e il primo tentativo di riforma.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Prima gazzetta ufficiale: Takvîm-i Vekāyi", "c637f623"], "d": ["Cominciò la pubblicazione della gazzetta ufficiale dello Stato; è l'inizio della tradizione dell'opinione pubblica moderna e della comunicazione ufficiale.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Trattato commerciale di Balta Limanı", "e790b383"], "d": ["All'Inghilterra fu riconosciuta la posizione più privilegiata anche nel commercio interno e fu abolito il sistema di yed-i vahit (monopolio); mentre la produzione locale restava senza protezione, il trattato divenne il documento della completa apertura del mercato ottomano al libero scambio.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Fine dell'Emirato del Libano — destituzione di Bashir Shihab III", "f85ae454"], "d": ["L'emiro Bashir II (III), che non riusciva a controllare la contesa cristiano-drusa e gli equilibri interni nella regione dello Shuf, fu destituito nel gennaio 1842; l'ordinamento emirale locale in vigore dal 1516 (per opera dei Ma'n e poi degli Shihab) ebbe fine e la regione passò all'amministrazione ottomana diretta e poi al sistema del doppio caimacamato.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: ordinamento Mecidiye", "c77be809"], "d": ["Con la riforma monetaria furono ritirate le monete dal titolo alterato; fu istituito un sistema bimetallico stabile basato sulla lira d'oro (Mecidiye).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Fine del dominio locale della famiglia Harfush a Baalbek", "8438f4ae"], "d": ["L'influenza della famiglia Harfush, che dal 1521 (dopo la rivolta di Janbirdi al-Ghazali) governava Baalbek come piccola dinastia locale, terminò con il nuovo riordinamento amministrativo della Sublime Porta; la città fu ridotta a ordinario centro di kaza dipendente dal vilayet di Damasco.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Fondata la Şirket-i Hayriyye", "462830e7"], "d": ["La società fondata per gestire i vapori sul Bosforo è considerata la prima società per azioni ottomana; gli approdi dei vapori impressero il loro segno sulla vita cittadina.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Primo contratto di debito estero", "9017c579"], "d": ["Per finanziare la guerra di Crimea fu contratto sul mercato di Londra il primo prestito estero; il punto raggiunto con 15 indebitamenti in 21 anni fu la moratoria del 1875 e il Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Linea telegrafica a Costantinopoli", "d320f39f"], "d": ["La prima linea telegrafica, stabilita per le necessità della guerra di Crimea, fu aperta al servizio; in pochi decenni l'impero ebbe una delle più estese reti telegrafiche del mondo.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Kanunnâme sulle terre", "6bae243a"], "d": ["Il kanunname che modernizzò il diritto fondiario legò all'atto di proprietà (tapu) il possesso effettivo delle terre mîrî; è tra i documenti fondamentali dell'ordinamento della proprietà dell'attuale Medio Oriente.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Prime lezioni al Dârülfünun", "08f74066"], "d": ["Il Dârülfünun, destinato a impartire istruzione di livello universitario, iniziò a funzionare con lezioni pubbliche; l'istituzione, proseguita a intermittenza, fu aperta in modo permanente nel 1900 e divenne il nucleo dell'Università di Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Regolamento dei Vilâyet", "ad20853b"], "d": ["Al posto dell'ordinamento per eyalet fu istituita l'organizzazione dei vilayet sul modello francese; sull'esempio dell'applicazione del Vilayet del Danubio di Midhat Pascià fu estesa a tutto il paese.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Viaggio di Abdülaziz in Europa", "9ff0fa1e"], "d": ["Il primo viaggio in Europa di un sultano ottomano con finalità di pace; l'Esposizione di Parigi e le visite a Londra servirono da vetrina sia della diplomazia sia della modernizzazione.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Inaugurato il Mekteb-i Sultânî di Galatasaray", "f9688524"], "d": ["Il liceo con insegnamento in francese, con una composizione studentesca senza distinzione di religione e comunità, divenne il simbolo dell'ideale di uguaglianza nell'istruzione del Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Entra in vigore il primo libro della Mecelle", "6475461c"], "d": ["La Mecelle, che raccolse con tecnica legislativa moderna il campo delle obbligazioni e dei beni del diritto islamico, è considerata il primo codice civile islamico; la commissione presieduta da Cevdet Pascià completò i 16 libri nel 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Deposizione di Abdülaziz", "eb7397ea"], "d": ["Statisti e alti ufficiali costituzionalisti deposero Abdülaziz con un colpo di Stato silenzioso; la sua morte sospetta cinque giorni dopo e i successivi eventi di Çırağan generarono regolamenti di conti durati anni.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Incursione di Çırağan (caso Ali Suâvi)", "d2a9ac87"], "d": ["Il giornalista Ali Suâvi assalì Çırağan per rimettere sul trono Murad V; l'incursione fu repressa nel sangue e il regime di Abdülhamid strinse in modo permanente il cerchio della sicurezza.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Istituita la Régie (monopolio del tabacco)", "bad9b030"], "d": ["Le entrate del tabacco furono cedute alla compagnia Régie, a capitale straniero, nell'ambito del Düyûn-ı Umûmiyye; gli scontri sul «contrabbando della Régie» tra contadini e agenti durarono decenni. Altri insediamenti perduti nella stessa data: Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Visita del Kaiser Guglielmo II a Costantinopoli e Gerusalemme", "2988cd06"], "d": ["La seconda visita dell'imperatore tedesco rafforzò il riavvicinamento ottomano-tedesco; si aprì la strada alla concessione della ferrovia di Baghdad e a Damasco fu pronunciato il discorso sull'«amico dei trecento milioni di musulmani».", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["La Ferrovia del Hegiaz a Medina", "95009b9c"], "d": ["La linea di 1464 km, costruita solo con donazioni musulmane e ingegneria locale, raggiunse Medina; il viaggio del pellegrinaggio si ridusse da settimane a giorni. È la più grande opera infrastrutturale dell'epoca di Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Incidente del 31 marzo", "1d7c2bb2"], "d": ["La grande rivolta contraria al regime costituzionale si impadronì di Costantinopoli; l'Armata d'Azione venuta da Salonicco soffocò la rivolta e Abdülhamid II fu deposto.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Inizio dell'assedio di Edirne", "234d9b28"], "d": ["La difesa di cinque mesi di Şükrü Pascià divenne un'epopea di resistenza nel disastro balcanico; la città cadde per fame e fu ripresa nel luglio 1913.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Colpo di mano della Sublime Porta", "b304d02d"], "d": ["Il governo, che si preparava a cedere Edirne, fu rovesciato da un assalto armato degli unionisti; il ministro della Guerra Nâzım Pascià fu ucciso. Iniziò il periodo di pieno potere di Unione e Progresso.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Abolizione del Mutasarrifato del Monte Libano", "b5639051"], "d": ["L'ordinamento del mutasarrifato autonomo, istituito con il Règlement Organique del 1861 e fondato sul protocollo internazionale rinnovato nel 1864, fu denunciato unilateralmente dallo Stato ottomano durante la Prima guerra mondiale; il Ministero dell'Interno cominciò a nominare nella regione mutasarrif musulmani direttamente. L'epoca dell'autonomia, in cui tra il 1861 e il 1915 prestarono servizio otto mutasarrif, fu così chiusa.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Spartizione del paese tra i principi", "82f26bfb"], "d": ["Dopo la disfatta di Ankara Süleyman Çelebi passò in Rumelia e proclamò il sultanato a Edirne; İsa Çelebi tenne Bursa e Çelebi Mehmed la regione di Amasya-Tokat-Sivas. Sulla mappa queste tre parti sono mostrate con colori distinti.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Trattato di Gallipoli: la costa del Mar Nero fino a Mesembria (Misivri) lasciata a Bisanzio", "a4164eca"], "d": ["Dopo la disfatta di Ankara, l'emiro Süleyman, che voleva mantenere la propria posizione in Rumelia, firmò a Gallipoli un trattato con l'imperatore bizantino Manuele. Lasciò a Bisanzio Kartal, Pendik e Gebze con alcune isole, in Rumelia Salonicco e la Tessaglia, e sul Mar Nero la fascia costiera fino a Mesembria (Misivri); fu abolito anche il tributo che Bisanzio pagava agli Ottomani. Ahtopol, İğneada e Rezovo, sulla costa dell'Istranca, rimasero così per ventun anni sotto amministrazione bizantina; Murad II con la pace del 1424 riprese la maggior parte di questi luoghi.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Morte di Yıldırım Bayezid in prigionia", "7e968d83"], "d": ["Il sultano, prigioniero di Tamerlano, morì ad Akşehir; la salma fu portata e sepolta a Bursa. La sua morte rese irreversibile la lotta per il trono tra i principi.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Trattato di Gallipoli — concessioni a Bisanzio", "dfacbd00"], "d": ["Süleyman Çelebi, volendo assicurare la propria posizione in Rumelia, accordandosi con Bisanzio e con gli Stati latini restituì Salonicco, le coste del Marmara e alcune isole; accettò perfino di pagare tributo.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Scontro di Ulubat — sconfitta di İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, che teneva Bursa, fu sconfitto a Ulubat dal fratello Mehmed; anche i vari tentativi di ripresa rimasero senza esito.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Scomparsa di İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, tornato più volte in Anatolia con l'appoggio di Süleyman Çelebi, dopo l'ultima sconfitta scomparve; la sua parte passò a Çelebi Mehmed e sulla mappa l'area di Mehmed si estese verso ovest.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi passò in Valacchia", "8441267a"], "d": ["Çelebi Mehmed, che di fronte a Süleyman Çelebi aveva perso Bursa e Ankara ed era ripiegato su Tokat-Amasya, incoraggiò il fratello Musa ad andare in Rumelia. Musa, accettato l'invito del voivoda di Valacchia Mircea, raggiunse la Valacchia per mare; di qui avrebbe intrapreso la lotta che avrebbe lasciato Süleyman tra due fronti.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed riprese Bursa e Ankara — la parte anatolica esce da Süleyman Çelebi", "bfb69f12"], "d": ["Per i successi di Mûsâ Çelebi in Rumelia (Jambol, 13 febbraio 1410) l'emiro Süleyman Çelebi, che si trovava in Anatolia, passò in Rumelia. Dopo la partenza di Süleyman dall'Anatolia, Mehmed Çelebi riprese la regione di Bursa, compresa Ankara, e come segno della sua ascesa al trono fece coniare moneta datata 813. Sulla mappa la sponda anatolica del Marmara passa dalla parte dell'emiro Süleyman al colore di Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Battaglia di Kosmidion", "0efc2caa"], "d": ["Nella battaglia combattuta davanti alle mura di Istanbul con l'appoggio bizantino, Süleyman Çelebi sconfisse il fratello Musa; tuttavia il suo sostegno in Rumelia aveva cominciato a diminuire rapidamente. Altri insediamenti che cambiarono mano nella stessa data: Alasonya (Elassona), Aydos (Aytos), Bolayır (luoghi della mappa in Rumelia passati da Musa a Süleyman).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Assedio di Costantinopoli di Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, volendo punire Bisanzio che aveva sostenuto Süleyman, assediò Costantinopoli; questo assedio spinse Bisanzio all'alleanza con Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Morte dell'emiro Süleyman — Musa domina la Rumelia", "325c1549"], "d": ["Süleyman Çelebi, catturato mentre fuggiva da Edirne, fu ucciso; l'intera Rumelia passò nelle mani di Musa Çelebi. Sulla mappa la Rumelia passa dal blu al viola.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Battaglia di Çamurlu — ricostituzione dell'unità", "0b23173e"], "d": ["Çelebi Mehmed, che aveva ottenuto l'appoggio di Bisanzio, del despotato serbo e dei signori della Rumelia, sconfisse in modo decisivo il fratello Musa a Çamurlu; Musa fu ucciso mentre fuggiva. La Rumelia in mano a Musa passò a Mehmed insieme a Edirne e Mehmed Çelebi si proclamò a Edirne unico sovrano dello Stato ottomano. L'Interregno (Fetret Devri) di undici anni terminò e le parti dei principi sulla mappa si riunirono in un unico corpo.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Decisione della campagna di Vienna — la pace di Vasvár non fu rinnovata, l'obiettivo spostato da Győr a Vienna", "1bf278f2"], "d": ["L'imperatore Leopoldo I voleva il rinnovo del trattato di Vasvár, il cui termine non era ancora scaduto, e anche Mehmed IV appariva favorevole alla pace. Il gran visir Merzifonlu Kara Mustafa Pascià, invece, adducendo le lagnanze di Imre Thököly, da lui fatto proclamare re dell'Ungheria centrale, non fece rinnovare la pace; mobilitò i predicatori, primo fra tutti Vânî Mehmed Efendi, e convinse il sultano alla guerra. Nella consultazione fu stabilito che il sultano restasse a Belgrado e che il serdâr-ı ekrem avanzasse per prendere Győr; ma nella consultazione di Székesfehérvár (Alba Reale), nonostante l'opposizione del khan di Crimea Murad Giray e del governatore di Buda Uzun İbrâhim Pascià, l'obiettivo fu cambiato nell'assedio di Vienna.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Inizio del secondo assedio di Vienna — l'esercito davanti a Vienna", "bb542e49"], "d": ["L'esercito ottomano al comando del gran visir Kara Mustafa Pascià giunse davanti a Vienna il 14 luglio 1683. L'imperatore Leopoldo I, lasciata la difesa della città a Starhemberg, si ritirò nell'interno dell'Austria. Questo secondo assedio, preparato, a differenza del primo, mirando direttamente a Vienna, sarebbe durato fino al 12 settembre.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Disfatta di Párkány e perdita di Esztergom", "a7366740"], "d": ["L'esercito ritiratosi da Vienna fu sconfitto una seconda volta a Párkány; poi cadde Esztergom, una delle fortezze chiave dell'Ungheria. La ritirata cominciò a trasformarsi in crollo.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Esecuzione di Merzifonlu Kara Mustafa Pascià", "ce8b10ac"], "d": ["Il gran visir, considerato responsabile della disfatta di Vienna, fu fatto strangolare a Belgrado; ma la sua esecuzione non raddrizzò il fronte né restituì il prestigio scosso dello Stato.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Costituzione della Lega Santa", "060280d0"], "d": ["Sotto la guida del papato fu costituita tra Austria, Polonia e Venezia la Lega Santa (Mukaddes İttifak) contro gli Ottomani; nel 1686 si unì anche la Russia. L'impero entrò così in una guerra su più fronti destinata a durare sedici anni.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Prima difesa di Buda", "ccc43630"], "d": ["Il primo assedio di Buda da parte dell'esercito della Lega Santa fu respinto con l'ostinata difesa di quattro mesi della fortezza; ma le fortezze in Ungheria continuavano a cadere una a una.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Perdita di Uyvar", "689ab78c"], "d": ["Cadde la fortezza di Uyvar, rimasta ventidue anni in mano ottomana e divenuta proverbiale in Europa; la presenza ottomana nell'Alta Ungheria si sciolse.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arresto di Thököly a Oradea — dissolto il Regno dell'Ungheria centrale, si arresero le fortezze dell'Alta Ungheria", "1741aaaf"], "d": ["Dopo la disfatta di Vienna gli Ottomani avevano cominciato a vedere in Thököly uno dei responsabili della guerra e della sconfitta. Il 15 ottobre 1685, per ordine del serdar Melek İbrâhim Pascià, il beylerbey di Oradea Ahmed Pascià fece arrestare Thököly venuto in aiuto; si sperava, consegnandolo agli Asburgo, di ottenere migliori condizioni di pace. Quando si diffuse la notizia dell'arresto, tutte le fortezze e le città del Regno dell'Ungheria centrale, tranne Munkács, difesa dalla moglie Ilona Zrínyi, si arresero agli Asburgo; la maggior parte dei soldati kuruc passò all'esercito asburgico. Quando Thököly fu liberato a Belgrado il 2 gennaio 1686 il regno non esisteva più.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Perdita di Buda — capitale ungherese di 145 anni", "70800e2b"], "d": ["Dopo un assedio di settantotto giorni Buda cadde; l'ultimo beylerbey, Abdurrahman Abdi Pascià, cadde martire sulle mura. La perdita della città, sotto amministrazione ottomana dal 1541, è considerata il simbolo della perdita dell'Ungheria. Altri insediamenti perduti nella stessa data: Pest.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Seconda Mohács (Harsány) — perdita della Transilvania e di Mohács", "a7922681"], "d": ["Nella pianura in cui era stata ottenuta la grande vittoria del 1526 questa volta si subì una grave sconfitta; l'esercito si disperse e i soldati ribelli fecero destituire il gran visir. La sconfitta portò anche alla perdita della Transilvania.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Perdita di Atene ed esplosione del Partenone", "b6691730"], "d": ["Una bomba lanciata dall'artiglieria veneziana fece saltare in aria il Partenone, che gli Ottomani usavano come arsenale; il tempio di duemila anni fu ridotto in rovina. La città passò ai Veneziani (sarebbe stata ripresa nel 1688).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Deposizione di Mehmed IV e ascesa di Solimano II", "9f53037c"], "d": ["Per i disastri sul fronte e la rivolta dell'esercito Mehmed IV fu deposto dopo un regno di 39 anni; al suo posto fu portato il fratello Solimano II, tenuto da quarant'anni nel kafes.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Prima perdita di Belgrado — assedio della Lega Santa", "c6b9b19a"], "d": ["Belgrado, in mano ottomana dal 1521, si arrese all'esercito della Lega Santa; le porte della Serbia furono aperte al nemico e il pericolo arrivò alla linea Niš-Sofia. Altro insediamento che nello stesso giorno nell'atlante passa dagli Ottomani agli Asburgo: Hisarcık (Grocka) — segue la catena di Belgrado, il suo centro principale (TDV belgrad; approssimazione dichiarata).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden attraversò la Morava davanti a Požarevac (Passarowitz) — Požarevac cadde agli Austriaci", "bcf3fc59"], "d": ["Il margravio Ludwig von Baden nell'agosto 1689 attraversò la Morava a Paraćin e avanzò verso Niš; la città rimase in mano austriaca fino all'estate 1690 (il TDV suleyman-ii dice che nel 1690 Paraćin fu ripresa). Il giorno e la lettura di Röder non sono stati riverificati.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Perdita di Niš — avanzata asburgica (corona del Regno d'Ungheria), l'anno più critico", "c5e27b3f"], "d": ["L'avanzata asburgica (corona del Regno d'Ungheria) tolse agli Ottomani anche Niš; le incursioni giunsero fino a Skopje e Pristina. Vidin cadde invece dopo, nell'ottobre 1689 (voce separata). Nell'anno più buio della guerra lo Stato sentì minacciata persino la capitale.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orșova e Kladovo (Fethülislâm) poste sotto guarnigione austriaca", "ee8dd875"], "d": ["Dopo la presa senza combattere di Vidin (ottobre 1689, TDV vidin) Baden il 25 ottobre 1689 riparò e presidiò Orșova e Fethülislâm; Orșova rimase agli Austriaci fino all'autunno 1690. Il giorno si basa su Bánlaky/Röder e non è stato riverificato.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš di nuovo ottomana", "0c4f44eb"], "d": ["Fâzıl Mustafa Pascià partì in campagna nel luglio 1690; dopo la presa di Pirot (Şehirköy), Požarevac e Golubac (Güvercinlik), Niš, assediata, passò in mano ottomana il 27 settembre 1690 (TDV semendire). Nello stesso tempo era stata ripresa anche Vidin. Altri insediamenti che nello stesso giorno nell'atlante tornano dagli Asburgo agli Ottomani: Jagodina (Yagodina) e Prokuplje (Ürküp) — non essendo reperibile il giorno a livello di luogo è stato assunto il giorno di Niš (TDV semendire; approssimazione dichiarata; Röder 1842 scrive che il visir passò da Jagodina tra l'8 e il 24 settembre, la contraddizione non è risolta).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Le truppe austriache si arresero a Smederevo", "90da20c4"], "d": ["Dopo la presa di Niš il 27 settembre 1690, con un assedio di quattro giorni le truppe austriache a Smederevo si arresero (TDV semendire). Bánlaky/Röder indicano il 24 settembre; le fonti si contraddicono, si è seguito il TDV.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrado ripresa", "ab435838"], "d": ["Il gran visir Köprülüzâde Fâzıl Mustafa Paşa l'8 ottobre 1690 riprese Belgrado all'Austria; la città perduta nel 1688 tornò così agli Ottomani (TDV suleyman-ii). Altro insediamento che nello stesso giorno nell'atlante torna dagli Asburgo agli Ottomani: Hisarcık (Grocka) — segue la catena di Belgrado, il suo centro principale (TDV suleyman-ii; approssimazione dichiarata).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Disfatta di Slankamen — Fâzıl Mustafa Pascià martire", "10d626f1"], "d": ["In una delle battaglie campali più sanguinose del secolo il gran visir cadde martire colpito alla fronte; l'esercito si disperse. Con questa battaglia si spense la speranza di ripresa.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Perdita dell'isola di Chio", "07c084f8"], "d": ["La flotta veneziana occupò Chio; il dominio ottomano nell'Egeo fu minacciato. L'isola sarebbe stata ripresa l'anno seguente.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Decisione di Mustafa II di partire personalmente in campagna", "61c3ba9c"], "d": ["Il nuovo sultano, seguendo la via degli avi, annunciò che sarebbe partito in campagna alla testa dell'esercito; questa decisione risollevò il morale dell'esercito e iniziò un periodo di campagne personali destinato a durare due anni.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Ripresa di Chio", "6b496fca"], "d": ["Mezomorto Hüseyin Pascià, vincitore della flotta veneziana nelle battaglie navali delle Isole Oinousses, riprese Chio; fu il segno di una breve ripresa della marineria ottomana.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Vittoria di Lugoj — prima campagna austriaca di Mustafa II", "d5ee9b34"], "d": ["Nella prima campagna a cui il sultano partecipò di persona fu ripresa Lipova e le forze austriache furono sconfitte a Lugoj; dopo anni di sconfitte si ebbe la prima interruzione. L'atlante considera ripresa in questa campagna dagli Asburgo agli Ottomani anche Karánsebes (Caransebeş); la fonte dà solo settembre 1695 (TDV mustafa-ii), il giorno dell'atlante è preso dalla voce di Lugoj (approssimazione dichiarata).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Perdita della fortezza di Azov", "2b78b5cd"], "d": ["Pietro I, che mirava a raggiungere il Mar Nero, nel suo secondo assedio prese Azov; la Russia si insediò per la prima volta in modo permanente in una fortezza ottomana e fece il primo passo per diventare una potenza navale.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Vittoria di Olașin (Ulaş)", "02ac9ca8"], "d": ["La vittoria ottenuta sulle rive del Danubio nella seconda campagna del sultano mandò a monte il piano austriaco di prendere Timișoara; non mutò tuttavia l'equilibrio generale della guerra.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Disfatta di Zenta — decisi i destini della guerra", "475c4a7b"], "d": ["L'esercito fu sorpreso mentre attraversava il fiume Tibisco dall'improvviso attacco del principe Eugenio; le forze divise sulle due sponde furono annientate in poche ore e morirono migliaia di soldati e statisti, compreso il gran visir Elmas Mehmed Pascià. Zenta, una delle più gravi disfatte della storia ottomana, rese inevitabile il tavolo della pace.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Inizio dei negoziati di pace di Karlowitz", "1f395cf3"], "d": ["Nei negoziati iniziati con la mediazione di Inghilterra e Olanda la delegazione ottomana dovette per la prima volta accettare il principio dell'«uti possidetis» (resta ciò che si possiede); le trattative, durate settantadue sessioni, sono considerate la nascita della moderna diplomazia ottomana.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali di Kavala sbarcò in Egitto", "514c943f"], "d": ["Nell'esercito ottomano inviato a riprendere l'Egitto occupato dai Francesi c'era anche un reparto di volontari raccolti a Kavala. Mehmed Ali, sulla trentina, era il secondo comandante di questo reparto; mise piede in Egitto non come governatore ma come ufficiale di compagnia.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["I soldati albanesi abbatterono il governatore d'Egitto", "c76a0ec2"], "d": ["Le truppe albanesi, cui non erano pagati gli stipendi, si ribellarono e costrinsero il governatore Hüsrev Pascià a fuggire dalla cittadella. Nel vuoto creato dal ritiro dei Francesi i bey mamelucchi, il corpo albanese e i governatori nominati dalla Sublime Porta entrarono in una lotta a tre; Mehmed Ali emerse stabilendo equilibri in questo triangolo. Altri insediamenti perduti nella stessa data: Tâif.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Gli ulema del Cairo proclamarono Mehmed Ali governatore", "a16752f2"], "d": ["Gli artigiani e gli ulema del Cairo, oppressi dalle tasse, si sollevarono sotto la guida del naqib al-ashraf Ömer Mekrem, dichiararono di non riconoscere il governatore Hurşid Pascià e insediarono Mehmed Ali nella carica di governatore. Nella storia ottomana l'elezione di un governatore da parte della popolazione è un evento assai raro.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["La Sublime Porta accettò il fatto compiuto: firmano di governatorato d'Egitto", "b86736a3"], "d": ["La Sublime Porta, che non aveva la forza di sostenere il proprio candidato in Egitto, inviò a Mehmed Ali il firmano di governatorato d'Egitto con il grado di visir. Sulla mappa l'Egitto da questa data passa allo strato vassallo (tono chiaro): giuridicamente territorio ottomano, di fatto paese della dinastia di Kavala. Altri insediamenti passati nella stessa data allo strato vassallo: Il Cairo, Alessandria, Damietta, Asyut, Assuan, Ibrim, Suez, Rosetta (Reşîd).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["La spedizione inglese di Fraser sbarcò ad Alessandria", "4d6c31be"], "d": ["In risposta all'avvicinamento ottomano alla Francia l'Inghilterra inviò in Egitto una forza di sbarco. Mehmed Ali era allora impegnato con i Mamelucchi nell'Alto Egitto; tornato rapidamente organizzò la difesa.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Disfatta di Rosetta (Reşid) — gli Inglesi respinti", "3636004c"], "d": ["La colonna inglese entrata nella cittadina di Rosetta subì gravi perdite nei combattimenti di strada; a settembre le forze evacuarono completamente l'Egitto. Questa vittoria consolidò il prestigio di Mehmed Ali sia in Egitto sia a Costantinopoli.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Strage della Cittadella: liquidazione dei bey mamelucchi", "84030b97"], "d": ["I bey mamelucchi, invitati al corteo organizzato per la campagna del Hegiaz, furono intrappolati nello stretto passaggio della Cittadella del Cairo ed eliminati. L'influenza mamelucca di cinque secoli finì così e in Egitto Mehmed Ali non ebbe più rivali.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Inizio della campagna del Hegiaz — l'esercito marciò da Suez per mare e per terra lungo la via dei pellegrini fino a Yanbu", "1c05c159"], "d": ["Riprendere i Luoghi Santi, in mano al governo saudita-wahhabita dal 1803, era la più grande questione di legittimità di Mahmud II; non avendo la Sublime Porta la forza, il compito fu affidato al governatore d'Egitto. Mehmed Ali mandò alla testa dell'esercito il figlio sedicenne Tosun.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Presa di Yanbu — la prima base costiera della campagna del Hegiaz", "179bc78d"], "d": ["Circa duemila fanti albanesi partiti da Suez con navi di nuova costruzione sbarcarono nell'ottobre 1811 presso Yanbu; la cittadina si arrese dopo due giorni di debole resistenza. La cavalleria al comando di Tosun, seguendo per terra la via dei pellegrini, giunse a Yanbu solo due settimane dopo via Aqaba e Wajh. Yanbu divenne la prima base nel Hegiaz dell'esercito egiziano in marcia su Medina e La Mecca.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Prima disfatta nella gola di Safra-Cedîde", "99ef804d"], "d": ["L'avanguardia egiziana, caduta in imboscata negli stretti passi di montagna, fu dispersa. La sconfitta fu la lezione tattica della campagna: si capì che nel Hegiaz non era possibile avanzare senza il sostegno delle tribù beduine.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medina ripresa", "6f6a5d55"], "d": ["Dopo un lungo assedio Medina si arrese. La ripresa della città del Profeta fu festeggiata a Costantinopoli con salve di cannone; a Mehmed Ali fu dato come ricompensa anche il governatorato di Gedda.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["La Mecca ripresa — aperta la via dei pellegrini", "3d6d66a0"], "d": ["Le forze egiziane entrate alla Mecca fecero leggere nuovamente nella Kaaba la khutba a nome del sultano ottomano. Le carovane di pellegrini, interrotte da dieci anni, poterono rimettersi in cammino. Sulla mappa il Hegiaz torna sotto il dominio ottomano, ma essendo l'amministrazione al Cairo è mostrato in tono vassallo. Altro luogo passato nella stessa data all'amministrazione vassalla: Gedda.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Ripresa di Tâif — completamento della campagna del Hegiaz", "6315fb31"], "d": ["Dopo Medina (dicembre 1812) e La Mecca (gennaio 1813), l'esercito egiziano al comando di Tosun Pascià riprese infine Tâif ai Wahhabiti. Il dominio saudita durato dieci anni ebbe termine e anche i tre centri sacri del Hegiaz entrarono di nuovo sotto controllo ottomano-egiziano.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali passò personalmente nel Hegiaz", "fda0ea2d"], "d": ["Vedendo che la campagna procedeva lentamente il governatore prese direttamente in mano il comando; trattando con i capi tribù cercò di sciogliere dall'interno il fronte saudita. Con questa campagna crebbe anche la quota dell'Egitto nel commercio del Mar Rosso.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Battaglia di Bisel: forze saudite sconfitte", "9c9ab91f"], "d": ["I Sauditi, duramente sconfitti in battaglia campale, si ritirarono nelle regioni interne. La tregua conclusa non fu duratura; due anni dopo l'operazione sarebbe stata portata nel cuore del Najd. L'atlante, dopo questa vittoria, considera Turaba e Hurma, a est di Tâif, tolte ai Sauditi (fonte dell'evento Lorimer, Gazetteer; la testimonianza specifica degli insediamenti e il giorno 13 gennaio sono approssimazione dichiarata).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrâhim Pascià partì per la campagna del Najd", "d5ed80d1"], "d": ["İbrâhim Pascià, subentrato al comando per la morte del fratello Tosun, intraprese una dura marcia di due anni nel deserto. L'esercito, avanzando pozzo dopo pozzo ed eliminando le tribù una per una, giunse alla capitale saudita.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Caduta di Diriyah — fine del Primo Stato saudita", "aa96206d"], "d": ["Dopo un assedio di sei mesi Diriyah si arrese e fu distrutta. L'emiro Abdullah ibn Saud fu inviato a Costantinopoli e giustiziato. La bandiera ottomana per la prima volta giunse così in profondità nell'interno dell'Arabia; la guarnigione del Najd rimase fino al 1824. Altri luoghi annessi nella stessa data: Diriyah (Najd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Inizio della campagna del Sudan", "b1fc6905"], "d": ["Lo scopo di Mehmed Ali era triplice: reclutare soldati per il proprio esercito, raggiungere l'oro di Sennar e distruggere i resti dei Mamelucchi in fuga. La forza al comando del figlio İsmâil Pascià discese a sud seguendo il Nilo.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Dongola passa senza violenza all'esercito egiziano (i Mamelucchi l'avevano lasciata nel giugno 1820)", "bc5942c0"], "d": ["Dongola, nella grande ansa del Nilo, passò senza violenza nelle mani dell'esercito egiziano di Ismail Pascià dopo che i Mamelucchi l'ebbero abbandonata nel giugno 1820. Sulla mappa il Sudan compare da questa data nello strato subordinato: il conquistatore è Il Cairo e Il Cairo sarà anche chi governa.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Battaglia di Jabal ad-Dayqa — la confederazione degli Shayqiya è sconfitta in modo decisivo dall'esercito egiziano", "befc9539"], "d": ["Un mese dopo il primo scontro a Kurti, l'esercito di Ismail Pascià, figlio di Muhammad Ali Pascià, sconfisse gli Shayqiya nella seconda e decisiva battaglia presso Jabal ad-Dayqa. Il capo shayqiya Makk Subayr si arrese; Makk Shawish continuò a resistere. Da allora il dominio egiziano sull'ansa del Nilo divenne permanente.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Resa del Sultanato di Sennar (Funj)", "3cac7dd2"], "d": ["La dinastia Funj di tre secoli si arrese senza combattere. Nello stesso anno l'accampamento stabilito nel punto di confluenza dei due rami del Nilo si trasformò in breve in Khartum, centro amministrativo del Sudan. Altri luoghi annessi nella stessa data: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Conquista del Kordofan", "06440602"], "d": ["La seconda colonna inviata a ovest, sconfitte a Bâra le forze del Darfur, prese il Kordofan insieme alla zona di En Nahud. Il dominio egiziano sul Sudan si estese così dalla valle del Nilo alle steppe occidentali.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Forze egiziane sbarcarono a Creta", "835aee90"], "d": ["Quando la rivolta greca si estese a Creta la Sublime Porta chiese l'invio sull'isola di una forza egiziana. L'influenza di Mehmed Ali sull'isola cominciò con questo intervento e otto anni dopo si concluse con la concessione a lui del governatorato di Creta.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Uccisione di İsmâil Pascià a Shendi", "223860c9"], "d": ["L'emiro locale Nemir, irritato dalle richieste di tasse e soldati, incendiò la casa in cui İsmâil Pascià alloggiava e bruciò lui e il suo seguito. La spedizione di rappresaglia trasformò la regione in un lago di sangue; l'amministrazione del Sudan fu da allora fondata sulla durezza.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II chiese aiuto a Mehmed Ali per la Morea", "03594a42"], "d": ["Per la rivolta di Morea, che l'esercito giannizzero non era riuscito a reprimere in tre anni, il sultano si rivolse all'esercito egiziano addestrato all'europea. In cambio furono promessi il governatorato di Morea e Creta. Questa richiesta fu la prima aperta ammissione che l'impero aveva bisogno della propria provincia.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrâhim Pascià sbarcò a Modone", "9c993dba"], "d": ["La forza di sbarco protetta dalla flotta egiziana mise piede all'estremità sud-occidentale della Morea. Questo esercito, dotato di fanteria regolare e artiglieria da campagna, ottenne in breve la superiorità sulle bande ribelli.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitza ripresa — caduto il centro della Morea", "8a478c11"], "d": ["Con la caduta di Tripolitza, centro amministrativo della rivolta, la maggior parte della Morea tornò sotto controllo. Sulla mappa la penisola compare in tono vassallo, essendo in mano alle forze egiziane.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Caduta di Missolonghi (Mesolongi)", "07257f87"], "d": ["Dopo un assedio di un anno la città fu presa. Ma l'eco che la difesa suscitò nella stampa europea portò al culmine la simpatia per la causa greca e preparò il terreno all'intervento delle grandi potenze.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Resa dell'Acropoli di Atene", "3b19f946"], "d": ["Con la caduta dell'Acropoli la rivolta greca era militarmente quasi finita. Proprio a questo punto la questione cessò di essere una rivolta interna e divenne oggetto della diplomazia europea.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Trattato di Londra: tre potenze imposero l'autonomia greca", "7ce46fd8"], "d": ["Inghilterra, Francia e Russia decisero di agire congiuntamente per far accettare tra Ottomani e Greci un armistizio e la condizione dell'autonomia; fu comunicato che in caso di rifiuto sarebbero intervenute le loro flotte. La Sublime Porta rifiutò la proposta.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Convenzione di Alessandria: decisione di ritiro dell'Egitto dalla Morea", "cc978f37"], "d": ["Mehmed Ali, che aveva perso la flotta a Navarino, senza consultare Costantinopoli si accordò direttamente con l'ammiraglio inglese e accettò di ritirare le proprie forze dalla Morea. Il fatto che un governatore concludesse un trattato autonomo con le grandi potenze preannunciava la crisi futura.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Le forze egiziane evacuarono la Morea", "8fb742dd"], "d": ["Le ultime truppe furono imbarcate; la penisola andò di fatto perduta e con il Protocollo di Londra del 1830 divenne il nucleo della Grecia indipendente. Mehmed Ali, che non aveva ricevuto il governatorato di Morea promesso, aveva perso in cambio una grande flotta e un grande esercito. Altri insediamenti perduti nella stessa data: Modone, Corone.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["L'amministrazione di Creta lasciata a Mehmed Ali", "7f76396d"], "d": ["Come compensazione per la perdita della Morea il governatorato di Creta fu dato a Mehmed Ali. L'isola fu governata dal Cairo per dieci anni; sulla mappa in questo periodo compare in tono vassallo. Altri luoghi annessi nella stessa data: Candia (Creta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrâhim Pascià entrò in Siria — iniziò la prima crisi", "1a5cc386"], "d": ["Il pretesto era il governatore di Acri, che non restituiva i fellah fuggiti dall'Egitto; la ragione reale era il bisogno che Mehmed Ali aveva del legname, dei porti e delle risorse umane della Siria. L'esercito, attraversato il Sinai, si impadronì rapidamente della costa della Palestina.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Inizio dell'assedio di Acri", "b211d96d"], "d": ["La fortezza che aveva fermato Napoleone nel 1799 resistette per sei mesi. L'assedio fu la prima grande prova dell'artiglieria moderna dell'esercito egiziano.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Acri cadde", "0f47917b"], "d": ["Quando le batterie che battevano le mura aprirono una breccia la fortezza fu presa. La porta della Siria era aperta; negli stessi giorni la Sublime Porta dichiarò ribelle Mehmed Ali e abolì il suo governatorato.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damasco si arrese", "48da3b62"], "d": ["La città si arrese senza combattere. İbrâhim Pascià cercò di conquistare il sostegno locale proclamando l'ordinamento fiscale e l'uguaglianza concessa ai non musulmani; le stesse politiche, pochi anni dopo, furono anche la causa delle rivolte contro di lui. Altri luoghi annessi negli stessi giorni: Beirut, Tripoli di Siria, Sidone.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Battaglia di Homs", "867810ee"], "d": ["L'esercito ottomano inviato a salvare la Siria fu sconfitto in campo aperto. Si vide che il nuovo esercito, costituito sei anni dopo l'abolizione del corpo dei giannizzeri, non era ancora pronto.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo presa", "9c0ead76"], "d": ["Cadde anche il centro commerciale e amministrativo della Siria settentrionale. L'esercito egiziano giunse così alle falde del Tauro e si volse ai passi alle porte dell'Anatolia.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Disfatta del passo di Belen (Beylan) — aperta la Cilicia", "4bae872b"], "d": ["La linea di difesa fu spezzata nello stretto passo dei monti Amano. Antiochia, Adana e Tarso passarono alle forze egiziane (l'occupazione di Maraş è del 1833 secondo il TDV, voce separata); sulla mappa la Cilicia torna al tono vassallo. La strada verso l'interno dell'Anatolia era ormai indifesa.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Cadde la gola di Gülek — la costa dell'İçil (Mersin, Silifke) sotto il controllo egiziano", "d9049b5b"], "d": ["La gola di Gülek, porta del Tauro verso la Cilicia, cadde in mano all'esercito egiziano. İbrâhim Pascià nominò un proprio mütesellim nel sancak dell'İçil e tutti gli scali sulla costa passarono sotto controllo egiziano. Sulla mappa Mersin e Silifke da questo giorno (estremo inferiore; il giorno della nomina non è nella fonte) sono mostrate legate all'Egitto; poiché nella decisione di Kütahya compare solo il muhassıllık di Adana, questo controllo termina con l'evacuazione dell'Anatolia.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğlisi sotto occupazione egiziana — imbocco del Tauro della strada Konya–Adana", "fb908900"], "d": ["Ereğli, sulla strada per Konya dell'esercito egiziano che aveva superato la gola di Gülek, nel 1832 entrò sotto l'occupazione di İbrâhim Pascià e, evacuata con l'assetto di Kütahya del 1833, fu di nuovo legata al vilayet di Karaman. Sulla mappa è il punto intermedio documentato dalla fonte della linea di occupazione tra Adana e Konya; per Ulukışla e Karapınar non è stata trovata testimonianza a livello di città.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["L'esercito egiziano entrò a Konya", "13952a2d"], "d": ["L'esercito, superato il Tauro, raggiunse l'Anatolia centrale. Per la prima volta le forze di un governatore ottomano avanzavano nei territori centrali dell'impero. Altri luoghi annessi nella stessa data: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Battaglia di Konya: il gran visir fatto prigioniero", "ec82cc9a"], "d": ["L'esercito ottomano, disperso dalla nebbia, subì una dura sconfitta e il gran visir Reşid Mehmed Pascià fu fatto prigioniero. L'esercito centrale dello Stato non esisteva più; non restava alcuna forza capace di fermarsi tra Costantinopoli e le forze egiziane.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş subì l'occupazione egiziana", "f558e383"], "d": ["Secondo il TDV Maraş nel 1833 subì l'occupazione di Kavalalı İbrâhim Pascià e restò per circa diciannove mesi sotto la sua amministrazione. Poiché Maraş era rimasta fuori dai confini provinciali dell'assetto di Kütahya, questa amministrazione è di fatto e non di diritto.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) subì l'occupazione egiziana — strada Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, sulla strada dell'esercito egiziano che avanzava verso Kütahya dopo la battaglia di Konya, nel 1833 rimase per un periodo in mano a İbrâhim Pascià. Sulla mappa è il punto intermedio documentato dalla fonte della linea di occupazione tra Konya e Kütahya; per Akşehir, Ilgın e İshaklı non è stata trovata testimonianza a livello di città, e restano nel colore ottomano.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["L'esercito egiziano raggiunse Kütahya", "214f8df6"], "d": ["İbrâhim Pascià si fermò a Kütahya, a tre tappe da Costantinopoli. Il suo non avanzare fu non militare ma politico: erano stati calcolati l'intervento russo e la reazione dell'Europa.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Flotta russa davanti a Büyükdere", "6f836d61"], "d": ["Mahmud II, che non aveva ottenuto aiuto da Inghilterra e Francia, si rivolse alla Russia, nemica del giorno prima. Questa decisione, ricordata con la frase del sultano «chi cade in mare si aggrappa al serpente», si concluse con lo sbarco dei soldati russi sugli Stretti e fece suonare in Europa i campanelli d'allarme.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Accordo di Kütahya (verbale) — Siria e Adana a Mehmed Ali", "25fe9985"], "d": ["La Sublime Porta lasciò a Mehmed Ali, oltre a Egitto, Creta e Hegiaz, i governatorati di Damasco, Aleppo, Tripoli di Siria e Sidone, e a İbrâhim Pascià il muhassıllık di Adana. In cambio l'esercito si ritirò a sud del Tauro. Non era un trattato, ma assunse la forma di firmani dati dal sultano a un governatore — la questione non era risolta, era rinviata.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Completato da Gülek il ritiro dell'esercito egiziano dall'Anatolia", "a53ac2a3"], "d": ["Dopo l'assetto di Kütahya le forze egiziane evacuarono l'Anatolia; verso metà giugno l'intero esercito passò dalla gola di Gülek in Cilicia. La costa dell'İçil (Mersin, Silifke) torna all'amministrazione ottomana; il muhassıllık di Adana e la Siria restano all'Egitto.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Trattato di Hünkâr İskelesi", "da741d5c"], "d": ["Fu firmata con la Russia un'alleanza difensiva reciproca di otto anni. Secondo una clausola segreta, se la Russia fosse stata attaccata, l'Impero ottomano avrebbe chiuso gli Stretti alle navi da guerra. Fu una delle decisioni più discusse della diplomazia ottomana e rese l'Inghilterra attiva nella questione egiziana.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Rivolta di Palestina-Nablus contro l'amministrazione egiziana", "4fe43e27"], "d": ["La leva obbligatoria, la raccolta delle armi e le nuove tasse provocarono in Palestina una vasta insurrezione. La rivolta fu duramente repressa; il sostegno all'amministrazione egiziana presso la popolazione locale si sciolse rapidamente.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Fine dell'amministrazione egiziana di Maraş (circa)", "bb46ca42"], "d": ["Contando dall'occupazione del 1833 la durata indicata dal TDV («circa diciannove mesi»), l'amministrazione egiziana termina verso l'estate del 1834. Anche il fatto che Mustafa Bey dei Küçükalioğulları nel 1834, incapace di resistere all'esercito egiziano, si ritirasse verso Maraş mostra che Maraş era allora un rifugio fuori dal controllo egiziano.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Rivolta del Jebel Druso", "12e74626"], "d": ["La resistenza scoppiata nella regione drusa durò due anni. Il malcontento accumulato in Siria avrebbe lasciato scoperte le spalle dell'esercito egiziano quando, nel 1840, le flotte alleate sbarcarono sulla costa.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali annunciò l'intenzione di proclamare l'indipendenza", "48633bbd"], "d": ["Il governatore dichiarò ai consoli delle grandi potenze di pensare di proclamare l'indipendenza di Egitto e Siria. L'Inghilterra vi si oppose con decisione: la nascita nel Mediterraneo di uno Stato forte e vicino alla Francia avrebbe minacciato la via dell'India.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["L'esercito ottomano attraversò l'Eufrate", "9af1ea69"], "d": ["Mahmud II spinse il suo esercito al confine siriano per riprendere ciò che aveva perso a Kütahya. L'ufficiale prussiano Moltke, presente nell'esercito come consigliere, obiettò alla scelta della posizione e all'attacco precoce; le sue obiezioni non furono ascoltate.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Battaglia di Nizip — l'esercito ottomano disperso", "156b3cdf"], "d": ["L'esercito ottomano, mal schierato, fu sconfitto in poche ore. Il sultano morì prima che la notizia della sconfitta giungesse a Costantinopoli; in pochi giorni lo Stato avrebbe perso il suo esercito, il suo sovrano e poi la sua flotta.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Morte di Mahmud II", "07eccfff"], "d": ["Il sultano, che nei trentun anni del suo regno aveva abolito il corpo dei giannizzeri e ricostruito l'amministrazione centrale, morì senza aver vinto il suo più grande avversario. Per la sua malattia non era stata fatta una diagnosi esatta. La morte fu tenuta nascosta fino al 30 giugno, finché non furono prese misure militari in città per il timore che si risvegliasse la mentalità giannizzera.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Ascesa di Abdülmecid e funerali di Mahmud II", "d0f3d2cc"], "d": ["Alla morte del padre salì al trono il sedicenne Abdülmecid. Lo stesso giorno la salma di Mahmud II fu portata al Palazzo di Topkapı; i disordini temuti non vi furono e ampie masse popolari, musulmane e non musulmane, parteciparono al corteo funebre.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Consegna della flotta ad Alessandria", "a53e6103"], "d": ["Il kapudan paşa Ahmed Fevzi Paşa, sospettando che il gran visir Koca Hüsrev Paşa volesse dare la flotta alla Russia, condusse la flotta ad Alessandria e la consegnò a Mehmed Ali. Lo Stato ottomano si ritrovò nello stesso mese senza esercito, senza sultano e senza flotta.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Nota comune delle grandi potenze", "2a3b8316"], "d": ["Cinque potenze consegnarono alla Sublime Porta una nota chiedendo che non concludesse da sola un accordo sulla questione egiziana. Una questione interna divenne così ufficialmente una «questione europea»; lo Stato ottomano perse di fatto il potere di decidere sulla propria provincia.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Trattato di Londra: quattro potenze al fianco degli Ottomani", "a517f775"], "d": ["Il trattato, firmato escludendo la Francia, diede a Mehmed Ali un ultimatum: se avesse accettato entro dieci giorni, il governatorato ereditario d'Egitto e Acri a vita; se avesse accettato entro venti giorni, il solo Egitto; se avesse rifiutato, nulla. Il governatore rifiutò.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardamento di Beirut e sbarco alleato", "0905ce92"], "d": ["La flotta anglo-austriaca bombardò Beirut; sul Monte Libano furono distribuite armi alla popolazione ribelle contro l'amministrazione egiziana. Il controllo di İbrâhim Paşa sulla Siria crollò tra rivolta interna e intervento esterno.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beirut e le città costiere perdute", "09bdaf23"], "d": ["Dopo gli scontri in direzione di Baalbek le forze egiziane si ritirarono dalla costa. Sulla mappa la costa libanese esce dal tono vassallo e torna all'amministrazione ottomana diretta.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Acri cadde in due ore", "5aec21f0"], "d": ["Nel bombardamento della flotta alleata l'arsenale della fortezza esplose e Acri si arrese in poche ore. La fortezza che otto anni prima İbrâhim Paşa aveva potuto prendere in sei mesi mostrò la superiorità dell'artiglieria navale.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Convenzione di Alessandria", "85cb47b0"], "d": ["Mehmed Ali accettò di rinunciare a Siria, Adana, Creta e Hegiaz, di restituire la flotta ottomana e di riconoscere la sovranità del sultano; in cambio fu garantito il governatorato ereditario d'Egitto.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["L'esercito egiziano evacuò Siria e Cilicia", "719a28dc"], "d": ["L'occupazione di nove anni terminò; l'esercito di İbrâhim Paşa tornò in Egitto attraverso il Sinai. Sulla mappa la vasta fascia che si estende da Aleppo a Gaza e da Adana a Creta passa di nuovo all'amministrazione ottomana diretta. Altri insediamenti perduti nella stessa data: Urfa, Maraş, Tarso, Antiochia, Candia (Creta), Hama, Damasco, Gerusalemme, Giaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firmano: il governatorato d'Egitto lasciato in via ereditaria alla famiglia di Kavala", "87b89ff8"], "d": ["Il firmano del sultano riconobbe il governatorato come trasmissibile di padre in figlio all'interno della dinastia; in cambio gli effettivi dell'esercito furono ridotti a diciottomila, le imposte legate a Costantinopoli e fu tolto il potere di coniare moneta e di concludere trattati. L'Egitto restò una provincia ma era ormai il paese di una dinastia separata. L'amministrazione del Hegiaz e dei Luoghi Santi tornò alla Sublime Porta. Altri insediamenti tornati nella stessa data dallo strato vassallo allo strato diretto: La Mecca, Medina, Gedda, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Convenzione di Londra sugli Stretti", "0e95a1ea"], "d": ["La convenzione, che sostituì il trattato di Hünkâr İskelesi, stabilì che in tempo di pace gli Stretti fossero chiusi a tutte le navi da guerra. Il privilegio ottenuto dalla sola Russia si trasformò così in garanzia comune dell'Europa; la questione degli Stretti ottenne uno statuto internazionale.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Paşa divenne di fatto governatore d'Egitto", "9e14f5d9"], "d": ["Al posto di Mehmed Ali, invecchiato e privo delle facoltà mentali, fu portato al governatorato il figlio İbrâhim Paşa. Ma pochi mesi dopo, nel novembre 1848, morì prima del padre.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Morte di Kavalalı Mehmed Ali Paşa", "871310e0"], "d": ["Il governatore, nato a Kavala, fondatore di una dinastia in Egitto e che aveva portato due volte l'impero sull'orlo dell'abisso, morì a ottant'anni. La dinastia da lui fondata regnò in Egitto fino al 1953; lo Stato, vedendo di aver potuto chiudere la ferita da lui aperta solo con l'intervento europeo, proseguì sulla via del Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Süleyman b. Kutalmış sconfitto e ucciso ad Ayn Salm; Antiochia esce dai Selgiuchidi di Anatolia", "0412dfa1"], "d": ["Süleyman b. Kutalmış, che nel 1084 aveva preso Antiochia a Bisanzio, morì nella battaglia di Ayn Salm combattuta con il sovrano selgiuchide di Siria Tutuş; la città passò sotto il controllo del sultano dei Grandi Selgiuchidi Malikshah e fu nominato governatore Yaghi-Siyan.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Morte di Malikshah; Antiochia con Yaghi-Siyan è legata al selgiuchide di Siria Tutuş", "c61da1b4"], "d": ["Dopo la morte del sultano dei Grandi Selgiuchidi Malikshah lo Stato fu diviso tra gli eredi; il governatore di Antiochia Yaghi-Siyan fu legato a Tutuş, signore della Siria.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Nicea si arrende ai Crociati; il centro selgiuchide si ritira a Konya, Bisanzio inizia a riprendere l'Anatolia occidentale", "8a4e90fa"], "d": ["Dopo l'assedio di Nicea da parte dei Crociati la città si arrese a Bisanzio il 19 giugno 1097; il sultano selgiuchide Kılıç Arslan I ritirò il proprio centro nell'interno, a Konya, mentre Bisanzio riprese luoghi sulle coste dell'Anatolia occidentale come Efeso.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Kılıç Arslan II prende a Bisanzio Dorileo (Eskişehir) e Kütahya", "3ddee6c2"], "d": ["Dopo Miriocefalo (1176), le fortezze bizantine dell'interno dell'Anatolia, Dorileo e Kütahya, negli ultimi anni di Manuele o dopo la sua morte, nel 576/1180, passarono in mano a Kılıç Arslan II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Karamanoğlu Mehmed Bey nominato subaşı di Ermenek, prende l'amministrazione dell'İç İl", "6d62be11"], "d": ["Karamanoğlu Mehmed Bey nel 675 (1276) fu nominato subaşı di Ermenek e prese l'İç İl sotto la propria amministrazione; Ermenek divenne il primo centro dei Karamanidi, che l'anno seguente avrebbero marciato su Konya.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Morte di Ertuğrul Gazi e passaggio di Osman Bey al beylik — eredità di Söğüt e Domaniç", "395fb9fa"], "d": ["Secondo il TDV Ertuğrul Gazi morì nel 680 (1281-82); la voce registra che vengono indicati anche il 1288 e il 1289. Osman Bey non ereditò dal padre una città conquistata, ma due assegnazioni che il sultano selgiuchide aveva dato a Ertuğrul, collocato sulla linea più avanzata della regione di frontiera: lo yurtluk (quartiere invernale) a Söğüt e lo yaylak (pascolo estivo) a Domaniç. Cioè il beylik cominciò non con un'eredità di conquista, ma con due assegnazioni di pascolo; sulla mappa questi due luoghi sono mostrati come «eredità» e non come «conquista».", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Vespri Siciliani — la dinastia angioina perse l'isola di Sicilia", "547db635"], "d": ["La rivolta scoppiata a Palermo all'ora del vespro del lunedì di Pasqua contro il governo di Carlo I d'Angiò staccò l'isola di Sicilia dalla dinastia angioina. Il Regno di Sicilia si divise in due: l'isola si volse all'Aragona, mentre la dinastia angioina si mantenne nel regno continentale con centro a Napoli. Anche i possedimenti esterni della dinastia sull'Adriatico e nel Mediterraneo restarono legati a questo regno: Corfù, che tenevano dal 1267, e Durazzo, che tenevano dagli anni 1270, continuarono come parte del Regno di Napoli; anche le fortezze di Valona, Kanina e Himara, sulla costa albanese, restarono nel regno con centro a Napoli (il comandante di Valona John of Taxis resistette ai Bizantini per tutto il 1282; Durazzo, Valona e Kanina passarono con ogni probabilità a Bisanzio all'inizio del 1285). Malta passò invece in mano aragonese solo nel 1284.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Incursione di Kulacahisar — prima azione militare di Osman Bey", "79b00b14"], "d": ["Voce Osman I del TDV: «Saccheggiò e incendiò la piccola fortezza di Kulaca presso İnegöl (684/1285)». È la prima azione militare di Osman Bey databile nelle fonti. Non fu conquistato un insediamento stabile, la fortezza fu saccheggiata e incendiata; è quindi più una classica incursione di frontiera che una conquista. È considerata il punto di partenza dell'attività militare del beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Conquista di Karacahisar — primo guadagno urbano e dominio su Eskişehir", "178ae619"], "d": ["Voce Osman I del TDV: Osman Bey nel 687 (1288) «conquistò Karacahisar e divenne signore di Eskişehir». È il primo vero guadagno urbano del beylik e secondo la tradizione con questo successo Osman Bey fu elevato a sancak bey di frontiera; si narra che a Karacahisar fu letta la prima khutba a suo nome e che vi fu nominato il primo cadì. La voce Eskişehir del TDV afferma che la tradizione ottomana dà la data del 1291, ma che l'esattezza di essa è dubbia.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Caduta di Acri in mano ai Mamelucchi — eliminazione dei Crociati dalla costa siriana: Sidone e Beirut", "3ca7a464"], "d": ["Acri, per lungo tempo centro del Regno crociato di Gerusalemme, fu conquistata dal sultano mamelucco al-Ashraf Khalil e il dominio dei Crociati in Palestina ebbe fine. I cavalieri templari, ritiratisi da Acri, si rifugiarono a Sidone; all'avvicinarsi dell'esercito mamelucco abbandonarono la fortezza marittima e fuggirono a Cipro e la città passò ai Mamelucchi la stessa estate. Anche Beirut, in mano ai Crociati dal 1197, fu presa nel 1291 dal governatore di Damasco Sanjar al-Shuja'i. Così la presenza crociata di due secoli fu cancellata dalla costa siro-palestinese.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Conquista di Bilecik e Yarhisar con un attacco notturno", "f461b0af"], "d": ["Voce Bilecik del TDV: «Sebbene i tekfur della regione, tra cui quello di Bilecik, avessero preparato un attentato contro Osman Gazi, quando la trama fu scoperta le forze ottomane conquistarono Yarhisar e Bilecik con un attacco improvviso (1299)». Le due fortezze furono prese in una sola operazione, nello stesso attacco notturno. Questa data è il punto di svolta considerato anno di fondazione dello Stato ottomano. Altri luoghi annessi nella stessa data: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Battaglia di Koyunhisar (Bapheus) — prima grande vittoria sull'esercito bizantino", "584a9512"], "d": ["Voce Osman I del TDV: Osman Bey il 27 luglio 1302 combatté a Bapheus (Koyunhisar) l'esercito bizantino e lo sconfisse. Questa vittoria è il punto di svolta che innalzò Osman Bey da bey di frontiera regionale a fondatore di dinastia. Dopo la battaglia la pianura di Bursa entrò sotto il controllo ottomano e iniziò il blocco di İznik.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Vittoria di Dimbos e poi presa di Kite e Ulubat", "e168ab64"], "d": ["Voce Osman I del TDV: nel 702 (1303) l'alleanza formata dai tekfur di Bursa, Kestel, Kite e Adranos fu sconfitta nella gola di Dimbos; il nemico fu ricacciato combattendo fino alla gola e il tekfur di Kestel morì sul campo di battaglia. Subito dopo la vittoria furono prese le fortezze di Kite e Ulubat, il collegamento terrestre di Bursa fu tagliato e il blocco fu reso più stretto. Alla battaglia partecipò anche il giovane Orhan.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Campagna del Sakarya: presa di Leblebicihisar, Lefke, Mekece e Geyve", "a51ba4d3"], "d": ["La voce Osman I del TDV dà l'ordine della campagna del Sakarya del 704 (1304): «Quando giunse a Leblebüci Hisarı, il tekfur si sottomise... Giunse a Lefke... Raggiunse Mekece... Andò a Geyve e prese la fortezza che trovò vuota». Lefke è la porta della valle del Sakarya verso Bilecik. Questa sola campagna, ponendo sotto controllo ottomano la catena di fortezze lungo la valle, chiuse il fianco orientale del bacino di İznik.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Chio passa sotto il controllo della famiglia genovese Zaccaria", "9eebe4de"], "d": ["Di fronte alla minaccia degli Aydınidi, l'imperatore bizantino chiese aiuto al genovese Benedetto Zaccaria; l'isola passò sotto il suo controllo (nominale vassallaggio bizantino). Il dominio degli Zaccaria durò fino al 1329.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Samo entra nella proprietà dei Genovesi (Zaccaria) di Chio", "0e6f51e3"], "d": ["La famiglia genovese Zaccaria, che aveva preso il controllo di Chio, aggiunse alla propria proprietà anche Samo, quasi spopolata (TDV: 1304-1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Conquista delle fortezze della gola di Geyve: Karaçepüş, Karatigin e Absu", "76907c78"], "d": ["Voce Orhan del TDV: Orhan nella campagna del Sakarya del 705 (1305) «conquistò le fortezze di Karaçepüş (Katoikia), Karatigin davanti a İznik e Absu (Hypsu: nella gola di Geyve)». Queste tre fortezze, chiudendo il passaggio tra la valle del Sakarya e il bacino di İznik, tagliarono completamente i soccorsi terrestri a İznik. A Karaçepüş e Absu, nella gola di Geyve, fu insediato Gazi Abdurrahman; la città ormai poteva essere fatta cadere solo per fame.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Campagna di Adranos (Orhaneli) — l'ultima campagna di Osman Bey", "4811546c"], "d": ["La voce Orhan del TDV registra la campagna alla fortezza di Adranos dell'autunno 1323 come ultima campagna di Osman Bey. Il tekfur di Adranos era stato membro dell'alleanza dei tekfur formata venti anni prima a Dimbos contro gli Ottomani; questa campagna significò la chiusura di quel conto. Il giorno esatto della conquista della fortezza non è noto; l'operazione fu proseguita da Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Morte di Osman Gazi e passaggio di Orhan Bey al beylik", "021487cd"], "d": ["Osman Gazi, che diede il nome al beylik, morì nel 724 (1324), come attestano i vakfiye di Asporça Hatun e di Mekece. Orhan, figlio che dal 1305 era alla testa dell'esercito nelle campagne, alla morte del padre salì alla guida del beylik senza alcuna lotta per il trono. Il passaggio senza scosse del sancak da parte della generazione fondatrice mostra che la dinastia superò con serenità la prima grande prova sulla via dal beylik di frontiera allo Stato.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Chio tolta agli Zaccaria e legata a Bisanzio", "f6741b26"], "d": ["L'imperatore Andronico III allontanò Zaccaria dall'isola e la legò a Bisanzio con il governatorato di Benedetto III. L'isola sarebbe stata occupata nel 1346 dal genovese Simone Vignosi.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Samo torna da Zaccaria a Bisanzio (catena di Chio)", "08034974"], "d": ["Con la fine della signoria degli Zaccaria (l'annessione di Chio a Bisanzio nel 1329) terminò anche la proprietà genovese a Samo.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Battaglia di Pelekanon (Maltepe) e presa dell'intera Kocaeli", "389e7bd4"], "d": ["Voce Orhan del TDV: il primo giorno della battaglia Orhan Gazi inviò una forza di trecento uomini per attirare l'esercito bizantino; il secondo giorno, con la discesa in pianura dei reparti al comando di Pazarlu, la battaglia si allargò e, ferito l'imperatore da una freccia, nell'esercito bizantino scoppiò il panico. L'esito è netto: «Orhan si impadronì dell'intera Kocaeli; dopo la vittoria gli abitanti di İznik non ebbero più alcuna speranza». Le cittadine costiere da Hereke a Üsküdar entrarono sotto dominio ottomano e Gebze fu fatta centro della regione. Fu l'ultimo esercito imperiale bizantino venuto a salvare Costantinopoli.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Fondazione della prima madrasa ottomana a İznik", "c85fb625"], "d": ["Orhan Bey, subito dopo aver preso İznik, vi nominò cadì Çandarlı Kara Halil, trasformò una basilica in moschea e, facendo costruire accanto un imaret e una madrasa, avviò la ricostruzione della città. Secondo la voce Dâvûd-i Kayserî del TDV la costruzione della madrasa fu completata nel 1336 e Orhan Gazi vi portò come müderris Dâvûd-i Kayserî con 30 akçe al giorno. Questa madrasa è il primo passo istituzionale della vita del sapere ottomano; il beylik aggiunse alla forza di conquista anche una tradizione del sapere. La trasformazione di una capitale bizantina presa con la conquista in centro del sapere islamico fu il primo segno concreto della pretesa ottomana di essere uno Stato stabile.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Bisanzio resa tributaria — assedio di İzmit e trattato", "0c1ec8d3"], "d": ["Voce Orhan del TDV: Orhan nell'estate del 733 (1333) assediò İzmit con un grande esercito e con catapulte e l'imperatore accettò un trattato. In cambio della rinuncia all'assedio Bisanzio accettò di pagare a Orhan 12.000 monete d'oro (hyperpera) all'anno; «così agli occhi dell'emiro ottomano Bisanzio era caduta nella condizione di paese tributario». In cambio Orhan sarebbe stato amico dell'imperatore e non avrebbe attaccato le città dipendenti da Bisanzio. Il fatto che un beylik di frontiera rendesse tributario l'Impero romano d'Oriente era la proclamazione di quanto fosse mutato l'equilibrio delle forze.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Samotracia passa dai Veneziani alla famiglia genovese Gattilusio", "c499ed5f"], "d": ["La famiglia genovese Gattilusio cacciò dall'isola i Veneziani, che la tenevano dal 1204.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Annessione del Beylik di Karesi: Balıkesir, Bergama, Biga, Edremit ed Erdek", "c7cb0511"], "d": ["La voce Orhan del TDV (İnalcık) pone l'annessione al 735 (1334-35): alla morte di Demirhan Bey i ghazi di Karesi e Hacı İlbey invitarono Dursun Bey al trono e chiesero aiuto a Orhan. Orhan marciò prima su Balıkesir; quando Dursun Bey, recatosi alle trattative di pace, morì colpito da una freccia scagliata dalla fortezza di Bergama, il beylik fu interamente annesso al paese ottomano. Nella stessa operazione si sottomisero Kirmasti e Mihaliç, fu presa Gölyazı e fu definitivamente conquistata Ulubat, in precedenza lasciata con la resa su garanzia. Orhan nominò Süleyman Paşa al sancak di Karesi e fece di Biga il centro di frontiera — fu così acquisito il quadro marinaro del passaggio in Rumelia. Nota: la voce Karesioğulları del TDV dà per lo stesso evento la data 746 (1345); l'enciclopedia si contraddice al suo interno. Altri luoghi annessi nella stessa data: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Samo entra nella proprietà della Maona di Chio", "01628b2f"], "d": ["Con la presa di Chio da parte del genovese Simone Vignosi e la consegna dell'amministrazione alla società della Maona, anche Samo entrò nella proprietà dei Genovesi di Chio (Maona) (TDV: 1346-1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Prima capitolazione di Orhan Gazi con i Genovesi", "e64cb196"], "d": ["Orhan Gazi, accordatosi con i Genovesi durante la guerra veneto-genovese, dopo la battaglia dello Stretto del febbraio 1352 inviò 1000 arcieri alla difesa di Pera e fornì 60.000 monete d'oro per il trasporto di soldati; in cambio concesse ai Genovesi la prima capitolazione. Il testo integrale del trattato non è giunto fino a noi. È il primo accordo ufficiale concluso dagli Ottomani con una potenza navale europea e sarebbe stato rinnovato trentacinque anni dopo, nel 1387.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Presa di Gallipoli — testa di ponte permanente in Rumelia", "ba51a160"], "d": ["Gli Ottomani presero nel 1354 Gallipoli, di cui avevano conosciuto i dintorni tra il 1349 e il 1352 come alleati di Cantacuzeno; il grande terremoto che abbatté le mura della città ne aveva creato l'occasione. La stretta testa di ponte di Çimpe si trasformò così in una vera base sulla sponda rumeliota dello Stretto e la porta verso la Tracia si aprì del tutto. Gallipoli sarebbe andata perduta nel 1366 con la crociata di Savoia, ma con la seconda conquista del 1376 sarebbe entrata definitivamente sotto dominio ottomano. Altri luoghi annessi nella stessa data: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Morte di Süleyman Paşa, conquistatore della Rumelia", "2dc98228"], "d": ["Süleyman Paşa, figlio maggiore di Orhan Bey e artefice delle conquiste in Rumelia, morì cadendo da cavallo durante una caccia nell'autunno del 1357, la più accolta tra le date 758 (1357), 759 e 760 (1359) date dalle fonti. La morte del principe, che con i suoi passaggi del 1352-1354 aveva fondato la presenza ottomana permanente in Rumelia, lasciò al fratello Murad il posto nella linea di successione. Il mausoleo di Süleyman Paşa, sepolto a Bolayır, rimase il più antico monumento dinastico ottomano in Europa.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Legge del Pençik — posta la base del corpo dei Giannizzeri", "e5877c2d"], "d": ["Dopo le conquiste in Rumelia, su consiglio di Karamanlı Kara Rüstem, tra gli ulema, entrò in vigore il sistema del pençik, che prevedeva di riservare allo Stato un quinto dei prigionieri di guerra o il suo equivalente in denaro. Con l'educazione presso famiglie turche e l'arruolamento di quelli scelti tra questi prigionieri si formò il nucleo di una forza di fanteria permanente direttamente dipendente dal sultano — il corpo dei Giannizzeri. Con questo ordinamento cominciò la trasformazione di un beylik di frontiera fondato sulla cavalleria tribale in uno Stato dotato di esercito centrale.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Discesa nella Tracia occidentale: conquista di Komotini", "9ef69221"], "d": ["Dopo la presa di Edirne le forze di frontiera, volte a ovest della Maritza, al comando di Gazi Evrenos Bey presero Komotini (Gümülcine), centro della Tracia occidentale. La città divenne il quartier generale avanzato da cui Evrenos Bey avrebbe portato le incursioni in Macedonia. Così la parte della Tracia che si estende fino alla costa egea entrò sotto controllo ottomano e si aprì la strada di Salonicco.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna passò al Principato di Dobrugia e divenne capitale", "2bfe73f9"], "d": ["Nel processo di dissoluzione dello zarato bulgaro Varna, sulla costa del Mar Nero, fu annessa al Principato di Dobrugia fondato da Dobrotitsa e fu fatta capitale di questo piccolo Stato.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["A ovest di Filippopoli: annessione di Pazardžik e Ihtiman", "1664d0e1"], "d": ["Dopo la presa di Filippopoli (Filibe) nel 1372, Pazardžik (Tatarpazarcığı), all'estremità superiore della valle della Maritza, e Ihtiman, che teneva il passo aperto su Sofia, furono legate all'amministrazione ottomana. Questa linea, in mano ai signori locali divenuti vassalli dopo la battaglia di Çirmen, fu portata sotto governo diretto, rendendo ininterrotto il percorso Filippopoli-Sofia. Questa avanzata è la preparazione della strada che dodici anni dopo condusse alla conquista di Sofia.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Rivolta di Savcı Bey — rivolta comune del principe e dell'erede bizantino", "75198c33"], "d": ["Savcı Bey, figlio di Murad I, e Andronico Paleologo, figlio dell'imperatore bizantino Giovanni V, all'inizio del maggio 1373 si ribellarono simultaneamente ai padri a Bursa e a Costantinopoli. Questa alleanza che univa gli eredi delle due dinastie fu rapidamente repressa; Savcı Bey, catturato, fu accecato e giustiziato. La data 787 (1385) indicata dalla tradizione ottomana per la rivolta è errata; l'evento cade subito dopo gli anni in cui Bisanzio entrò nel vassallaggio ottomano e mostra quanto le due corti fossero intrecciate.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Valli dello Struma e del Mesta: annessione di Kjustendil, Petrič, Nevrokop e Drama", "8c0980c4"], "d": ["Le valli dello Struma e del Mesta, in mano ai signori locali serbi e bulgari che avevano cominciato a pagare tributo agli Ottomani dopo la vittoria di Çirmen, furono poste sotto amministrazione ottomana diretta con l'avanzata dei bey di frontiera. Con l'annessione di Kjustendil, Petrič, Nevrokop e Drama si aprì la metà orientale della Macedonia e Salonicco e Serres entrarono nel cerchio d'assedio. L'espansione della Rumelia verso sud-ovest sulla mappa è il risultato di questa operazione.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Fine del beilicato di Eretna e fondazione dello Stato di Kadı Burhâneddin", "60dcaf57"], "d": ["Gli Eretnidi, sorti nel 1335 da un governatorato ilkhanide e che per quarantasei anni governarono l'Anatolia centrale, con centro a Sivas e Kayseri, si dissolsero per rivalità di corte. Dopo aver eliminato i rivali Kılıcarslan e Hacı Şadgeldi, Kadı Burhâneddin, divenuto visir nel maggio 1378, proclamò il proprio sultanato nell'autunno del 1381, pose fine al beilicato e fondò lo Stato che porta il suo nome. Così il vicino orientale degli Ottomani cambiò mano; la linea Sivas-Kayseri sarebbe rimasta per diciassette anni nelle mani di Kadı Burhâneddin.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Tamerlano prese Herat: fine della dinastia Kart e passaggio del Khorasan ai Timuridi", "15f6019e"], "d": ["Il Khorasan nel 1380 era frammentato dalla lotta tra Sarbadar, Kart e Muzaffaridi. Dopo aver inviato nella regione il figlio Mîrân Şah, Tamerlano marciò in persona su Herat e, dopo averla assediata per un periodo, ricevette la città dal sovrano kart Gıyâseddin Pîr Ali. La rivolta scoppiata dopo la sua partenza fu repressa nel sangue da Mîrân Şah e fu posta fine alla dinastia Kart, che regnava a Herat dal 1255. L'intero Khorasan, da Mashhad a Nishapur, entrò in questa data sotto amministrazione timuride.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Avanzata nell'interno della Macedonia: conquista di Manastır e Ocrida", "63bb7838"], "d": ["Manastır (Bitola), sulla Via Egnatia, e Ocrida, sulla riva del lago, entrarono nell'amministrazione ottomana durante le incursioni in direzione dell'Albania. Entrambe erano punti chiave della strada che si estendeva fino all'Adriatico; Ocrida era inoltre la più antica sede arcivescovile ortodossa dei Balcani. Il TDV registra che per la data della conquista di Ocrida non si hanno informazioni certe, che sono state proposte le date 787 (1385) e 797 (1395), dopo la morte di Marko Kraljević; qui si è assunto il 1385. Manastır sarebbe stata nei secoli seguenti uno dei più importanti centri militari della Rumelia.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Battaglia di Savra — aperte le porte dell'Albania", "dda6671b"], "d": ["Per l'appello di aiuto del signore albanese Karlo Topia, stretto contro la dinastia Balšić, le forze ottomane sconfissero nella piana di Savra l'esercito di Balša II; Balša perse la vita sul campo. Questa battaglia, combattuta su invito di un signore locale, diede agli Ottomani la prima influenza stabile nelle terre albanesi che si estendevano fino alle coste adriatiche. Questa politica, che sfruttava la contesa tra i signori della regione, sarebbe stata per il secolo seguente il metodo immutabile delle conquiste balcaniche.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["La «campagna dei tre anni» di Tamerlano: presa dell'Azerbaigian e dell'Iran settentrionale", "2a98ec51"], "d": ["Tamerlano, che durante le campagne del Khorasan aveva visto da vicino la frammentazione dell'Iran, nel 788 (1386) marciò a ovest. Nell'operazione del 1386-1388, detta «campagna dei tre anni», passò per Mazandaran, Luristan e Georgia in Azerbaigian e raggiunse il Karabakh; Tabriz, Ardabil, Urmia e Nakhchivan entrarono sotto amministrazione timuride. La presa dell'Iran settentrionale e dell'Azerbaigian fu l'inizio anche di una lunga contesa con l'Orda d'Oro, come era stata un tempo tra l'ulus di Jochi e gli Ilkhanidi.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Battaglia di Frenkyazısı e assedio di Konya — prima campagna di Karaman", "af4e5d77"], "d": ["Murad I partì personalmente in campagna contro Karamanoğlu Alâeddin Ali Bey, suo genero, che era infastidito dall'espansione ottomana nell'Anatolia occidentale; nella battaglia combattuta nel luogo detto Frenk Yazısı l'esercito ottomano, addestrato ed esperto, sconfisse le forze karamanidi. Poi fu assediata la fortezza di Konya, ma, grazie al perdono concesso ad Alâeddin Bey, il beylik non fu del tutto eliminato. Questa campagna è il primo atto della lunga resa dei conti tra Ottomani e Karaman che sarebbe durata un secolo e finita solo con l'annessione definitiva nel 1468.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Muş passa dall'amministrazione Qara Qoyunlu a quella di Tamerlano (789/1387)", "ed2e7a11"], "d": ["Muş, passata all'amministrazione Qara Qoyunlu dopo il periodo mongolo, nel 789 (1387) passò sotto l'amministrazione di Tamerlano, che possedeva i territori Qara Qoyunlu. Nell'atlante Muş è registrata in quest'anno come passata dai Qara Qoyunlu ai Timuridi.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Fondazione dell'arsenale di Gallipoli — nascita della flotta ottomana", "47546241"], "d": ["Il primo arsenale organizzato dello Stato ottomano fu fondato nel 1390 da Yıldırım Bayezid a Gallipoli, nel luogo dell'arsenale lasciato da Bisanzio. Gli Ottomani, ereditata la tradizione marinara dei beylik dell'Anatolia occidentale, divennero così per la prima volta una potenza navale che costruiva da sé le proprie navi. Situato nel punto chiave dello stretto dei Dardanelli, l'arsenale servì per un secolo e mezzo, dall'assedio di Costantinopoli alle campagne egee, come principale base della flotta ottomana.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Il Hamîd-ili annesso agli Ottomani: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Yıldırım Bayezid, partito in campagna in seguito all'attacco di Karamanoğlu Alâeddin Bey al Hamîd-ili e alle lagnanze della popolazione, si impadronì dell'intero restante territorio degli Hamîdoğulları e ne affidò l'amministrazione al figlio İsa Çelebi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Fine della dinastia muzaffaride: Shah Mansur sconfitto davanti a Shiraz", "5fd14eb8"], "d": ["Shah Mansur, ultimo forte sovrano dei Muzaffaridi, che dal 1318 regnavano a Yazd, Fars, Isfahan e Kerman, si unì ai parenti e mosse contro Tamerlano. Nella battaglia presso Shiraz, per il passaggio al nemico di uno dei suoi emiri, perse la maggior parte delle sue forze e, sconfitto, fu ucciso. Poiché Tamerlano fece poi uccidere anche tutti i membri della dinastia, il dominio muzaffaride ebbe fine e Fars e Kerman furono annessi all'amministrazione timuride.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Incorporazione di Amasya nelle terre ottomane", "fe2860cf"], "d": ["Durante la campagna di Bayezid I Yıldırım nell'Anatolia centrale, l'emiro di Amasya, assediato, consegnò la città agli Ottomani e Bayezid entrò in città nel 1393. Il sultano ne lasciò l'amministrazione al figlio Mehmed Çelebi; come sangiaccato di principe, Amasya divenne da allora uno dei più importanti centri di formazione della dinastia ottomana. Altri insediamenti che cambiarono mano nella stessa data: Ladik (Amasya), Merzifon, Osmancık, Çorum. Questa scelta sarebbe stata decisiva nel futuro Interregno; Çelebi Mehmed avrebbe condotto la sua lotta per riunificare lo Stato proprio da questa base di Amasya.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Tamerlano conquistò Baghdad — i Gialayridi fuggirono in Anatolia", "4d5602b3"], "d": ["Tamerlano, dopo un lungo assedio, prese Baghdad; il sultano gialayride Ahmed, signore della città, fuggì a ovest e si rifugiò prima presso i Mamelucchi e poi alla corte ottomana. L'espansione di Tamerlano verso ovest venne così per la prima volta a diretto contatto con la sfera d'influenza ottomana. Da qui comincia il primo anello dell'ostilità tra i due sovrani.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Presa di Varna sulla costa del Mar Nero", "a84b2abf"], "d": ["Mentre si stringeva la morsa sui territori dello zarato bulgaro tra Danubio e Mar Nero, Varna, il maggiore porto della costa, passò all'amministrazione ottomana. La presa del porto aprì la strada dell'avanzata verso la Dobrugia e diede agli Ottomani il primo grande approdo sulla costa occidentale del Mar Nero. Varna sarebbe stata anche teatro, cinquantun anni dopo, della vittoria del 1444 in cui l'esercito crociato fu annientato.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["La zona di Nevşehir e Ürgüp passa dai Karamanidi agli Ottomani", "06ff59e8"], "d": ["Nelle campagne di Yıldırım Bayezid contro i Karamanidi, la zona di Nevşehir (Muşkara) e Ürgüp nel 800/1398 passò sotto amministrazione ottomana; dopo la Battaglia di Ankara nel 1402 Tamerlano restituì la regione ai Karamanidi.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Caduta dello Stato di Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, caduto prigioniero dell'aqquyunlu Karayülük Osman Bey, offrì di essere liberato in cambio della resa di Sivas, ma la popolazione della città resistette e il sultano fu giustiziato davanti alle mura. I notabili di Sivas, benché avessero portato a capo il figlio Alâeddin Ali Çelebi, di fronte alla pressione degli Aqquyunlu chiesero aiuto a Yıldırım Bayezid; le forze ottomane al comando di Süleyman Çelebi sconfissero Karayülük e dominarono la città. Così lo Stato di Kadı Burhâneddin scomparve dalla storia e Sivas, Tokat, Niksar e Kayseri furono annesse ai territori ottomani. Altri luoghi annessi nella stessa data: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Braccio di ferro di Tamerlano: rifiutata la restituzione dei fuggitivi", "33790bc8"], "d": ["Per la pressione di Tamerlano il sultano gialayride Ahmed e il capo dei Qaraqoyunlu Kara Yûsuf si rifugiarono nelle terre ottomane; Tamerlano chiese la consegna di questi due fuggiaschi, Yıldırım Bayezid rifiutò. Allora i due sovrani cominciarono a scambiarsi lettere contenenti gravi ingiurie reciproche. Il terreno ideologico della guerra fu preparato da questa corrispondenza prima che un solo soldato si muovesse.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Yıldırım Darüşşifası a Bursa — primo ospedale ottomano", "5f0dc59a"], "d": ["Yıldırım Bayezid, negli anni in cui faceva costruire a Bursa la magnifica Grande Moschea, dotò la città anche di un dârüşşifa; fu l'anello dedicato alla medicina del vasto programma di opere pie composto da imaret, madrasa, han e ponte. Questo edificio, primo ospedale fondato dallo Stato, assolvendo anche la funzione di scuola di medicina che formava medici, determinò il modello delle istituzioni sanitarie ottomane. L'opera, completata solo due anni prima del disastro di Ankara, è tra gli ultimi anelli della visione di Yıldırım di trasformare Bursa in capitale imperiale.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Tamerlano rase al suolo Sivas", "f4d79de6"], "d": ["Tamerlano, che marciava su Sivas guidato dall'aqquyunlu Karayülük Osman Bey e dall'emiro di Erzincan Mutahharten, assediò la città per diciotto giorni e, dopo averla ricevuta con la promessa che non sarebbe stato versato il sangue di nessuno, compì un grande massacro; fece gettare i difensori nei fossati e li fece ricoprire di terra ancora vivi. Furono distrutte le opere importanti della città, a cominciare dalle mura, e Sivas crollò demograficamente. È il primo grande colpo inferto da Tamerlano alle terre ottomane, due anni prima della battaglia di Ankara.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid riprese Erzincan e Kemah", "7047ca08"], "d": ["Yıldırım Bayezid, approfittando della partenza di Tamerlano per la campagna di Siria, tolse Erzincan e Kemah all'emiro di Erzincan Mutahharten, vassallo di Tamerlano. Sebbene Bayezid non fosse intervenuto nella distruzione di Sivas, questa mossa significava sfidare direttamente la sfera d'influenza di Tamerlano nell'Anatolia orientale. Da allora il rapporto tra i due sovrani divenne irreparabile.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum di Tamerlano da Tabriz — quattro condizioni", "3e1ac50e"], "d": ["Tamerlano, con un ambasciatore inviato da Tabriz, comunicò quattro condizioni: la restituzione di Kemah a Mutahharten, la restituzione ai proprietari dei territori sottratti ai bey anatolici, l'invio in ostaggio di un principe ottomano con accettazione di berretto e cintura come segno di sudditanza e la consegna di Kara Yûsuf. Bayezid non ne accettò nessuna; nonostante l'insistenza degli statisti e la mediazione di Mutahharten, i negoziati crollarono. Tamerlano era deciso a chiudere in modo definitivo la questione anatolica prima di partire per la campagna di Cina.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Ricostituiti i Saruhanoğulları — Manisa esce dal dominio ottomano", "ac747b05"], "d": ["Tre settimane dopo la disfatta di Ankara, con l'appoggio di Tamerlano, Orhan Bey salì alla testa del beylik e il territorio di Saruhan tornò indipendente. La regione centrata su Manisa, dodici anni dopo l'annessione ottomana del 1390, uscì dalla mappa. È una delle prime applicazioni, di data sicuramente nota, della politica di Tamerlano di far rivivere i beylik.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["L'emiro Süleyman fuggì in Rumelia con il tesoro di Stato", "0a2b7363"], "d": ["L'emiro Süleyman, preso con sé il tesoro di Stato, gli archivi, la famiglia e i fratelli che erano a Bursa, da Gemlik passò con una nave a Güzelcehisar (Anadoluhisarı), di lì raggiunse Gallipoli e proclamò il proprio dominio a Edirne. Il trasferimento in Rumelia dell'archivio e del tesoro di Stato è l'inizio dello spostamento, per una generazione, del baricentro ottomano nei Balcani. Sulla mappa la Rumelia da questa data è disegnata con il colore proprio dell'emiro Süleyman.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Tamerlano ristabilì i beilicati dell'Anatolia — si dissolse l'unità turca", "15187774"], "d": ["Tamerlano, dopo la vittoria di Ankara, restituì alle loro antiche terre i bey che erano con lui. Ai bey Karamanoğlu Mehmed e Ali furono dati la provincia di Karaman e inoltre Kayseri, Kırşehir, Sivrihisar e Beyşehir; a Germiyanoğlu Yakub Bey II, Kütahya e la provincia di Germiyan; a Candaroğlu İsfendiyar Bey, oltre alla linea Kastamonu-Sinope, Çankırı e Kalecik. Anche le province di Aydın, Menteşe e Teke tornarono alle loro antiche dinastie. L'unità turca dell'Anatolia che Bayezid I Yıldırım aveva costruito in dieci anni si dissolse in una sola estate; sulla mappa questi beilicati ricompaiono con i propri colori. Altri insediamenti che cambiarono mano nello stesso processo: Aksaray, Denizli, Ereğli (Konya), Ermenek, Ilgın, Karapınar, Kayseri, Konya, Kırşehir, Kütahya, Sivrihisar, Söke.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Tamerlano prese Smirne ai cavalieri di San Giovanni", "66dd1dd4"], "d": ["Tamerlano, disceso a ovest per Kütahya, Denizli, Aydın, Ayasuluk e Tire, assediò e prese Smirne costiera, in mano ai cristiani dal 1344. Impadronitosi in breve tempo di questa fortezza che Yıldırım Bayezid non era riuscito a prendere per anni, dopo aver preso anche le fortezze circostanti lasciò il territorio di Aydın ai vecchi proprietari e tornò a est. La città passò da allora sotto l'amministrazione dell'aydınide Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi si impadronì di Bursa — nacque la parte anatolica", "955128c1"], "d": ["Îsâ Çelebi, ritiratosi dopo la disfatta di Ankara verso Karesi, si impadronì di Bursa mentre Tamerlano era a Smirne. Nell'antica capitale saccheggiata e incendiata dai soldati di Tamerlano proclamò il proprio dominio e fece coniare moneta a suo nome; nel gennaio 1403 era riconosciuto in Anatolia con il titolo di «sovrano dei Turchi». Sulla mappa questa parte, che si estende lungo la sponda asiatica del Marmara, compare con il colore proprio di Îsâ Çelebi.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Ritiro di Tamerlano dall'Anatolia", "93a98839"], "d": ["Tamerlano, ricevuta la notizia della morte di Yıldırım Bayezid ad Akşehir, considerò concluso il suo lavoro in Anatolia e si volse a est. Rimasero i beylik che dichiaravano fedeltà e i principi ottomani messi gli uni contro gli altri; alcune città, come Sivas, furono lasciate in mano a emiri simili a Mezid Bey, vassallo di Tamerlano. Tamerlano non tornò più in Anatolia, ma questo assetto frammentato da lui creato durò dieci anni.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["L'emiro Süleyman passò in Anatolia: Bursa cadde nelle sue mani", "9b27aa5f"], "d": ["L'emiro Süleyman, saputa la sconfitta di Îsâ Çelebi, passò in Anatolia con un esercito potente insieme a Çandarlı Ali Pascià e prese Bursa; i registri del marzo 1404 mostrano che anche Karadeniz Ereğli era sotto la sua amministrazione. Di fronte a Süleyman, che in breve tempo dominò sia la Rumelia sia gran parte dell'Anatolia, Çelebi Mehmed non poté resistere. Altri insediamenti passati da Çelebi Mehmed all'emiro Süleyman nello stesso processo: Akyazı, Anadolu Hisarı, Absu (Hypsu), Adranos (Orhaneli), Akhisar (Pamukova), Armutlu, fortezza di Aydos, Ayvalık, Balıkesir, Behramkale (Assos), Bergama, Beykoz, Biga. Sulla mappa, da questa data fino alla riconquista di Bursa da parte di Çelebi Mehmed (1410), le due sponde appaiono in un solo colore, nella parte dell'emiro Süleyman.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Battaglia della pianura di Yenişehir — Çelebi Mehmed si ritirò ad Amasya", "f1568288"], "d": ["Çelebi Mehmed, che aveva perso Bursa e Ankara, fu sconfitto dall'emiro Süleyman nella pianura di Yenişehir, perse tutti i guadagni nell'Anatolia occidentale e si ritirò alla base di Tokat-Amasya. Dopo questa sconfitta evitò lo scontro diretto e si volse a consolidare la propria autorità nell'interno dell'Anatolia. Così cominciò la più lunga fase silenziosa dell'Interregno.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["L'emiro Süleyman prese Ankara a Çelebi Mehmed", "d6a2acd6"], "d": ["L'emiro Süleyman nel 1406 assediò Ankara, rimasta in mano a Çelebi Mehmed dopo il ritiro di Tamerlano dall'Anatolia. Il comandante della fortezza Yâkub Bey resistette per un periodo, ma con uno stratagemma del gran visir Çandarlı Ali Paşa consegnò la fortezza a Süleyman. Allora Çelebi Mehmed, accordatosi con Karamanoğlu Mehmed Bey, si mosse contro Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed riprese Sivas al timuride Mezid Bey", "90079b0c"], "d": ["Dopo l'invasione di Tamerlano l'amministrazione di Sivas era stata lasciata a Mezid Bey, vassallo di Tamerlano. Çelebi Mehmed, ad Amasya, inviò il comandante Bayezid Paşa a prendere la città e, dopo una forte resistenza, Sivas passò per la seconda volta alla dinastia ottomana. Così la parte di Mehmed, sei anni dopo la battaglia di Ankara, raggiunse a oriente il suo antico confine.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Fine della dinastia artuqide: consegna di Mardin ai Qaraqoyunlu", "15b06f33"], "d": ["Gli Artuqidi, che regnavano a Mardin dal 1106 e costituivano il ramo più longevo della dinastia, non resistettero alla pressione degli Aqquyunlu. Melik Ahmed, resosi conto di non poter difendere la città, si accordò con il sovrano qaraqoyunlu Kara Yûsuf e gli consegnò Mardin. Così il dominio artuqide di oltre tre secoli ebbe fine; Mardin e dintorni furono teatro della lotta tra Qaraqoyunlu e Aqquyunlu fino al passaggio agli Ottomani un secolo dopo.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Battaglia di Yanbolu — Mûsâ Çelebi entrò a Edirne", "8f978408"], "d": ["Mûsâ Çelebi, passato in Rumelia attraverso la Valacchia, con l'appoggio valacco e serbo sconfisse a Yanbolu le forze dell'emiro Süleyman ed entrò a Edirne. Durante l'Interregno la Rumelia uscì così per la prima volta dalle mani dell'emiro Süleyman. Ma il suo dominio non fu duraturo; quattro mesi dopo, sconfitto a Kosmidion, si sarebbe ritirato nell'interno dei Balcani.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Battaglia di İnceğiz — prima sconfitta di Çelebi Mehmed in Rumelia", "3c35cd43"], "d": ["Çelebi Mehmed, passato in Rumelia con le navi bizantine, entrò in battaglia a İnceğiz con Mûsâ Çelebi; Mûsâ con i settemila giannizzeri al suo comando sconfisse Mehmed e Mehmed fu costretto a tornare in Anatolia. Questa sconfitta lo orientò a una strategia non di scontro diretto ma di attrazione dalla propria parte dei signori di frontiera della Rumelia e del despotato serbo. Con questa diplomazia fu preparato il terreno della vittoria di Çamurlu nove mesi dopo.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Assedio di Konya e accordo con i Karamanoğulları — ripresi Hamîd-ili, Said-ili, Beyşehir, Seydişehir e Akşehir", "0996257e"], "d": ["Contro i Karamanoğulları, che durante il Fetret Devri attaccavano i territori ottomani e avevano assediato e incendiato Bursa, Çelebi Mehmed organizzò una grande campagna e assediò Konya nel Muharram 818. Karamanoğlu Mehmed Bey II fu costretto a chiedere la pace; in seguito all'accordo Hamîd-ili (zona di Isparta) e Said-ili furono annessi di nuovo ai territori ottomani, anche Beyşehir, Seydişehir e Akşehir furono restituite; anche Sivrihisar, data da Tamerlano ai Karamanoğulları nel 1402, tornò agli Ottomani. Questa campagna, con cui cominciò il rammendo dell'unità anatolica dispersa dalla battaglia di Ankara, è una delle ragioni concrete per cui Çelebi Mehmed è considerato «secondo fondatore».", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Presa di Smirne all'aydınide Cüneyd Bey", "2377ca51"], "d": ["Smirne, centro dell'aydınide Cüneyd Bey, che durante l'Interregno cambiava continuamente parte tra i principi, fu presa da Çelebi Mehmed dopo un assedio di dieci giorni; Cüneyd, perdonato, fu mandato al sancak di Nicopoli. La città, restituita agli Aydınoğulları da Tamerlano nel 1402, tornò così agli Ottomani dopo tredici anni. Cüneyd l'avrebbe ripresa nel 1422 e la questione sarebbe stata chiusa solo nel 1424-1426 da Murad II.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Esecuzione di Torlak Kemal — Saruhan definitivamente ottomana", "8a09dbf1"], "d": ["Torlak Kemal, che conduceva il ramo dell'Anatolia occidentale del movimento dello sceicco Bedreddin, fu sconfitto nella zona di Manisa e giustiziato. Da questa data la regione di Saruhan entrò in modo definitivo sotto controllo ottomano e il beylik fatto rivivere da Tamerlano nel 1402 scomparve dalla storia. Furono così eliminati gli ultimi residui politici dell'Interregno nell'Anatolia occidentale.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Conquista di Valona, Berat e Kanina", "1e1949b8"], "d": ["Gli Ottomani nel 1417 posero sotto il proprio dominio Valona, sulla costa adriatica, insieme alla città di Berat, nell'interno del paese, e alla fortezza di Kanina. Un anno dopo il tentativo veneziano di riprendere la città fallì e vi fu stabilita un'organizzazione di sancak, rendendo duraturo il dominio ottomano. La presa di Valona, facendo per la prima volta degli Ottomani proprietari diretti di un porto sull'Adriatico, diede loro un trampolino oltremare di fronte all'Italia.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Ripresa dell'Anatolia centrale: Kayseri e Kırşehir", "204eacb3"], "d": ["Le città dell'Anatolia centrale cadute in mano ai Karamanidi durante l'Interregno tornarono all'amministrazione ottomana nelle campagne di Çelebi Mehmed per ricomporre lo Stato. Con l'annessione di Kayseri e Kırşehir il bacino del Kızılırmak, perduto nella battaglia di Ankara, fu in gran parte ripreso. Questa avanzata è la continuazione della politica di orientamento verso est iniziata con l'assedio di Konya quattro anni prima.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["I Mamelucchi diedero Kayseri a Nâsırüddin Muhammed dei Dulkadır", "aad4b00c"], "d": ["L'esercito mamelucco, partito in campagna contro Karamanoğlu Mehmed Bey, occupò Kayseri; il comandante mamelucco, lasciata la città e i dintorni a Nâsırüddin Muhammed dei Dulkadır, tornò nel suo paese.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Morte di Mehmed I e ascesa al trono di Murad II", "98acac77"], "d": ["Mehmed I, che aveva posto fine al Periodo dell'Interregno (Fetret Devri) e riunito di nuovo il territorio ottomano in una sola mano, morì a Edirne il 25 giugno 1421 e il figlio Murad salì al trono a Bursa. Secondo l'accordo preso con Bisanzio prima della morte, i figli minori sarebbero stati inviati come ostaggi presso l'imperatore e l'imperatore non avrebbe liberato il pretendente al trono Mustafa Çelebi, che teneva con sé; Murad II rifiutò di inviare i fratelli all'imperatore.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Liquidazione definitiva dei Tekeoğulları: presa di Antalya", "e65565b2"], "d": ["Il Beylik dei Tekeoğulları, ricostituito dopo la battaglia di Ankara per volontà di Tamerlano, finì con l'assedio di Antalya da parte delle forze ottomane al comando di Hamza Bey; l'ultimo uomo importante del beylik, Osman Çelebi, fu eliminato. Così il territorio di Teke sulla costa mediterranea fu annesso in modo definitivo agli Ottomani dopo una separazione di ventun anni. Il beylik, come ramo staccatosi dagli Hamîdoğulları, regnava ad Antalya dal 1321.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Campagna di Turahan Bey in Morea e distruzione del Muro Esamilio", "c6c2706d"], "d": ["Poiché Bisanzio aveva sostenuto il pretendente rivale al trono Mustafa Çelebi, Murad II inviò Turahan Bey in Morea. Turahan Bey, abbattuto il muro Esamilio, che sbarrava da parte a parte l'istmo di Corinto, entrò nella penisola e causò grandi devastazioni. La pace fu ottenuta a condizione che il muro non fosse più ricostruito e che fosse pagata un'imposta annua; il despotato di Morea fu così lasciato militarmente indifeso e il terreno della conquista definitiva del 1460 fu preparato trentasette anni prima.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["I monasteri dell'Athos sotto protezione ottomana", "562de5ea"], "d": ["Negli anni in cui Salonicco era assediata, la repubblica monastica dell'Athos, sul dito orientale della Calcidica, si rivolse a Murad II chiedendo protezione e accettò il dominio ottomano. Furono garantiti i diritti di proprietà e di culto dei monaci; i monasteri, in cambio di un'imposta, furono lasciati liberi nei propri affari interni. Questo ordinamento fu l'esempio più longevo del rapporto di protezione stabilito dagli Ottomani con le istituzioni ortodosse e durò cinque secoli.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Annessione del Beylik dei Tâceddinoğulları: Niksar", "370ffd47"], "d": ["Per la pressione del beylerbey di Amasya Yörgüç Paşa, Tâceddinoğlu Hüsâmeddin Hasan Bey consegnò nell'830 (1427) le chiavi del suo paese, con centro a Niksar; gli fu dato un sancak in Rumelia. Il beylik, fondato nella seconda metà del XIV secolo e i cui confini giunsero a tratti fino a Kelkit, Amasya, Samsun, Ordu e Giresun, finì così. Nello stesso anno furono censiti anche i territori degli Hacıemiroğulları e legati al sancak di Canik; l'epoca dei beylik del Mar Nero centrale si chiuse.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Cessione di Belgrado all'Ungheria — Trattato di Tata", "62481183"], "d": ["Alla morte del despota serbo Stefan Lazarević, in forza del Trattato di Tata tra il re d'Ungheria Sigismondo e l'erede Đurađ Branković, la fortezza di Belgrado fu ceduta all'Ungheria. La fortezza, che sorge alla confluenza di Danubio e Sava e fino ad allora era stata in mano al despotato serbo, era per gli Ottomani la serratura della porta d'accesso all'Europa centrale. Questa cessione fece di Belgrado per cento anni il più duro ostacolo all'avanzata ottomana: gli assedi del 1440 e del 1456 sarebbero falliti e la fortezza sarebbe caduta solo nel 1521.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin passò dal presidio qaraqoyunlu all'aqquyunlu Karayülük Osman Bey", "d82bc97f"], "d": ["I Qaraqoyunlu governarono con governatori Mardin, presa da Kara Yûsuf nel 1409; l'emiro Nâsır, lasciato come presidio, nell'835 (1432) consegnò la città all'aqquyunlu Karayülük Osman Bey. Il governo aqquyunlu durò fino all'inizio del XVI secolo.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["I Karamanidi presero Kayseri ai Dulkadır", "2b09e8e8"], "d": ["Il bey di Karaman, con la vittoria ottenuta contro i Dulkadır, annesse al proprio paese Kayseri, Ürgüp, Develi Karahisarı e Uçhisar.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Evento di Buçuktepe — prima rivolta giannizzera e ritorno al trono di Murad II", "6388dda1"], "d": ["L'evento di Buçuktepe, scoppiato a Edirne e prima rivolta giannizzera conosciuta dalla storia, cominciò con la richiesta di aumentare di mezzo akçe le paghe e si concluse con la deposizione del giovane Mehmed II. Murad II l'8 Safar 850 partì in fretta da Manisa e iniziò il suo secondo sultanato. L'evento fu il primo segno che il corpo dei kapıkulu era ormai una forza con voce in capitolo sul trono e plasmò la cautela di tutta la vita del Conquistatore verso i giannizzeri.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Annessione della costa dell'Epiro: Arta e Preveza", "796f7ecf"], "d": ["Diciannove anni dopo la resa di Ioannina nel 1430, anche Arta e Preveza, sulla parte costiera del despotato d'Epiro, entrarono nell'amministrazione ottomana. Fu così messo sotto controllo il golfo di Ambracia, aperto sul Mar Ionio, e il collegamento marittimo di Ioannina fu completato. Preveza è il punto chiave della baia che novant'anni dopo avrebbe dato il nome alla vittoria di Barbarossa passata alla storia.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Morte di Murad II e seconda ascesa di Mehmed II", "8f8256ad"], "d": ["Murad II, ammalatosi dopo le nozze del figlio, morì a Edirne il 1° Muharram 855 (3 febbraio 1451). Mehmed II, di diciannove anni, salì per la seconda volta al trono ottomano il 16 Muharram 855 (18 febbraio 1451) — questa volta in modo permanente. Il ritorno del giovane sovrano deposto cinque anni prima a Buçuktepe è l'inizio di un regno che due anni dopo sarebbe stato coronato dalla conquista di Costantinopoli e che avrebbe trasformato il Beylik ottomano in un impero mondiale.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Primo assedio di Caffa da parte delle forze congiunte ottomano-crimeane", "e346d163"], "d": ["Nel giugno 1454 il khan di Crimea Hacı Giray, accordatosi con Mehmed il Conquistatore, assediò Caffa da terra con 7000 cavalieri; una flotta ottomana di cinquanta-sessanta galee si dispose al largo. La genovese Caffa fece togliere l'assedio pagando un tributo e la conquista definitiva fu rinviata di ventun anni, al 1475. Questa prima operazione congiunta fu il primo esempio della cooperazione militare ottomano-crimeana che si sarebbe ripetuta nella conquista definitiva di Caffa.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Presa delle isole dell'Egeo settentrionale: Tenedo, Imbro e Taso", "76575895"], "d": ["Subito dopo la conquista di Costantinopoli Mehmed il Conquistatore, per mettere al sicuro la rotta marittima della nuova capitale, si volse alle isole all'imboccatura egea dello stretto dei Dardanelli; Tenedo e Imbro furono prese a Bisanzio, Taso alla famiglia Gattilusio, di origine genovese. Queste isole, che bloccano le due sponde dello stretto, furono da allora il primo anello della linea di approvvigionamento e difesa di Costantinopoli. Per gli interventi delle flotte pontificia e veneziana il dominio andò e venne per un periodo e si consolidò solo nel 1459.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Conquista del Kosovo: presa di Pristina e Novi Pazar", "d7ed2345"], "d": ["L'esercito ottomano, marciando contro il Despotato serbo, prese Pristina, nella piana del Kosovo, e Novi Pazar (Yenipazar), centro della regione di Raška; nella stessa operazione fu presa anche Novo Brdo, celebre per le miniere d'argento. Così la metà meridionale della Serbia fu legata all'amministrazione ottomana diretta e il despotato di Smederevo fu staccato dai suoi territori centrali. Questa conquista fu il passo decisivo sulla via dell'annessione completa della Serbia quattro anni dopo.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["İpek (Peć) entrò nell'amministrazione ottomana — uno dei centri del sancak di Dukakin", "19511588"], "d": ["Nel 1455, subito dopo la campagna di Serbia di Mehmed il Conquistatore, İpek (Peć), centro del patriarcato serbo, passò all'amministrazione ottomana; nelle fonti ottomane non vi è alcuna registrazione di questo passaggio. La località divenne col tempo una piccola cittadina musulmana e una delle residenze del sancak bey nel sancak di Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Conquista di Enez e Samotracia — completamento della costa della Tracia occidentale", "106e723b"], "d": ["Enez, alla foce della Maritza, fu presa alla famiglia Gattilusio, di origine genovese, che la teneva da ottant'anni; nella stessa operazione fu presa anche l'isola di Samotracia, legata ad essa. Con la caduta di Enez la fascia costiera della Tracia occidentale, da Salonicco a Gallipoli, divenne territorio ottomano ininterrotto. In mano alla famiglia Gattilusio restò solo Mitilene, che sarebbe stata presa sei anni dopo.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Fallimento dell'assedio di Belgrado", "3d53a604"], "d": ["Mehmed il Conquistatore, dopo la conquista di Costantinopoli, assediò Belgrado, considerata la chiave dell'Europa centrale; ma i rinforzi portati sul Danubio da Giovanni Hunyadi e i volontari raccolti dal predicatore crociato Capistrano impedirono la caduta della fortezza. Il sultano, nonostante l'eroismo personale mostrato davanti all'assedio, ferito, dovette ritirarsi. Questo fallimento chiuse per sessantacinque anni la frontiera ungherese all'avanzata ottomana; Belgrado sarebbe stata presa solo nel 1521 da Solimano.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Conquista della Morea settentrionale: Patrasso", "c08a8509"], "d": ["Le forze di Mehmed il Conquistatore, rivolte contro il despotato di Morea negli stessi anni dell'annessione della Serbia, presero Patrasso, nel nord-ovest della penisola. Questo porto, che controlla l'imboccatura del golfo di Corinto, è la chiave dell'ingresso terrestre in Morea; la sua presa preparò il terreno alla conquista definitiva due anni dopo. La città era l'ultimo grande scalo attraverso cui i despoti bizantini mantenevano i contatti con il mondo latino.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Presa della costa occidentale del Mar Nero: Amasra", "f43608fc"], "d": ["Amasra, colonia fortificata genovese sul Mar Nero occidentale, si arrese senza resistere alla pressione congiunta delle forze navali e terrestri di Mehmed il Conquistatore. Questo porto sulla costa di Bartın-Zonguldak sorgeva come una sacca latina tra i territori dei Candaroğulları e quelli ottomani; con la sua presa la costa si unificò. La caduta di Amasra è il primo passo della grande campagna del Mar Nero che due anni dopo (1461) si sarebbe rivolta a Sinope e Trebisonda.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Conquista dell'isola di Lesbo (Mitilene)", "fe17aeba"], "d": ["L'esercito ottomano al comando di Mehmed il Conquistatore, nel Dhu al-Hijja 866, dopo un assedio breve ma violento, tolse Lesbo alla famiglia Gattilusio, di origine genovese, e l'annesse. La caduta della più grande isola dell'Egeo settentrionale liquidò anche l'ultima importante base dei Genovesi nella regione. L'isola, per la vicinanza alla costa anatolica, avrebbe d'ora in poi servito da avamposto della flotta ottomana ed è anche entrata nella storia della marineria come luogo in cui crebbero i fratelli Barbarossa.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Inizio della guerra ottomano-veneziana di sedici anni", "563ddb68"], "d": ["I Veneziani, per fermare l'avanzata ottomana in Morea e nell'Egeo, nel 1463 iniziarono la guerra alleandosi con i governanti di Karaman e degli Aqquyunlu. Questa strategia di accerchiamento, costituita da Uzun Hasan a est, Venezia a ovest e Karaman nel mezzo, costrinse il Conquistatore a combattere contemporaneamente su più fronti. La lotta di sedici anni avrebbe compreso tutte le grandi operazioni dell'epoca, da Otlukbeli alle campagne d'Albania, e sarebbe finita solo con il trattato di Costantinopoli del 1479.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Conquista di gran parte dell'Erzegovina: Trebinje e Mostar", "f54c0100"], "d": ["I territori del duca d'Erzegovina Stjepan Vukčić-Kosača, che aveva stabilito un'amministrazione separata dalla Bosnia, tre anni dopo la caduta del Regno di Bosnia passarono in gran parte all'amministrazione ottomana: al sud Trebinje fu presa nel 1466 «insieme a quasi tutta la regione dell'Erzegovina». Anche Mostar, sorta intorno alle due piccole fortezze del ponte sulla Neretva, deve essere stata presa poco prima della conquista di Blagaj, centro dell'Erzegovina, nel 1466-1468; è registrata con il nome «Köprülü Hisar» nel censimento riassuntivo della Bosnia del 1468-1469. La conquista dell'Erzegovina con le fortezze restanti del ducato fu completata nel 1483.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Seconda campagna d'Albania — marcia personale del Conquistatore contro Skanderbeg", "9cdd2bfa"], "d": ["Per spezzare la resistenza di Skanderbeg, durata più di un quarto di secolo, Mehmed il Conquistatore organizzò nel 1466-1467 grandi campagne comandate di persona. L'esercito ottomano assediò Kruja e per controllare la regione costruì la fortezza di İlbasan (Elbasan). La campagna, pur spezzando le reni alla resistenza albanese, non riuscì a far cadere la fortezza; per la piena sottomissione della regione sarebbe occorso il decennio successivo alla morte di Skanderbeg.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Le avanguardie Aq Qoyunlu prendono ai Qara Qoyunlu la fortezza di Bingöl", "51b94cbc"], "d": ["Nelle ultime settimane della campagna di Jahan Shah contro Uzun Hasan, le avanguardie Aq Qoyunlu conquistarono la fortezza di Bingöl; con l'uccisione di Jahan Shah il 10 novembre 1467 il dominio Qara Qoyunlu nella regione ebbe fine.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Crollo dello Stato dei Qaraqoyunlu: uccisione di Cihan Şah", "30bc6358"], "d": ["Il sovrano qaraqoyunlu Cihan Şah, sorpreso da un attacco mentre tornava dalla campagna contro Uzun Hasan per l'incalzare dell'inverno, fu ucciso mentre fuggiva tra Bingöl e Kiğı. Dopo questo colpo lo Stato non si riprese; l'ultimo sovrano, Hasan Ali, nel 1469 fu catturato e ucciso da Uğurlu Mehmed, figlio di Uzun Hasan. Il dominio qaraqoyunlu, durato quasi un secolo nell'Anatolia orientale, in Azerbaigian e in Iraq, passò così agli Aqquyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Morte di Skanderbeg — spegnimento della resistenza albanese", "9158c35f"], "d": ["Skanderbeg, cresciuto alla corte ottomana, che dopo la disfatta di Zlatica del 1444 si era ribellato e aveva resistito per oltre un quarto di secolo in Albania, morì a Lezhë, dove si era rifugiato. Questa resistenza, che aveva più volte trattenuto gli eserciti ottomani sotto Murad II e il Conquistatore, con la sua morte perse la guida centrale. Con il crollo del fronte albanese alimentato dal papato e da Venezia, gli Ottomani, nel giro di dieci anni, presero Kruja e Scutari e annessero definitivamente la regione ai propri territori.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Stabilita l'amministrazione ottomana a Kayseri: Gedik Ahmed Pascià pone fine ai Karamanidi", "33cf35fc"], "d": ["Con la fine dei Karamanidi per opera di Gedik Ahmed Pascià nel 1474, Kayseri entrò sotto amministrazione ottomana; la città nel corso del XV secolo era passata di mano tra Dulkadiridi, Ramazanidi e Karamanidi. Con il governo ottomano Kayseri divenne capoluogo di sanjak del beylerbeylik di Karaman.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Samo abbandonata: termina la proprietà genovese (Maona)", "5bdc380c"], "d": ["Secondo il TDV l'isola fu abbandonata dopo il 1475; nel 1479 Mehmed il Conquistatore la conquistò e vi fece costruire una fortezza.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Disfatta di Racova (Vaslui) in Moldavia", "a1a74bf7"], "d": ["Il voivoda di Moldavia Stefano il Grande, attirando in terreno paludoso le forze ottomane al comando del beylerbey di Rumelia Hadım Süleyman Paşa, le sconfisse duramente. Questa disfatta, una delle più gravi sconfitte terrestri dell'epoca del Conquistatore, ebbe grande eco in Europa e diede a Stefano fama nel mondo crociato. Il sultano l'anno seguente sarebbe partito personalmente in campagna per rappresaglia.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Vittoria di Akdere (Valea Albă) — campagna di Moldavia", "45a66791"], "d": ["Mehmed il Conquistatore, partito di persona in campagna per vendicare la disfatta di Racova dell'anno precedente, con l'esercito ottomano inflisse una grave disfatta alle forze moldave nel luogo detto Akdere ed entrò a Suceava, centro del beylik. Ma le fortezze non furono prese; per la scarsità di viveri, la peste scoppiata tra i giannizzeri e i preparativi ungheresi l'esercito dovette ritirarsi. La sottomissione definitiva della Moldavia poté essere ottenuta solo negli anni seguenti, con la presa di Chilia e Akkerman nel 1484.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Conquista di Kruja e completamento dell'Albania", "559a79b4"], "d": ["Con la presa nel 1478, dieci anni dopo la morte di Skanderbeg, di Kruja, Drivasto, Lezhë e Jabljak la conquista dell'Albania fu in gran parte completata. La caduta della fortezza di Kruja, che aveva resistito per anni agli eserciti ottomani ed era il simbolo della resistenza di Skanderbeg, significava la fine dell'alleanza veneziano-albanese nella regione. Scutari, rimasta, sarebbe stata lasciata agli Ottomani con il trattato di Costantinopoli firmato l'anno successivo.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Annessione della penisola di Taman", "4ef917b8"], "d": ["Dopo la presa di Caffa e Kerč' nel 1475, la flotta inviata da Mehmed il Conquistatore sulle coste caucasiche conquistò, con Anapa e Kopa, la genovese Matrega (Tamatarhan) sulla penisola di Taman. Così le due sponde dello stretto furono poste sotto controllo e l'ingresso al Mar d'Azov divenne completamente controllabile. Taman, come porta aperta sul Caucaso settentrionale, fu legata al sancak di Caffa.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Ingresso di Samo sotto amministrazione ottomana (Mehmed il Conquistatore)", "c877bc14"], "d": ["Mehmed il Conquistatore conquistò Samo, vi fece costruire una fortezza e riorganizzò il censimento; la fortezza fu fatta demolire da Bayezid II nel 1483 per ragioni politiche.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Fallimento dell'assedio di Rodi", "35a85c28"], "d": ["Per ordine di Mehmed il Conquistatore la flotta di 160 unità al comando di Mesih Paşa assediò Rodi nella primavera dell'885 (1480) e l'isola restò sotto blocco per tre mesi. I cavalieri di San Giovanni, guidati dal gran maestro Pierre d'Aubusson, nonostante le gravi perdite resistettero con forza; respinto anche l'ultimo grande assalto del 20 Jumada al-ula 885, la flotta si ritirò il 3 agosto. Dopo questo fallimento le mura della città furono rinnovate da cima a fondo e fatte della più forte fortificazione d'Europa e l'isola poté essere presa solo nel 1522 da Solimano.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Icaria (Nikarya) entra sotto l'amministrazione dei Cavalieri di San Giovanni di Rodi", "5cbc2669"], "d": ["Icaria (Nikarya), tra Samo e Chio, dal 1481 al 1521 fu sotto l'amministrazione dei Cavalieri di San Giovanni di Rodi.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Battaglia di Yenişehir — sconfitta di Cem Sultan", "c35abee2"], "d": ["Dopo la morte del Conquistatore i due fratelli che si erano mossi per il trono si trovarono di fronte nella pianura di Yenişehir e Cem Sultan subì una sconfitta decisiva. Il principe, che aveva regnato diciotto giorni a Bursa facendo leggere la khutba a suo nome, dopo la sconfitta fu costretto a rifugiarsi prima a Konya, poi nei territori mamelucchi. Yenişehir avviò la più lunga crisi dinastica della storia ottomana: la questione di Cem per quattordici anni avrebbe paralizzato la politica estera ottomana di fronte all'Europa.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Annessione dell'Erzegovina", "bf247891"], "d": ["Dopo la conquista della Bosnia nel 1463 i territori del Ducato di Erzegovina, rimasto in piedi, passarono per gradi all'amministrazione ottomana: Trebinje e Mostar furono prese nel 1466, il sancak di Erzegovina fu costituito nel 1470 e gli ultimi territori del ducato sulla costa adriatica, con Herceg Novi, furono conquistati all'inizio del 1482 e annessi al sancak. Così la regione montuosa dietro l'Adriatico divenne interamente ottomana e Bosnia ed Erzegovina divennero un unico spazio amministrativo. Il figlio dell'ultimo duca, entrato nella corte ottomana, è Hersekzâde Ahmed Paşa, che sarebbe salito fino al gran visirato.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Zante (Zaklise) lasciata a Venezia dietro tributo annuo", "268a691a"], "d": ["Zante, una delle isole Ionie tolte alla famiglia Tocco alla fine del periodo di Mehmed il Conquistatore, fu lasciata a Venezia dal nuovo sultano, impegnato nella questione di Cem Sultan e in cerca di tranquillità a occidente. L'isola fu affidata a un'amministrazione veneziana che riconosceva la sovranità ottomana e pagava un tributo annuo di cinquecento ducati. Così nel Mar Ionio l'amministrazione diretta ottomana rimase soltanto a Santa Maura (Ayamavra).", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultan si rifugiò a Rodi", "2228d6da"], "d": ["Cem Sultan, il cui tentativo di assediare Konya era fallito, fuggì dall'Anatolia con una trentina di uomini e raggiunse Rodi, dove fu accolto con cerimonia dai cavalieri di San Giovanni. Ma l'ospitalità si trasformò presto in prigionia; il principe, ceduto prima alla Francia e poi al papato, divenne una carta in mano alla politica europea. Bayezid II fu costretto a pagare un compenso annuo in cambio del fatto che il fratello fosse trattenuto e le mosse militari ottomane verso l'Occidente furono sospese fino alla morte di Cem.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Inizio della guerra ottomano-mamelucca (fronte della Cilicia)", "3fe3f0c7"], "d": ["La contesa per l'influenza sui Dulkadıroğulları e l'ostilità lasciata dal rifugio di Cem Sultan in terra mamelucca nel 1485 avviarono tra le due grandi potenze sunnite una guerra destinata a durare sei anni. Negli scontri che si svolsero in Cilicia intorno ad Adana e Tarso le parti non riuscirono a prevalere l'una sull'altra; gli eserciti ottomani subirono alcuni gravi colpi. Questa guerra è la prima fase della frattura nelle relazioni ottomano-mamelucche ed è il prologo del processo che trent'anni dopo si sarebbe concluso con le campagne di Marj Dabiq e Ridaniye di Selim il Severo.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Pace ottomano-mamelucca — mediazione di Tunisi", "60dd6719"], "d": ["Nella guerra ottomano-mamelucca iniziata nel 1485 le parti non ottennero una vittoria decisiva; con la mediazione del sovrano di Tunisi Osman Hafside si giunse a un accordo nel 1491. Il trattato riportò i confini in gran parte a quelli prebellici e la resa dei conti tra i due Stati islamici fu rinviata per una generazione. La lotta logorante di sei anni è tra le ragioni principali della cauta politica estera di Bayezid II e del suo dare peso agli assetti interni anziché volgersi a oriente.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Accoglienza nell'Impero ottomano degli ebrei sefarditi espulsi dalla Spagna", "5c2b5c24"], "d": ["Dopo la caduta di Granada una parte degli ebrei fuggiti dalle persecuzioni dell'Inquisizione in Spagna si rifugiò nelle terre ottomane e fu insediata in varie città. Sotto l'amministrazione ottomana queste comunità sefardite ottennero una libertà che non avevano mai visto fino ad allora: stabilirsi dove volevano, vivere la propria fede, aprire istituzioni educative e costruire nuove sinagoghe. Questa migrazione, che con le conoscenze di stampa, medicina e finanza portate con sé trasformò la vita economica di Salonicco e Costantinopoli, divenne l'esempio più discusso in Europa dell'ordine di tolleranza ottomano.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Morte di Cem Sultan — fine di quattordici anni da ostaggio", "f6588b70"], "d": ["Cem Sultan, ceduto dal papato al re di Francia Carlo VIII, dopo essere partito da Roma il 27 gennaio 1495 morì nel luogo detto Castel Capuana; le fonti registrano che potrebbe essere stato avvelenato da ambienti pontifici. La morte del principe, tenuto per quattordici anni in mano agli Stati europei come carta di minaccia contro gli Ottomani, lasciò finalmente libera la mano di Bayezid II. Infatti il sultano avrebbe poi dichiarato guerra a Venezia e portato la flotta alla sua prima grande vittoria.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Vittoria navale di Sapienza (Zonchio) — primo grande successo navale nel Mediterraneo", "9754aaef"], "d": ["Bayezid II, che con la fine della questione di Cem trovò libera la mano, nel 1499 dichiarò guerra a Venezia; la flotta ottomana, sconfitta la flotta veneziana al largo di Sapienza (Zonchio), ottenne la prima grande vittoria navale nel Mediterraneo. Con questa vittoria la flotta dichiarò di poter ormai opporsi a Venezia sul mare.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Perdita di Cefalonia e Itaca", "60f0f687"], "d": ["Venezia, scossa dalla presa di Modone e Corone, unitasi alla Spagna passò al contrattacco e assediò Cefalonia, in mano ottomana dal 1479. Dopo una resistenza di quarantasette giorni la fortezza cadde, l'isola passò a Venezia insieme a Itaca e per trecento anni non tornò sotto amministrazione ottomana. Questa perdita creò un equilibrio in cui ciò che era stato guadagnato in Morea veniva restituito nello Ionio.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Caduta del Khanato dell'Orda d'Oro e ascesa della Crimea", "0d1dc515"], "d": ["L'ultimo sovrano, Şeyh Ahmed Han (1481-1502), non riuscì a salvare il paese dalla crisi in cui era caduto e il Khanato dell'Orda d'Oro scomparve dalla storia nel 1502 con il colpo del khan di Crimea Mengli Giray. Per le lotte di trono e la frammentazione, sui territori dell'antica Orda d'Oro comparvero i khanati di Crimea, Kazan, Nogai, Astrakhan e Sibir. La vittoria della Crimea, sotto protezione ottomana, rese incontestabile l'influenza ottomana a nord del Mar Nero, mentre il vuoto creatosi nella regione sarebbe stato riempito da Mosca nel secolo successivo.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Fine della guerra ottomano-veneziana e pace", "125b1526"], "d": ["La guerra iniziata nel 1499, che aveva scosso Venezia con Sapienza e con la perdita di Lepanto, Modone e Corone, terminò nel 1502 con la pace. Venezia, perdute le sue più importanti basi in Morea, dovette riconoscere la superiorità ottomana in cambio della conservazione dei privilegi commerciali nel Mediterraneo orientale. Il regno di Bayezid II, considerato cauto, con questa guerra aveva elevato gli Ottomani per la prima volta a una posizione di seria potenza navale nel Mediterraneo.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Rivolta di Şahkulu — insurrezione kızılbaş dalla zona di Teke a Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, che nel 1510 aveva reso manifesta la propria rivolta sotto l'effetto della propaganda safavide in Anatolia, nel marzo 1511 aveva assalito il mercato di Antalya e in aprile aveva sconfitto le forze ottomane a Kütahya e dintorni. Nell'ultimo scontro con il gran visir Hadım Ali Paşa presso Sivas entrambe le parti subirono gravi perdite; morirono sia il gran visir sia il capo della rivolta. Questa insurrezione, che scosse l'autorità dello Stato in Anatolia, mise in luce il vuoto di potere degli ultimi anni di Bayezid II e fu la più forte giustificazione della marcia al trono del principe Selim.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Ritiro di Bayezid II dal trono e ascesa di Selim il Severo", "c4cfab69"], "d": ["Per la pressione del principe Selim, che nella lotta per il trono con i fratelli aveva dietro di sé il sostegno dei giannizzeri, Bayezid II si ritirò dal trono il 24 aprile 1512 e Selim I salì al trono lo stesso giorno come nono sovrano ottomano. L'anziano sultano morì il 25 Rabi' al-awwal 918 (10 giugno 1512) lungo la strada, mentre si recava a Dimetoka, dov'era nato, nel villaggio di Abalar presso Çorlu. Al posto di un regno di trentuno anni cauto e rivolto all'interno subentrò l'epoca di Selim il Severo, che in otto anni avrebbe raddoppiato i confini dell'impero.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Conquista della fortezza di Sinj", "83271ea5"], "d": ["Le forze di akıncı ottomani al confine bosniaco presero al Regno d'Ungheria la fortezza di Sinj, che si spinge nell'entroterra della Dalmazia. Fu un anello iniziale della linea di confine dalmata, che nove anni dopo si sarebbe ampliata con la conquista di Knin e dei dintorni da parte di Gazi Hüsrev Bey; la fortezza sarebbe stata perduta a favore di Venezia nel 1686.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Battaglia di Yenişehir ed eliminazione del principe Ahmed", "e2ed15dd"], "d": ["Selim il Severo sconfisse nella pianura di Yenişehir presso Bursa il fratello maggiore, il principe Ahmed, il più forte rivale al trono, e, fattolo prigioniero, lo eliminò. Così la contesa fraterna in corso dal 1511 si chiuse e la divisione interna in Anatolia ebbe fine. Selim, messe al sicuro le spalle, guadagnò la libertà di volgersi alla questione safavide.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Ingresso di Selim il Severo a Tabriz", "dad2e227"], "d": ["Dopo la vittoria di Çaldıran l'esercito ottomano entrò nella capitale safavide Tabriz e in città la khutba fu letta a nome del sultano. Selim vi restò una settimana e fece trasferire a Costantinopoli una parte degli artisti e degli ulema di Tabriz; questo trasferimento avrebbe influenzato profondamente l'arte di palazzo ottomana. Benché la città fosse abbandonata per l'avvicinarsi dell'inverno e il malcontento dei giannizzeri, a oriente la superiorità safavide era spezzata. Sulla mappa i luoghi che in questo giorno passano agli Ottomani non sono contigui, ed è corretto: Tabriz è un'occupazione militare di nove giorni; la piana di Erzincan si arrese senza combattere durante la campagna, mentre la fortezza di Kemah al suo centro resistette in mano safavide fino al 19 maggio 1515; Siirt fu ripresa ai Safavidi da Halil Bey, melik di Hasankeyf, il quale, liberatosi a Tabriz dalla prigionia dello shah Ismail, aveva fatto atto di obbedienza agli Ottomani — Diyarbakır, che la circonda, rimase safavide fino al 1515 e Hasankeyf fino al 1517.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Muş e Bingöl (Çapakçur) passano dai Safavidi all'amministrazione ottomana", "b0a53b5a"], "d": ["Con la presa dell'Anatolia orientale ai Safavidi dopo Çaldıran, Muş nel 921/1515 entrò sotto amministrazione ottomana; la vicina Çapakçur (Bingöl) fu aggregata agli Ottomani nello stesso processo.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Conquista ai Safavidi della fortezza di Kemah", "73fd8671"], "d": ["Selim il Severo, che al ritorno da Çaldıran aveva passato l'inverno ad Amasya, incaricò Bıyıklı Mehmed Paşa della conquista della poderosa fortezza di Kemah, che teneva il punto di passaggio dell'Eufrate. Al termine dell'assedio, a cui partecipò personalmente il sultano, la fortezza fu tolta ai Safavidi e la porta dell'Anatolia orientale si aprì. Questa conquista è il primo passo concreto che trasformò la vittoria di Çaldıran in un guadagno territoriale duraturo.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Vittoria di Turnadağ — il Beylik dei Dulkadır diventa vassallo ottomano", "fd879145"], "d": ["Le forze ottomane sconfissero nel luogo detto Ördekli, tra Göksun e Andırın, il bey dei Dulkadır Alâüddevle Bozkurt, che durante la campagna di Çaldıran aveva tenuto un atteggiamento ambiguo; Alâüddevle fu ucciso in questa battaglia. Il beylik in questa data non fu annesso: dopo Alâüddevle, Selim il Severo pose alla testa del Beylik dei Dulkadıroğulları Şehsuvaroğlu Ali Bey e il paese con centro a Maraş-Elbistan continuò come beylik vassallo degli Ottomani. Il cuscinetto sul confine mamelucco entrò così sotto controllo ottomano e si aprì la strada della campagna d'Egitto di due anni dopo; l'annessione sarebbe avvenuta dopo l'uccisione di Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Conquista di Âmid (Diyarbakır) e fondazione del beylerbeylik di Diyarbekir", "a6867d5b"], "d": ["Dopo che İdrîs-i Bitlisî ebbe portato dalla parte ottomana i bey curdi sunniti della regione, le forze safavidi non resistettero a un lungo assedio e le chiavi di Âmid furono consegnate a Bıyıklı Mehmed Paşa. La città fu fatta centro del neocostituito beylerbeylik di Diyarbekir. Così il nucleo amministrativo dell'Alta Mesopotamia passò in mano ottomana.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Conquista di Harput — aperta la strada di Diyarbekir", "564eb269"], "d": ["Hüsrev Paşa, beylerbey di Karaman, partito per liberare dall'assedio safavide Diyarbekir, presa dopo Çaldıran, conquistò dopo un assedio di tre giorni la fortezza di Harput, i cui dintorni erano già stati presi da Çerkez Hüseyin Bey. La strada che si estende a est dell'Eufrate fino a Diyarbekir fu così messa al sicuro.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Battaglia di Koçhisar (Kızıltepe) — sconfitta di Kara Han", "9ea9e843"], "d": ["L'esercito ottomano al comando di Bıyıklı Mehmed Paşa sconfisse in una battaglia campale durata un giorno intero, nella località di Koruk della piana di Dede Garkın presso Koçhisar, il governatore safavide Kara Han; la testa mozzata di Kara Han fu inviata all'accampamento del sultano. In seguito le forze ottomane entrarono nella città di Mardin ma vi restarono solo pochi giorni e ripartirono; la fortezza di Mardin, tenuta dai presidi safavidi, poté essere presa in consegna solo un anno dopo. Questa vittoria, assicurando il confine meridionale di Selim, gli rese possibile volgersi alla campagna d'Egitto. Altri luoghi annessi nella stessa data: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Partenza di Selim il Severo da Costantinopoli per la campagna d'Egitto", "ac258b4b"], "d": ["Selim il Severo partì da Costantinopoli in apparenza con i preparativi di una nuova campagna orientale contro i Safavidi e si diresse a sud passando da Akşehir. Il fatto che il sultano mamelucco Qansuh al-Ghawri fosse entrato in contatto con lo shah Ismail e minacciasse il fianco orientale ottomano avrebbe portato in breve tempo a cambiare l'obiettivo. La campagna è l'inizio della grande operazione che sarebbe durata due anni e avrebbe trasformato gli Ottomani in un impero mediorientale.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Presa di Zabid: primo ingresso dei marinai ottomani nel Mar Rosso", "38740e0c"], "d": ["Di fronte alla pressione del Portogallo nell'Oceano Indiano, i marinai di origine ottomana Hüseyin Bey e Selman Reis, inviati nel Mar Rosso su richiesta del sultano mamelucco Qansuh al-Ghawri, con le loro flotte presero Zabid. Questa operazione, ancora condotta al servizio mamelucco, è la prima presenza effettiva della marina ottomana sulla linea Mar Rosso-India. Un anno dopo, con il passaggio dell'Egitto agli Ottomani, la stessa flotta sarebbe stata legata direttamente a Costantinopoli.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Dichiarazione ufficiale dell'obiettivo della campagna: i Mamelucchi e Aleppo", "689e310d"], "d": ["Selim il Severo, quando Qansuh al-Ghawri si accordò con i Safavidi e spinse l'esercito su Aleppo, dichiarò apertamente come obiettivo della campagna il sultano mamelucco e Aleppo. Così la rivalità velata durata anni tra i due Stati sunniti si trasformò in guerra aperta. Questa dichiarazione avviò il conto alla rovescia di quattro settimane che conduceva a Marj Dabiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Fallimento dell'assedio di Aden: primo tentativo nel Mar Rosso contro il Portogallo", "8ffd46f2"], "d": ["Selman Reis e Hüseyin Bey condussero un assedio di otto giorni per prendere Aden, porta del Mar Rosso aperta sull'Oceano Indiano, ma di fronte alle forti fortificazioni della città dovettero ritirarsi. La mancata presa di Aden avrebbe intralciato per molti anni la strategia meridionale da condurre contro il Portogallo. Questo tentativo è la prima prova della politica oceanica ottomana.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Il Beylik dei Ramazanoğulları legato agli Ottomani", "cfaa3754"], "d": ["Durante le assegnazioni seguite alla vittoria di Marj Dabiq, il Beylik dei Ramazanoğulları, con centro ad Adana, fu dato a Mahmud Bey e posto sotto dominio ottomano. Il beylik, uscito dalla sudditanza mamelucca, anziché essere abolito fu lasciato alla famiglia con lo statuto di «ocaklık»; i Ramazanoğulları continuarono l'amministrazione della Cilicia come sancak bey ottomani. Questo ordinamento privilegiato durò fino al 1608, anno in cui Pîr Mansûr lasciò il beylik. Altri luoghi annessi nella stessa data: Malatya, Tarso, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa e Deir ez-Zor entrano nel dominio ottomano", "2088eb6a"], "d": ["Quattro giorni dopo Marj Dabiq Selim il Severo entrò ad Aleppo senza incontrare resistenza e nelle moschee della città la khutba fu letta a suo nome. La caduta così rapida di Aleppo, considerata capitale commerciale e amministrativa della Siria, mostra che l'autorità mamelucca nella regione era crollata. La presa della città aprì in un istante la strada verso Damasco e di lì verso l'Egitto. Altri luoghi annessi nella stessa data: Antiochia, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Incontro ad Aleppo, a Gökmeydan, con il califfo abbaside al-Mutawakkil III", "22979f42"], "d": ["Il califfo abbaside del Cairo al-Mutawakkil III, fatto prigioniero a Marj Dabiq insieme all'esercito mamelucco, fu condotto ad Aleppo, a Gökmeydan, alla presenza del sultano, e Selim il Severo gli mostrò grande rispetto. Il califfato del Cairo, carica simbolica all'ombra dei sultani mamelucchi dal 1261, con questo incontro passò di fatto sotto la protezione ottomana. Il califfo sarebbe stato poi portato a Costantinopoli insieme al sultano.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli di Siria e Hama passano all'amministrazione ottomana", "a1e19a79"], "d": ["Dopo Aleppo e Hama anche Tripoli di Siria, sulla costa siriana, passò senza resistere all'amministrazione ottomana. La città, uno dei porti più attivi del Mediterraneo orientale, era la porta di Damasco sul mare e il centro del commercio della seta e dello zucchero. Con la sua presa la fascia costiera del Bilad al-Sham cambiò interamente mano.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damasco (Dimashq) entra nel dominio ottomano", "2b844d91"], "d": ["Selim il Severo, a cui si era aperta la strada con la resa di Hama e Homs dopo Aleppo, il 27 settembre giunse davanti a Damasco; non entrò subito in città ma piantò fuori la tenda nel luogo detto Mastaba e vi entrò con una grande cerimonia il dodicesimo giorno dal suo arrivo. Restando a lungo a Damasco stabilì l'ordinamento amministrativo della Siria e fece costruire la tomba di Muhyiddin Ibn al-Arabi. Così l'intero Bilad al-Sham uscì dall'amministrazione mamelucca. Altri luoghi annessi nella stessa data: Beirut.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Proclamazione di Tumanbay a sultano mamelucco al Cairo", "6020d90d"], "d": ["Dopo la morte di Qansuh al-Ghawri a Marj Dabiq gli emiri mamelucchi portarono al trono Tumanbay, che sarebbe stato l'ultimo sultano dello Stato. Il nuovo sultano, di origine circassa, ereditò uno Stato che aveva perso la Siria, aveva il tesoro esaurito e mancava di armi da fuoco. Ciò nonostante, costituendo una linea di difesa davanti al Cairo, avrebbe organizzato un'ultima resistenza contro l'avanzata ottomana.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Battaglia di Gaza (Khan Yunis): sconfitta di Canbirdi Gazâlî", "9f1eb8cb"], "d": ["Selim il Severo inviò a Gaza il gran visir Hadım Sinan Paşa con un'avanguardia di quattromila uomini. Canbirdi Gazâlî, nominato naib di Damasco da Tumanbay, cercò di fermare l'avanguardia ottomana sulla linea Gaza-Khan Yunis, ma subì una grave sconfitta e fuggì in Egitto. Con la dispersione dell'ultima forza cuscinetto mamelucca in Palestina la strada del deserto del Sinai si aprì completamente.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["A est del Giordano: Amman entra nell'amministrazione ottomana", "9db62667"], "d": ["Dopo la battaglia di Gaza, mentre le forze ottomane, in preparazione della campagna d'Egitto, scendevano a sud, anche Amman, a est del Giordano, entrò nell'amministrazione ottomana. Le città costiere e interne della Palestina (Giaffa, Nablus, Sidone, Acri, Gerusalemme) erano invece già passate di mano nell'autunno del 1516, dopo Marj Dabiq. Queste città furono amministrate per quattro secoli come sancak dell'eyalet di Damasco.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Arrivo di Selim il Severo a Gerusalemme", "66d7bfad"], "d": ["A Gerusalemme, passata senza resistere sotto l'amministrazione ottomana dopo Marj Dabiq, dopo la battaglia di Gaza giunse Selim il Severo con i notabili dello Stato e l'esercito. Il sultano visitò la Cupola della Roccia e la moschea di al-Aqsa e confermò lo statuto sacro della città. Gerusalemme sarebbe rimasta da questa data sotto l'amministrazione ottomana per quattro secoli esatti, fino al dicembre 1917.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Ingresso di Selim il Severo a Gaza e marcia verso il deserto del Sinai", "2106bfc7"], "d": ["Dopo la sconfitta di Canbirdi Gazâlî a Khan Yunis (21 dicembre 1516) Gaza era in mano all'avanguardia. Il sultano entrò a Gaza il 2 gennaio 1517 e vi incontrò Sinan Paşa, alla testa dell'avanguardia; l'esercito fece gli ultimi preparativi per il passaggio in Egitto. Nel deserto arido di Katya (Sinai), che si estende da Gaza a Salihiye, si sarebbero percorse otto tappe e l'acqua sarebbe stata trasportata con i cammelli. Questo passaggio è la fase più rischiosa e logisticamente più difficile della campagna.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Presa di Suez — porta aperta sul Mar Rosso", "05f3324e"], "d": ["Con l'entrata delle truppe ottomane al Cairo dopo la vittoria di Ridaniye anche Suez, all'estremità settentrionale del Mar Rosso, passò all'amministrazione ottomana. Questo arsenale-porto da cui i Mamelucchi inviavano la flotta nell'Oceano Indiano divenne la base della politica meridionale da condurre contro il Portogallo. Suez è l'imboccatura settentrionale della linea in cui tre secoli dopo sarebbe stato aperto il canale.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Primo ingresso delle truppe ottomane al Cairo", "0a3f4f4d"], "d": ["Il giorno dopo la vittoria di Ridaniye fu consentito agli eserciti ottomani di entrare al Cairo e il 24 gennaio le truppe si stabilirono in città. Ma questo ingresso non significava il pieno controllo della città; Tumanbay si era ritirato nell'Alto Egitto e la resistenza mamelucca non era ancora spezzata. La conquista del Cairo sarebbe stata completata non in un solo giorno, ma in un processo sanguinoso esteso su settimane.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Incursione di Tumanbay al Cairo e tre giorni di combattimenti di strada", "b83b6ce6"], "d": ["Tumanbay, ritiratosi nell'Alto Egitto, con circa settemila uomini la notte del 27-28 gennaio entrò all'improvviso al Cairo e avviò la resistenza in città, mettendo le truppe ottomane in estrema difficoltà. Nei violenti scontri di strada durati tre giorni i Mamelucchi tennero temporaneamente la maggior parte della città. La resistenza poté essere spezzata solo con l'intervento dell'artiglieria ottomana e dei rinforzi.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Canbirdi Gazâlî entrò al servizio ottomano", "a94ea459"], "d": ["L'ex emiro mamelucco Canbirdi Gazâlî, ritiratosi a Salihiye dopo Ridaniye, si rivolse al sultano chiedendo il perdono. Selim il Severo, ritenendo che sarebbe stato utile a stabilire l'ordine in Egitto e in Siria, lo accolse al proprio servizio. Questa scelta è il primo grande esempio della politica ottomana di includere nel sistema i quadri mamelucchi anziché liquidarli.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Ingresso solenne di Selim il Severo al Cairo e lettura della khutba", "6d98080c"], "d": ["Dopo la repressione degli scontri di strada il sultano il 15 febbraio 1517 entrò al Cairo con una cerimonia splendida e nelle moschee fu letta la khutba a suo nome. La lettura al Cairo della khutba a nome del sultano ottomano è la proclamazione della fine giuridica del dominio mamelucco, durato dal 1250. Questa data è considerata il momento simbolico del completamento della conquista effettiva dell'Egitto.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Cattura a Terruce dell'ultimo sultano mamelucco Tumanbay", "7058e6ad"], "d": ["Tumanbay, nascostosi nel delta del Nilo dopo aver lasciato il Cairo, fu denunciato dai beduini che gli avevano dato rifugio e catturato nella zona di Terruce. La sua cattura eliminò il centro organizzato della resistenza mamelucca. L'ultimo sultano sarebbe stato poi tenuto per quattordici giorni in mano ottomana.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Esecuzione di Tumanbay a Bab Zuweila e fine dello Stato mamelucco", "ad9820be"], "d": ["Quattordici giorni dopo la cattura Tumanbay fu impiccato a Bab Zuweila, la celebre porta del Cairo; il corpo fu poi sepolto nella madrasa fatta costruire dallo zio. Così lo Stato mamelucco, che dominava Egitto e Siria dal 1250, scomparve ufficialmente dalla storia. Con lo spezzarsi della resistenza anche città dell'Alto Egitto (Sa'id) come Asyut e Assuan furono legate all'amministrazione ottomana.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Attacco della flotta portoghese a Gedda e difesa di Selman Reis", "52322cf5"], "d": ["La flotta portoghese di una trentina di galee e galeoni attaccò Gedda; Selman Reis, dirigendo la difesa della città, impedì al nemico di sbarcare e affondò alcune navi portoghesi. Questa difesa evitò che il porto della Mecca e quindi la via del pellegrinaggio cadessero in mano a uno Stato cristiano. Gedda, pochi mesi dopo, sarebbe stata ufficialmente inclusa nell'amministrazione ottomana con la bay'a del Hegiaz.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Presa di Alessandria con la flotta — completamento della conquista dell'Egitto", "386878fe"], "d": ["Quattro mesi esatti dopo Ridaniye, trentasei giorni dopo l'esecuzione di Tumanbay, con l'arrivo in porto della flotta ottomana al comando di Câfer Bey Alessandria passò all'amministrazione ottomana; anche i porti del delta come Rosetta e Damietta furono legati nello stesso processo. Il fatto che questo grande porto egiziano aperto sul Mediterraneo fosse ricevuto mesi dopo la caduta del Cairo e dal mare e non da terra mostra chiaramente che la conquista fu completata non con un'unica battaglia ma regione per regione. Alessandria sarebbe poi divenuta il porto vitale che legava Costantinopoli e il Cairo. Altri luoghi annessi nella stessa data: Rosetta (Reşîd).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Incorporazione pacifica dell'Hegiaz: giuramento di fedeltà di Abu Numayy, figlio dello Sharif della Mecca", "c13b98c7"], "d": ["Selim I Yavuz aveva pensato dapprima di inviare truppe per prendere La Mecca e i dintorni, ma vi rinunciò quando l'emiro della Mecca, lo Sharif Barakat, comunicò la propria sottomissione. Abu Numayy, figlio di Barakat, di dodici anni, giunse al Cairo con i doni del padre e le chiavi della Mecca e fu ricevuto alla presenza del sultano. Così l'Hegiaz si incorporò agli Ottomani non come conseguenza automatica di Ridaniyya, ma cinque mesi e mezzo dopo e senza che fosse sparato un solo colpo, per via pacifica e con giuramento di fedeltà. Altri luoghi incorporati nella stessa data: Tâif. Altri insediamenti che cambiarono mano nella stessa data: Hurma (a est di Tâif), Rabigh, Badr.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Accettazione del titolo di Servitore dei Due Luoghi Santi e khutba a Medina", "63b32b59"], "d": ["Dopo la seconda udienza della delegazione della Mecca Selim il Severo assunse ufficialmente la protezione dei Due Luoghi Santi e cominciò a usare il titolo di «hâdimü'l-Haremeyni'ş-şerîfeyn». Lo sceriffo Barakat, indossato il kaftano d'onore inviatogli, fece leggere la khutba a nome del sultano; con l'andata a Costantinopoli anche della delegazione di Medina l'emirato di Barakat fu confermato con un berat. Il sultano inviò alla popolazione dei Due Luoghi Santi duecentomila monete d'oro e abbondanti provviste, avviando la tradizione della surre che si sarebbe ripetuta ogni anno. Altri luoghi annessi nella stessa data: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Ingresso di Selman Reis al servizio ottomano e passaggio di mano della politica del Mar Rosso", "771da99a"], "d": ["Selman Reis, che aveva difeso Gedda contro i Portoghesi, venne al Cairo e si presentò a Selim il Severo; benché fosse trattenuto per un periodo, nel 1519 fu chiamato a Costantinopoli e si impegnò a preparare trenta galee e alcune galeotte contro la minaccia portoghese. Questo incontro è l'inizio del passaggio della politica del Mar Rosso e dell'Oceano Indiano dall'eredità mamelucca al legame diretto con Costantinopoli. Gli Ottomani erano ormai, oltre che uno Stato mediterraneo, una potenza che conduceva anche una politica oceanica.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Partenza di Selim il Severo dal Cairo e beylerbeylik di Hayır Bey", "8cd4fb23"], "d": ["Selim il Severo, dopo essere rimasto circa otto mesi in Egitto ed aver stabilito l'ordine amministrativo, finanziario e militare, lasciò il Cairo; Hayır Bey, ex naib di Aleppo che a Marj Dabiq aveva ritirato l'ala sinistra accelerando la disfatta mamelucca, iniziò a governare dalla Cittadella come primo beylerbey ottomano d'Egitto. La scelta di un governatore di origine mamelucca fu una politica di transizione consapevole, che evitava che la nuova amministrazione apparisse estranea alla popolazione locale. Sulla via del ritorno il sultano portò a Costantinopoli, con sé, l'ultimo califfo abbaside al-Mutawakkil III e gli artisti e dotti eminenti dell'Egitto.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Fine del califfato abbaside del Cairo — la tradizione della «cerimonia di trasferimento»", "1d357640"], "d": ["Selim il Severo, preso l'Egitto, portò con sé a Costantinopoli l'ultimo califfo, al-Mutawakkil III ʿala Allah, fatto prigioniero a Marj Dabiq; così ebbe fine il califfato abbaside del Cairo, che durava senza autorità all'ombra dei sultani mamelucchi dal 1261. In compenso, la celebre tradizione secondo cui il califfato sarebbe stato trasferito a Selim con una cerimonia ufficiale a Santa Sofia compare per la prima volta alla fine del XVIII secolo nell'opera di d'Ohsson e non si trova in nessuna delle fonti dell'epoca di Selim. Il TDV İslâm Ansiklopedisi considera la tradizione inventata, non esistendo una fonte originale che documenti la cerimonia; ma registra anche che per il passaggio del califfato secondo la shari'a non c'era bisogno di una simile cerimonia di trasferimento.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum annessa all'amministrazione ottomana — spezzata l'influenza safavide nell'Anatolia orientale", "78d1be02"], "d": ["Benché dopo la vittoria di Çaldıran (1514) l'influenza ottomana nella regione fosse cresciuta, la presa completa di Erzurum fu ritardata fino alla rottura dell'influenza iraniana; la città fu annessa all'amministrazione ottomana solo nel 1518-19, dopo la campagna d'Egitto. Erzurum era entrata sotto dominio safavide nel 1502, quando lo shah Ismail pose fine al Beylik degli Aqquyunlu; questo periodo di sedici anni si chiuse così. Nel 1534, durante la Campagna dei Due Iraq, sarebbe stato istituito il beylerbeylik di Erzurum. Nel 1518-1519 Aşkale fu annessa all'amministrazione ottomana insieme alla regione di Erzurum (giorno non confermato).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Inizio delle rivolte dei Celâlî: rivolta di Şeyh Celâl di Bozok", "99bd8a99"], "d": ["Nella zona di Bozok un certo Şeyh Celâl, proclamatosi mahdi, si sollevò nei dintorni di Tokat; benché la rivolta fosse repressa, per un secolo il suo nome designò tutti i movimenti di banditi e di rivolta in Anatolia. Il celalismo, unendosi alla dissoluzione del sistema del timar e alla pressione demografica alla fine del XVI secolo, si trasformò nel problema di sicurezza interna più duraturo dell'impero. Le rivolte provocarono in Anatolia migrazioni di massa dette «grande fuga».", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Algeri legata allo Stato ottomano", "b8eba4c1"], "d": ["Hayreddin Reis, che resisteva alla pressione spagnola in Nord Africa, per poter reggere si rivolse a Costantinopoli e offrì Algeri al sultano e la khutba fu letta a nome di Selim il Severo. Così Algeri fu ufficialmente annessa ai territori ottomani e a Hayreddin furono inviati soldati e cannoni con il titolo di beylerbey. Questo legame pose la base del dominio navale ottomano nel Mediterraneo occidentale destinato a durare secoli. Altri luoghi annessi nella stessa data: Costantina, Cherchell (Şerşel), Medea (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Morte di Selim il Severo a Çorlu", "9fe83744"], "d": ["Selim I, che in otto anni aveva più che raddoppiato il territorio dello Stato, il 18 luglio 1520 partì da Costantinopoli per una nuova campagna; per un grosso tumore comparso sulla schiena non poté andare oltre Çorlu. Nonostante l'intervento dei medici la malattia si aggravò e, dopo due mesi di cure senza speranza, vi morì l'8-9 Shawwal 926 (21-22 settembre 1520). Con Çaldıran, Marj Dabiq e Ridaniye aveva fermato l'Iran e abolito lo Stato mamelucco, portando agli Ottomani il califfato e la protezione dei Due Luoghi Santi. Lasciò un solo figlio maschio: Solimano.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Ingresso dell'isola di Icaria (Nikarya) sotto amministrazione ottomana", "6afa972b"], "d": ["Icaria (Nikarya), tra Samo e Chio, dal 1481 al 1521 fu amministrata dai Cavalieri di San Giovanni di Rodi; il primo periodo ottomano sull'isola iniziò nel 1522 e durò fino al 1822. In questo periodo era il kaymakam il responsabile della riscossione e del pagamento delle imposte; come nelle altre isole dell'Egeo continuò a esistere anche il consiglio locale degli anziani (demogerontia), che talvolta entrò in conflitto con l'amministrazione ottomana.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Annessione del paese di Dulkadir — eyalet di Dulkadır con centro a Maraş", "595c3c30"], "d": ["Il paese di Dulkadır, rimasto dopo la disfatta di Turnadağ del 1515 come beylicato vassallo degli Ottomani, dopo l'uccisione di Şehsuvaroğlu Ali Bey con i suoi figli ad Artukova fu annesso direttamente ai territori ottomani e fatto eyalet con centro a Maraş. La regione di Bozok del beylicato fu legata all'amministrazione ottomana come sanjak separato. Si chiuse così il periodo dulkadiride di circa due secoli di Maraş, Elbistan, Göksun, Gürün, Zamantı e Darende; il beylicato cuscinetto al confine mamelucco scomparve del tutto.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Conquista di Knin", "a46d3117"], "d": ["Con le incursioni del sanjak-bey di Bosnia Gazi Hüsrev Bey negli anni 927-928 (1521-1522) una serie di fortezze veneziane, tra cui Knin, Scardona e Ostrovica, passò all'amministrazione ottomana; il confine fu spinto oltre la seconda catena montuosa. Questa catena di conquiste pose le basi del sanjak di Dalmazia, che sarebbe stato completato quindici anni dopo con la presa di Clissa.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Ritiro dei Cavalieri: cessione di Bodrum, Coo e Dodecaneso", "ea01666e"], "d": ["In forza delle condizioni di resa di Rodi, i cavalieri di San Giovanni evacuarono non solo il centro dell'isola, ma tutte le posizioni che tenevano da duecento anni. La fortezza di Bodrum (San Pietro) sulla costa anatolica e le isole di Coo, Calimno e Lero passarono così sotto amministrazione ottomana senza scontri. Con questa cessione completata due settimane dopo la caduta di Rodi, la presenza latina nell'angolo sudorientale dell'Egeo ebbe fine del tutto.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Rivolta di Hain Ahmed Paşa in Egitto", "b18bb805"], "d": ["Ahmed Paşa, inviato al governatorato d'Egitto mentre attendeva il gran visirato, si proclamò al Cairo «al-Malik al-Mansur Sultan Ahmed» e dichiarò la propria indipendenza. La rivolta fu presto repressa e il paşa ucciso, ma l'evento mostrò la fragilità del controllo centrale nella più ricca provincia dell'impero. Allora İbrahim Paşa si recò in Egitto e fece preparare il celebre Kanunnâme d'Egitto, che riordinava l'amministrazione della provincia.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Annessione della Bosnia settentrionale: Jajce e Banja Luka", "8ec86cfa"], "d": ["Quando dopo Mohács la linea di difesa ungherese crollò, il sanjak-bey di Bosnia Gazi Hüsrev Bey marciò nella valle del Vrbas e prese le ultime fortezze bosniache rimaste al regno d'Ungheria. Con la caduta di Jajce e Banja Luka l'eyalet di Bosnia raggiunse a nord il fiume Sava e nacque il fronte croato. Banja Luka divenne presto il secondo centro della provincia.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Presa di Buda e consegna a Szapolyai", "fba4f89b"], "d": ["Durante la campagna di Vienna l'esercito ottomano assediò e riprese Buda, caduta in mano a Ferdinando, e consegnò la città al re ungherese János Szapolyai, sotto protezione ottomana. Così sull'Ungheria fu stabilito, nella rivalità asburgico-ottomana, il modello di regno vassallo cuscinetto. Questo ordinamento sarebbe durato fino al 1541; dopo la morte di Szapolyai Buda sarebbe stata trasformata in provincia ottomana diretta.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Solimano partì per la campagna di Germania — sfida a Carlo V", "7c3d7055"], "d": ["Dopo il fallimento dell'assedio di Vienna e il nuovo assedio di Buda da parte di Ferdinando, il sultano partì da Costantinopoli, questa volta per attirare in battaglia campale direttamente l'imperatore Carlo V. L'esercito ad agosto sarebbe stato trattenuto dalla resistenza della piccola fortezza di Güns e, poiché l'imperatore non uscì a combattere, la campagna si sarebbe limitata alle incursioni. La campagna preparò il terreno della prima pace con gli Asburgo l'anno seguente.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Campagna di Germania e assedio di Güns (Kőszeg)", "8aec937a"], "d": ["Solimano marciò con l'esercito sull'Austria con lo scopo di costringere Carlo V a una battaglia campale; la piccola fortezza di Güns, resistendo venticinque giorni, ritardò l'avanzata dell'esercito. Poiché l'imperatore non uscì a combattere, gli akıncı colpirono i dintorni di Vienna e per l'avanzare della stagione si tornò indietro. La campagna non portò guadagni territoriali, ma, facendo sedere gli Asburgo al tavolo, preparò il terreno della pace dell'anno seguente.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Trattato di Costantinopoli — prima pace con gli Asburgo", "b085767a"], "d": ["Il sultano, ricevuto l'ambasciatore di Ferdinando, Cornelius, acconsentì a una tregua e comparve il primo testo ufficiale di pace tra Ottomani e Austria. Con il trattato Ferdinando accettò di pagare un'imposta annua per i territori ungheresi che teneva e l'arciduca d'Austria fu nel protocollo considerato pari al gran visir. Questo statuto ineguale era la chiara espressione della pretesa di superiorità della diplomazia ottomana nel XVI secolo.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Presa di Kars e apertura del confine nordorientale", "742e3101"], "d": ["Mentre la colonna avanzata della Campagna dei Due Iraq (Irakeyn Seferi) si dirigeva da Erzurum verso est, la fortezza di Kars, in mano all'atabeg georgiano e in rovina dai tempi di Tamerlano, fu ricevuta in resa senza incontrare resistenza. Poiché la città teneva il passaggio tra l'arco dell'Aras e Çıldır, era considerata la chiave della porta settentrionale che si apriva sull'Iran. Questo guadagno fu il primo anello del beylerbeylik di Kars, che sarebbe stato fondato trent'anni dopo, e della linea caucasica.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Prima entrata a Tabriz — apertura della Campagna dei Due Iraq", "cf7ed4e3"], "d": ["İbrahim Pascià, avanzato per primo con la carica di serdar-ı ekrem, entrò senza incontrare resistenza nella capitale safavide Tabriz, poiché lo shah Tahmasp evitava la battaglia campale e si ritirava all'interno. Anche Solimano il Legislatore raggiunse la città a settembre; ma per l'incalzare dell'inverno e per la lunghezza eccessiva della linea di rifornimento l'esercito si diresse verso Baghdad e Tabriz non poté essere tenuta a lungo. La città, presa per la seconda volta dopo Çaldıran, fu il luogo in cui gli Ottomani impararono che a oriente conquistare era facile, mantenere difficile.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Conquista di Tunisi da parte di Barbarossa", "d8754216"], "d": ["Il kapudan paşa Barbarossa Hayreddin Paşa, dopo aver colpito con la flotta le coste italiane, si volse a Tunisi e vi entrò facendo fuggire il sovrano hafside Mevlây Hasan. La presa di Tunisi, per la sua posizione che controlla lo Stretto di Sicilia, mutò all'istante a favore degli Ottomani l'equilibrio delle forze nel Mediterraneo occidentale. Ma questo dominio non sarebbe durato a lungo: Carlo V l'anno seguente avrebbe risposto con una grande flotta.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Perdita di Tunisi a favore di Carlo V", "a691f0f8"], "d": ["Carlo V, con una grande campagna sostenuta dalle flotte genovese e pontificia, fece cadere La Goletta, prese Tunisi e restituì al trono Mevlây Hasan sotto protezione spagnola. Vi fu posta una guarnigione spagnola e l'avanzata ottomana nel Mediterraneo centrale fu temporaneamente fermata. La conquista definitiva di Tunisi sarebbe stata possibile solo quarant'anni dopo, nel 1574.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Campagna di Gazi Hüsrev Bey lungo la Sava: Bosanski Brod e Jasenovac", "3740ec83"], "d": ["Dopo la presa di Jajce e Banja Luka nel 1528 le fortezze lungo il fiume Sava rimasero ancora per un periodo sul confine croato-slavone legato alla corona asburgica. Gazi Hüsrev Bey, diventato per la terza volta sanjak-bey di Bosnia nel 1536, mentre nello stesso anno prendeva Požega e dintorni, aggiunse all'amministrazione ottomana anche le fortezze di Brod e Jasenovac sulla riva della Sava. Così il confine settentrionale della Bosnia raggiunse la Sava; la regione fu completata due anni dopo con la presa di Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Esecuzione di Makbul İbrahim Paşa", "348aa7b8"], "d": ["İbrahim Paşa, gran visir per tredici anni, amico più stretto di Solimano e di fatto secondo uomo dello Stato, fu fatto strangolare e giustiziato a palazzo, dove era stato invitato all'iftar, senza che fosse indicata alcuna ragione. Si ritiene che nella sua morte abbiano influito l'atteggiamento assunto nella campagna dei Due Iraq, l'uso del titolo di «serasker sultan» e gli equilibri interni di palazzo. L'esecuzione è una svolta che mostra come nell'amministrazione centrale ottomana i gran visir non avessero sicurezza assoluta.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Conquista della fortezza di Klis e fondazione del sancak di Dalmazia", "6ffd4ebf"], "d": ["Murad Bey, convertito di origine croata e kethüdâ di Gazi Hüsrev Bey, prese a Venezia la strategica fortezza di Klis, subito a nord di Spalato. Subito dopo la conquista Klis fu fatta centro di un nuovo sancak e kaza comprendente i dintorni; i confini di questo sancak tracciarono in gran parte il quadro della Croazia ottomana. Questa conquista, giunta quindici anni dopo Knin, completò l'ossatura amministrativa dell'interno della Dalmazia.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Assedio di Corfù e guerra con Venezia", "11af95bd"], "d": ["Dopo la campagna di Puglia (Apulia) l'esercito ottomano sbarcò truppe a Corfù e assediò la poderosa fortezza veneziana dell'isola. Per la natura scoscesa della fortezza, le gravi perdite e le condizioni stagionali, il 6 settembre il blocco fu tolto e ci si ritirò. Benché l'assedio fosse rimasto senza esito, la guerra aperta con Venezia si concluse con l'annessione agli Ottomani di numerose isole dell'Egeo e dell'Adriatico e con la vittoria di Prevesa l'anno seguente.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Campagna di Barbarossa nell'Egeo: presa delle isole amministrate direttamente da Venezia", "1b32ed96"], "d": ["La flotta, ritornata dall'assedio di Corfù, approfittando della guerra dichiarata a Venezia, ricevette in resa una a una nell'Egeo le isole legate non al ducato ma direttamente a Venezia. Egina fu presa dopo una violenta resistenza, Astipalea in mano alla famiglia Querini, Scarpanto e Casos si arresero, e anche Patmos, sotto amministrazione monastica, accettò la protezione ottomana. Il Ducato di Nasso fu invece lasciato in vita come tributario; la sua annessione avrebbe atteso il 1566.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Campagna di Barbarossa nell'Egeo settentrionale: presa di Sciro e delle Sporadi settentrionali", "20ab688e"], "d": ["Sulla via di Prevesa la flotta ricevette in resa una a una le isole dell'Egeo settentrionale che dopo la conquista di Costantinopoli si erano poste sotto la protezione di Venezia. Sciro, a nord di Negroponte, e Schiato, Scopelo e Alonisso, che tengono l'imboccatura del golfo di Salonicco, entrarono così sotto amministrazione ottomana. Queste isole colmarono l'ultimo vuoto nell'Egeo settentrionale, rimasto per altri sessantotto anni in mano veneziana, benché Negroponte fosse stata presa nel 1470.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Presa di Aden e annessione della costa dello Yemen", "e7d46d8f"], "d": ["La flotta partita da Suez per la campagna dell'India si diresse prima verso la costa dello Yemen, poiché non si poteva uscire nell'oceano senza mettere in sicurezza il Mar Rosso. Hadım Süleyman Pascià entrò nel porto di Aden il 3 agosto 1538; il sovrano tahiride Amir b. Dawud, che propendeva per i Portoghesi, fu fatto portare alla porta del capitano e giustiziato, e in città fu lasciata una guardia di 500 uomini. Nella stessa campagna furono ricevute in resa anche Mocha e le isole di Kamaran e Ferasan, che dominano lo stretto, e fu posta la base del beylerbeylik dello Yemen. Così l'Impero ottomano per la prima volta possedette l'intera costa settentrionale del Bab el-Mandeb; Sana'a e le regioni interne avrebbero dovuto attendere altri nove anni.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Campagna di Moldavia e annessione della regione di Bucak (Bender)", "90a88a56"], "d": ["Nella campagna contro il voivoda di Moldavia Petru Rareș, che non adempiva agli obblighi verso gli Ottomani, fu presa Suceava e la città di Iași fu saccheggiata dal khan di Crimea Sâhib Giray. Il sultano pose sul voivodato Ștefan Lăcustă (Stefano la Cavalletta) e annesse direttamente ai territori ottomani, insieme a Bender, la regione di Bucak (Bessarabia meridionale). Questa annessione fu uno degli anelli che fecero del Mar Nero nord-occidentale un mare interno ottomano. La Moldavia era già un voivodato vassallo degli Ottomani; questa campagna non prese il territorio a uno Stato straniero, ma si limitò a togliere al voivoda l'amministrazione interna di Bender e Bucak legandola direttamente al sultano; il resto del voivodato mantenne lo statuto di vassallo. La stessa struttura si sarebbe ripetuta nel 1484 a Chilia e Akkerman e nel 1713 a Chotin: le fortezze di confine dirette, i territori interni vassalli.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Acquisizione di Nauplia (Anabolu) tramite trattato", "104d0937"], "d": ["La guerra con Venezia, durata tre anni dopo Prevesa, si concluse con l'accettazione da parte della repubblica di cedere le ultime due fortezze in Morea. Nauplia e Monemvasia, che non si era riusciti a prendere con l'assedio, furono cedute agli Ottomani a tavolino, oltre a un'indennità di guerra di trecentomila ducati. La penisola di Morea fu così riunificata senza che vi restasse una sola traccia veneziana.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Ingresso di Seghedino sotto amministrazione ottomana e formazione del livâ di Seghedino", "019aa000"], "d": ["Dopo l'instaurazione completa dell'amministrazione ottomana a Buda nel 1541, i notabili di Seghedino adottarono la sovranità di Ferdinando I e si prepararono alla difesa armata. Il beylerbey di Buda Küçük Bâlî Pascià, all'inizio del 1543, fece venire i governanti della città, li fece giustiziare con l'accusa di tradimento e poi inviò un reparto per prendere la città. In quel periodo fu costituito il livâ di Seghedino e come primo sanjak-bey fu nominato Derviş Bey, figlio di Bâlî Pascià; il livâ all'inizio si estendeva tra Danubio e Tibisco.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Conquista di Valpó, Siklós e Pécs", "2ca030a3"], "d": ["Il primo obiettivo della campagna d'Ungheria intrapresa due anni dopo l'annessione di Buda era mettere in sicurezza il fianco meridionale della nuova provincia tra la Drava e il Danubio. Dopo la presa delle fortezze di Valpó e Siklós, si arrese Pécs (Peçuy), centro della Baranya. La città sarebbe divenuta il centro più popoloso e più ricco di opere pubbliche dell'Ungheria ottomana, e lo storico İbrahim Peçuylu avrebbe preso da qui il proprio nome.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Conquista di Esztergom e Székesfehérvár", "efca9e05"], "d": ["Nella campagna d'Ungheria guidata di persona da Solimano, dopo un assedio di due settimane e mezzo, Esztergom, centro religioso e città arcivescovile del Regno d'Ungheria, entrò nell'amministrazione ottomana. Poi fu presa anche Székesfehérvár, città dell'incoronazione dei re ungheresi, e la cintura difensiva dell'eyalet di Buda fu completata. Esztergom sarebbe rimasta in mano ottomana, come fortezza chiave della linea del Danubio, fino al 1595.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Cintura difensiva settentrionale e occidentale di Buda: Vác, Hatvan e Simontornya", "733ee5ce"], "d": ["Dopo la presa di Esztergom e Székesfehérvár, il beylerbey di Buda si mise in movimento, senza campagna del sultano, per completare l'anello di fortezze intorno alla capitale. Vác sull'ansa del Danubio, Hatvan, porta dell'Alföld, e Simontornya sulla linea del Sió furono ricevute in resa una per una. I guadagni di quest'anno silenzioso trasformarono Buda da città di frontiera in un centro provinciale destinato a durare centoquaranta anni.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Annessione di Bassora e accesso al Golfo Persico", "02f87c11"], "d": ["Al tempo della conquista di Baghdad (1534) il signore di Bassora Rashid b. Mughamis aveva dichiarato obbedienza a Solimano il Legislatore e nel 1538 aveva inviato le chiavi della città. Quando il suo successore Şeyh Yahya si schierò contro gli Ottomani, il beylerbey di Baghdad Ayas Pascià mosse da terra e il sanjak-bey di Mosul con 120 navi lungo l'Eufrate; Ayas Pascià entrò a Bassora il 26 dicembre 1545 e la città divenne centro di beylerbeylik. Questo porto alla foce dello Shatt al-Arab era la porta con cui gli Ottomani si aprivano al Golfo, controllato dal Portogallo da Hormuz; con il Trattato di Amasya del 1555 anche l'Iran riconobbe questa situazione.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Conquista di Sana'a e dell'interno dello Yemen", "d31ded85"], "d": ["Dopo Taiz fu presa anche Sana'a e l'intero paese fu legato al beylerbeylik. Ma per la geografia impervia e per la differenza confessionale questo dominio non fu mai tranquillo; lo Yemen divenne per gli Ottomani un fronte che inghiottiva continuamente soldati.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Conquista di Taiz", "d4509df9"], "d": ["Nello Yemen, dove nove anni prima ci si era accontentati della fascia costiera, con il progressivo rafforzamento degli imam zaiditi nell'entroterra montuoso, le forze di Özdemir Pascià salirono sull'altopiano e presero Taiz.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Trattato di Costantinopoli — pace di cinque anni con gli Asburgo", "41f81773"], "d": ["Tra Ottomani e Asburgo fu firmata una pace di cinque anni; Ferdinando accettò di pagare 30.000 ducati annui per i territori ungheresi che teneva. Il trattato registrò giuridicamente la situazione di fatto dell'Ungheria divisa in tre. La messa in sicurezza del fronte occidentale diede a Solimano la possibilità di organizzare nuove campagne contro l'Iran.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Seconda campagna d'Iran e ripresa di Tabriz", "e82365df"], "d": ["Nella campagna intrapresa su incitamento del fratello Elqas Mirza, che si era ribellato allo shah Tahmasp e si era rifugiato a Istanbul, l'esercito entrò per la seconda volta a Tabriz. Poiché i Safavidi ancora una volta non accettarono la battaglia campale e si ritirarono bruciando la terra, in città fu possibile restare solo poche settimane. La campagna rese certo che Tabriz non poteva essere tenuta e orientò la strategia ottomana verso la creazione di una linea di confine stabile, cioè la fortificazione di Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Conquista di Van e fissazione del confine orientale", "fc8f930b"], "d": ["La fortezza di Van, assediata al ritorno da Tabriz, con la sua posizione sulla roccia che si erge sulla riva orientale del lago era la chiave indiscussa della regione e si arrese dopo un breve assedio. La città fu subito fatta centro di beylerbeylik; vi furono legati i sanjak di Erciş, Adilcevaz e Hakkâri. A differenza di Tabriz, Van fu tenuta e per quattrocento anni rimase la posizione stabile più avanzata degli Ottomani a oriente.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Annessione di al-Hasa e Qatif — la costa arabica del Golfo", "f6701e60"], "d": ["Dopo la presa di Bassora fu presa Qatif, divenuta avamposto del Portogallo sulla costa occidentale del Golfo, e insieme alle oasi di al-Hasa nell'entroterra fu fondato un nuovo beylerbeylik. Era il punto di partenza delle operazioni verso Bahrein e Hormuz. L'Impero ottomano ebbe così voce contemporaneamente sulle coste della penisola arabica sia del Mar Rosso sia del Golfo Persico.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Perdita di Shahrizor — il bey di Ardalan Sohrab si orienta verso i Safavidi", "5600efc9"], "d": ["La zona di Shahrizor, che durante la Campagna dei Due Iraq (1535) aveva riconosciuto l'amministrazione ottomana, era governata dall'emiro di Ardalan Bige Bey, che risiedeva nella fortezza di Zalm. Alla morte di Bige Bey nel 1550, il fratello Sohrab, che si impadronì della fortezza di Zalm e prese il controllo del beylicato, si volse ai Safavidi e abbandonò l'obbedienza agli Ottomani; la zona di Shahrizor uscì così dall'influenza ottomana. La regione fu riguadagnata solo nel 1554, durante la campagna di Nakhchivan, con l'assedio e la presa della fortezza di Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Presa di Ardahan e del bacino di Çıldır", "14c9eb76"], "d": ["Il beylerbey di Erzurum, durante la guerra con i Safavidi, si diresse verso le terre degli atabeg georgiani sull'arco del Kura e legò Ardahan e i dintorni di Çıldır all'amministrazione ottomana. La linea Kars-Ardahan si completò così e a nordest furono messi sotto controllo gli altopiani che si aprono sulla Georgia. L'ordinamento amministrativo definitivo della regione sarebbe stato completato ventisette anni dopo con l'eyalet di Çıldır.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Pascià attraversa il Danubio — inizio della guerra di Transilvania", "38fde931"], "d": ["Per gli scompigli causati dal monaco Martinuzzi, tutore del piccolo János Zsigmond, re di Transilvania, e per la cessione da parte della Transilvania delle fortezze del Banato a Ferdinando, si ritenne necessaria una nuova campagna; il comando fu dato al beylerbey di Rumelia Sokollu Mehmed Pascià. L'esercito, nonostante i tentativi dilatori di Martinuzzi, attraversò il Danubio e prese Bečej, Bečkerek, Csanád e Lippa; ma l'assedio di Timișoara fu tolto il 16 novembre per i primi freddi. Si aprì così in Ungheria una nuova guerra ottomano-asburgica.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["La città di Lipova (Lippa) cade in mano all'esercito austriaco di Castaldo — la fortezza si arrende il 5 dicembre", "a0e1ff0d"], "d": ["Lipova, presa da Sokollu Mehmed Pascià nell'ottobre 1551, fu assediata il 4 novembre dall'esercito del generale Castaldo; due giorni dopo la città cadde in mano austriaca. Ulama Pascià difese la fortezza per altri nove giorni con una guarnigione di 5.000 uomini e il 5 dicembre 1551 ne uscì con un accordo. Fino alla caduta di Timișoara nel 1552 Lipova rimase in mano asburgica.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Forze inviate da Timișoara occupano le palanke del Banato meridionale — Versec, Haram, Keve", "edca0921"], "d": ["Dopo la resa di Timișoara all'esercito ottomano, i reparti staccati dall'esercito d'assedio si diressero verso le piccole palanke del Banato; secondo il racconto di Bánlaky, le palanke di Versec, Facset, Mehádia, Csákóvár, Haramvár e Keve furono occupate da queste forze. Così anche Haram, sulla riva del Danubio, cadde in mano ottomana.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Conquista di Szolnok e fallimento dell'assedio di Eger", "a7156e8f"], "d": ["Dopo la presa di Timișoara i due eserciti ottomani riuniti ricevettero Szolnok sul Tibisco quasi senza combattere, poiché la guarnigione di mercenari abbandonò la fortezza. La fortezza di Eger, assediata poi, non poté essere presa di fronte alla resistenza di trentotto giorni della guarnigione di duemila uomini al comando di István Dobó e l'esercito si ritirò all'arrivo dell'inverno. Il fatto che nella stessa campagna una fortezza cadesse facilmente mentre l'altra resisteva fu il primo segno aperto che in Ungheria il confine non avanzava più spontaneamente a favore degli Ottomani.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Alleanza ottomano-francese — la flotta francese agli ordini degli Ottomani", "a8e01b22"], "d": ["Con il trattato del 1° febbraio 1553 la flotta francese fu posta agli ordini della flotta ottomana; fu prevista un'azione comune nel Mediterraneo occidentale contro la Spagna. Dopo il trattato Turgut Reis il 15 giugno 1553 partì in campagna con quarantacinque galee per sostenere la Francia. Fu la prima alleanza ufficiale che portò il terreno commerciale delle capitolazioni del 1536 a una cooperazione militare.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Esecuzione del principe Mustafa a Konya Ereğlisi", "dec36858"], "d": ["Il principe Mustafa, entrato nella tenda del padre per unirsi all'esercito riunito per la campagna di Nakhchivan, mentre stava per presentarsi all'udienza incontrò i carnefici e fu strangolato. L'uccisione del candidato alla successione, molto amato nell'esercito, suscitò profonda collera tra i giannizzeri e Rüstem Paşa fu rimosso dal gran visirato. L'evento è passato nella letteratura e nella memoria popolare come una delle rotture più discusse della politica ottomana verso i principi.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Spostamento a sud del confine di Ibrim e della Nubia", "c57d5d77"], "d": ["Il confine meridionale del beylerbeylik d'Egitto fu spostato oltre la seconda cataratta con la fortificazione, per mano di Özdemir Bey, della fortezza di Ibrim, che si erge su uno sperone roccioso sul Nilo, e con la piena annessione della Bassa Nubia all'Egitto ottomano. (A Ibrim l'organizzazione amministrativa ottomana era stata istituita subito dopo la conquista dell'Egitto; sulla mappa Ibrim è mostrata ottomana dal 1517. Quest'anno è approssimativo, la fonte non dà l'anno.) La fortezza era sia un argine contro le incursioni dalla Nubia sia il punto di controllo della via dell'oro e degli schiavi verso Sennar. Il reparto di guardia bosniaco qui stanziato si radicò al punto che i suoi discendenti erano ancora nella fortezza trecento anni dopo. Le fonti danno due racconti distinti sul momento dell'ingresso di Ibrim sotto amministrazione ottomana: la voce Sudan del TDV lega l'annessione della Bassa Nubia all'Egitto ottomano all'operazione di Özdemir Pascià a metà del XVI secolo, mentre la voce Nûbe scrive che la regione fino alla valle di Halfa e l'organizzazione amministrativa di Ibrim furono stabilite subito dopo la conquista del 1517. Il sanjak di Ibrim fu legato all'eyalet di Abissinia il 26 luglio 1573.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Presa di Bugia (Bicâye) agli Spagnoli", "49691cda"], "d": ["Bugia, in mano alla Spagna da quarantatré anni e che divideva in due la costa tra Algeri e Costantina, si arrese dopo l'assedio da terra e da mare. Con la caduta della fortezza la costa dell'ocak di Algeri divenne ininterrotta fino a Orano. In Spagna questa perdita suscitò un'indignazione tale che il comandante Alonso de Peralta, che aveva consegnato la fortezza, fu giustiziato in patria.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Annessione di Zeila all'eyalet di Abissinia", "7bbf369a"], "d": ["Al limite meridionale dell'eyalet di Abissinia, il porto di Zeila, sulla costa africana del Golfo di Aden, fu legato all'amministrazione ottomana. Questa città, porta sul mare del Sultanato di Adal, era l'ultimo punto di rifornimento per le navi che uscivano da Bab el-Mandeb. Con l'annessione di Zeila il confine dell'Impero ottomano in Africa raggiunse il suo punto più meridionale.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Battaglia dei principi a Konya", "1c8de387"], "d": ["Il principe Bayezid, entrato nella lotta per il trono, giunse davanti a Konya con una forza di circa 30.000 uomini e in uno scontro di due giorni fu sconfitto dal fratello, il principe Selim. Bayezid, sconfitto, si rifugiò attraverso Amasya in Iran, presso lo shah Tahmasp. La battaglia trasformò la crisi di successione al sultanato degli ultimi anni di Solimano in un problema di politica estera.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Vittoria navale di Gerba", "c7b905c1"], "d": ["La flotta ottomana al comando di Piyâle Paşa disperse davanti a Gerba, con una manovra di divisione in due, la flotta alleata ispano-genovese-maltese riunita per riprendere Tripoli. Gli alleati persero gran parte delle flotte e la fortezza sull'isola cadde in breve tempo. Gerba, dopo Prevesa, è considerata la seconda grande vittoria navale che consolidò la superiorità ottomana nel Mediterraneo.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Esecuzione del principe Bayezid a Qazvin", "a759de14"], "d": ["Il principe Bayezid, rifugiatosi in Iran, dopo lunghe trattative fu consegnato dallo shah Tahmasp alla delegazione ottomana e fu strangolato insieme ai quattro figli. In cambio della consegna i Safavidi ottennero importanti concessioni materiali e garanzie di confine. Con questa esecuzione cadde l'ultimo ostacolo all'ascesa al trono di Selim II e l'ordine di pace di Amasya fu preservato.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Presa di Chio ai Genovesi", "a4559b96"], "d": ["Chio, amministrata da duecento anni come colonia commerciale dalla famiglia genovese dei Giustiniani e tributaria degli Ottomani, con la motivazione che aveva trascurato il tributo e dato porto alle navi nemiche fu presa da Piyâle Pascià senza sparare un colpo. Con Chio e Psara fu liquidata anche l'ultima presenza genovese sulla costa orientale dell'Egeo. Con la salvaguardia della produzione di mastice e dei privilegi dei Chioti l'isola fu legata all'eyalet di Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Annessione del Ducato di Nasso — l'intero arcipelago delle Cicladi", "68f0ec0b"], "d": ["Il Ducato latino di Nasso, in vita dal 1207 e tributario degli Ottomani dal 1537, fu abolito con la motivazione delle lamentele giunte per le vessazioni dell'ultimo duca Giacomo Crispo sulla popolazione. Nasso, Paro, Milo, Andro, Siro, Micono, Io, Amorgo e tutte le Cicladi circostanti furono poste sotto amministrazione ottomana diretta con un'unica decisione. Solimano il Legislatore affidò per un periodo l'amministrazione delle isole a Yasef Nasi; il dominio latino di tre secoli e mezzo ebbe così fine nel cuore dell'Egeo.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Rivolta dello Yemen e campagna di Koca Sinan Paşa nello Yemen", "c8218d8e"], "d": ["L'imam zaydita Mutahhar, adducendo la riscossione forzata delle imposte, si sollevò e sradicò l'amministrazione ottomana dalla maggior parte dello Yemen. Koca Sinan Paşa, inviato da Costantinopoli, con l'operazione condotta tra il 1568 e il 1570, dopo un lungo assedio prese Kawkaban e ristabilì il dominio ottomano nella regione. La campagna era di importanza vitale per conservare il controllo della porta meridionale del Mar Rosso e della rotta commerciale dell'Oceano Indiano.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Alleanza difensiva con il Sultanato di Aceh e aiuto nell'Oceano Indiano", "8e835f24"], "d": ["Gli ambasciatori di Aceh, che avevano chiesto aiuto a Solimano di fronte agli attacchi portoghesi, alla morte del sultano a Szigetvár presentarono la propria fedeltà a Selim II e con lui fu firmato un trattato difensivo. Il sultano ordinò l'invio da Alessandria di cannoni, fucili, munizioni e artigiani; furono preparate diciassette navi da guerra da inviare nelle acque indiane. Il crescere della rivolta dello Yemen impedì alla flotta di partire, ma gli artiglieri e gli artigiani ottomani giunti ad Aceh lasciarono una traccia duratura nella regione.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Sbarco a Cipro: presa di Limassol", "9074ccc9"], "d": ["L'esercito ottomano sbarcato sull'isola prese Limassol senza incontrare molta resistenza e il giorno dopo si diresse verso Larnaca. Poiché la popolazione locale era scontenta dell'amministrazione veneziana e aiutava le forze ottomane, anche a Larnaca non si incontrò una seria resistenza; lo scalo di Tuzla fu fatto base di sbarco di truppe e materiale. Venezia aveva concentrato la difesa a Nicosia e Famagosta; il governatore di Pafo comunicò la propria obbedienza al serdar solo dopo la caduta di Nicosia.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Conquista di Nicosia", "413d866b"], "d": ["Dopo un assedio iniziato il 25 luglio 1570 e durato quarantacinque giorni Nicosia, capitale di Cipro sotto amministrazione veneziana, si arrese all'esercito ottomano. La caduta del centro dell'isola strinse la resistenza veneziana nella fortezza di Famagosta. La conquista ebbe grande eco in Occidente e accelerò il processo che portò alla formazione, sotto la guida del papa, della flotta della Lega Santa.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Resa di Kyrenia — costa settentrionale di Cipro", "39fdeea5"], "d": ["La caduta di Nicosia il 9 settembre, passata a fil di spada, spezzò la resistenza nel nord di Cipro. La fortezza di Kyrenia, dietro i monti Beşparmak, appresa la sorte della capitale, si arrese a condizioni otto giorni dopo e la sua guarnigione fu fatta partire con il permesso di lasciare l'isola. Sull'isola la bandiera veneziana rimase solo a Famagosta, che avrebbe resistito ancora undici mesi.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Ricostruzione della flotta dopo Lepanto", "db51fe44"], "d": ["Il primo compito di Kılıç Ali Paşa, nominato kapudan paşa dopo la disfatta di Lepanto, fu ricostituire la flotta che aveva subìto gravi perdite; gli arsenali lavorarono senza sosta per tutto l'inverno 1571-1572. Nel giugno 1572 una nuova flotta di circa 250 galee e 300 galee di reis volontari uscì nel Mediterraneo. Questa rapida ripresa mostrò che Lepanto non aveva spezzato in modo duraturo la potenza navale ottomana.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Trattato di Costantinopoli con Venezia — riconoscimento di Cipro", "4d08ef50"], "d": ["Venezia, rimasta sola per lo scioglimento della Lega Santa, fece una pace separata con gli Ottomani, riconobbe ufficialmente che Cipro apparteneva agli Ottomani e accettò di pagare un'indennità di guerra. Il trattato mostrò chiaramente che la vittoria di Lepanto non aveva dato al mondo cristiano alcun guadagno politico. Venezia per settant'anni avrebbe evitato di entrare in guerra diretta con gli Ottomani.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Morte di Selim II", "c289f5ee"], "d": ["Selim II, dopo una caduta, per circa due mesi non poté presentarsi al divano e morì. La sua morte fu tenuta segreta a palazzo per dodici giorni, finché il figlio maggiore, Murad, che era a Manisa, non giunse a Costantinopoli. Sul giorno della morte le fonti divergono: Selânikî dice 15 dicembre; Gerlach, Mehmed b. Mehmed e Cenâbî dicono 13 dicembre.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Proclamazione della morte di Selim II e ascesa di Murad III", "84334d70"], "d": ["La morte di Selim II e l'ascesa di Murad III, portato da Manisa, furono proclamate ufficialmente il 22 dicembre 1574. Il nuovo sultano sarebbe rimasto sul trono ventun anni; il suo regno sarebbe stato ricordato per le lunghe guerre con l'Iran a oriente, la vigilia della Lunga Guerra a occidente e la svalutazione dell'akçe all'interno. Fino alla morte di Sokullu Mehmed Paşa nel 1579 nell'amministrazione dello Stato continuò il vecchio ordine.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Battaglia di Wadi al-Makhazin (Alcácer Quibir) — Abd al-Malik, sostenuto dagli Ottomani, annientò l'esercito portoghese", "21280dac"], "d": ["Abd al-Malik, salito al trono del Marocco con il sostegno ottomano, annientò a Wadi al-Makhazin il grande esercito del re del Portogallo Sebastiano; poiché nella battaglia morirono tre sovrani insieme, nelle fonti occidentali è detta «Battaglia dei Tre Re». La potenza militare portoghese crollò e il paese passò poco dopo in mano alla Spagna. Anche Abd al-Malik morì nella battaglia; il fratello subentrato, Ahmed al-Mansur, comunicò la vittoria a Costantinopoli con una delegazione. Il rapporto tra i due Stati rimase non di tributo né di sudditanza ma a livello di scambio di ambasciatori e doni, e poco dopo si tese per la questione dei doni.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Offerta di fedeltà degli abitanti di Derbent a Lala Mustafa Pascià — la Porta di Ferro sotto amministrazione ottomana", "9c55aeff"], "d": ["Durante la campagna dello Shirvan una delegazione di sette persone degli abitanti di Derbent si recò a Ereş dal serdar Lala Mustafa Pascià e offrì la propria fedeltà. Derbent (Demirkapı), che chiude lo stretto passaggio tra la muraglia caucasica e il Mar Caspio, passaggio obbligato delle vie terrestri dal nord, ebbe un ruolo chiave nel mantenimento dello Shirvan. Il dominio ottomano qui durò fino al 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Conquista dello Shirvan: presa di Shamakhi", "9afae4c1"], "d": ["L'esercito, che dopo la vittoria di Çıldır si era aperto verso il Caucaso, entrò nello Shirvan, la provincia più ricca dei Safavidi sulla costa del Caspio, e prese la città centrale Shamakhi. Özdemiroğlu Osman Pascià vi fu nominato beylerbey e il ramo settentrionale della Via della Seta fu messo sotto controllo ottomano. Lo Shirvan sarebbe divenuto il fronte che nella guerra orientale di dodici anni cambiò più volte di mano e costò di più.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Presa di Baku — accesso alla costa del Caspio", "eb5adab8"], "d": ["Come ultimo anello dell'operazione dello Shirvan fu preso il porto di Baku sulla costa occidentale del Mar Caspio. I pozzi di nafta intorno alla città erano già allora una fonte di reddito conosciuta e il porto era il punto di uscita della seta iraniana che giungeva attraverso il Caspio. L'Impero ottomano ebbe così, per la prima e unica volta nella sua storia, uno sbocco sul Mar Caspio.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Conquista di Erevan (Revan) e costruzione della fortezza", "7f623b7b"], "d": ["Ferhad Pascià, che a Kars aveva ricevuto l'ordine di andare a Erevan e di costruirvi una fortezza, marciò su Erevan e la città fu posta sotto controllo ottomano all'inizio del Ramadan 991 (metà settembre 1583). A Erevan, che tiene la porta settentrionale della valle dell'Aras, fu costruita una nuova e grande fortezza; la città fu fatta centro di beylerbeylik. Posta a metà della via dell'esercito tra Kars e Tabriz, Erevan era la spina dorsale logistica del fronte orientale. La fortezza fu costruita così solida che per i duecento anni successivi divenne l'obiettivo costante delle guerre ottomano-iraniane.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Annessione del Karabakh e di Ganja", "29abaead"], "d": ["Come ultimo guadagno della guerra orientale decennale Ferhad Pascià nel 1588 marciò su Ganja e il 1° settembre entrò in città; la regione del Karabakh tra Kura e Aras e il suo centro Ganja furono posti sotto amministrazione ottomana. Così Shirvan, Erevan e Karabakh si unirono formando nel Caucaso una linea ottomana ininterrotta. Il Trattato di Ferhad Pascià, firmato nel 1590, avrebbe sancito questo confine, ma il guadagno poté essere mantenuto solo per vent'anni.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Conquista di Bihać", "651a7275"], "d": ["Telli Hasan Paşa, beylerbey di Bosnia, dopo aver preso nel novembre 1591 Ripaç, fortezza avanzata di Bihać, nel 1592 prese anche la città e la fortezza stessa; dopo un assedio di dieci giorni il comandante Lamberg si arrese. Questa conquista spinse avanti il confine della Bosnia lungo il fiume Una e fu l'ultimo grande guadagno ottomano alla vigilia della Lunga Guerra, che sarebbe scoppiata un anno dopo con la morte da martire di Telli Hasan Paşa sul fiume Kupa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Inizio della «Lunga Guerra» ottomano-austriaca", "bd22c392"], "d": ["Quando il beylerbey di Bosnia Telli Hasan Paşa fu sconfitto e cadde martire sul fiume Kupa (Sisak), lo Stato ottomano dichiarò guerra all'Austria e iniziò la Lunga Guerra destinata a durare tredici anni. Questa guerra, in cui fu decisiva la fanteria con armi da fuoco, accelerò nell'ordinamento militare ottomano l'impiego di sekban e fucilieri e approfondì il declino dei sipahi con timar. La guerra sarebbe terminata nel 1606 con il trattato di Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Paşa partì per la campagna d'Austria — prima campagna della Lunga Guerra", "d4a2f46d"], "d": ["Dopo la sconfitta e la morte da martire del beylerbey di Bosnia Hasan Paşa davanti a Siska (Sisak), il gran visir Koca Sinan Paşa, con parole e promesse brillanti, convinse il sultano alla guerra e partì con 12.000 giannizzeri e altre unità. Così si aprì la prima campagna della guerra ottomano-austriaca che sarebbe durata tredici anni.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Conquista di Yanıkkale (Győr)", "14b75207"], "d": ["Il gran visir Koca Sinan Paşa, dopo un assedio di oltre un mese, ricevette la resa di Yanıkkale, considerata la chiave della strada di Vienna. La caduta della fortezza provocò grande panico in Europa e fu il guadagno più brillante degli Ottomani nella Lunga Guerra. Ma la fortezza avrebbe potuto essere tenuta solo quattro anni.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Morte di Murad III", "1b62e886"], "d": ["Dopo un regno di ventun anni Murad III morì nei giorni in cui l'esercito valacco incendiava İbrâil e si spingeva fino a Silistra e fu sepolto nel cimitero di Santa Sofia. Il figlio Mehmed III, chiamato da Manisa, giunse a Costantinopoli dieci giorni dopo e salì al trono (27 gennaio 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Perdita di Esztergom a favore dell'Austria", "f420d333"], "d": ["Nell'assedio condotto da Karl von Mansfeld i difensori di Esztergom, che non ricevevano sufficiente aiuto, consegnarono la fortezza all'arciduca Mattia. Con la fine del dominio ottomano di cinquantadue anni la catena difensiva sulla linea del Danubio fu spezzata e Buda fu direttamente minacciata. La fortezza sarebbe stata ripresa solo dieci anni dopo, nel 1605.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Conquista della fortezza di Eger", "3e511629"], "d": ["Dopo una lotta di tre settimane la poderosa fortezza di Eger, che gli Ottomani non erano mai riusciti a prendere, cadde con la resa dei difensori. Questa conquista, a cui fu presente il sultano, in qualche misura ripristinò il morale abbattuto dalla perdita di Esztergom e fu istituito l'eyalet di Eger. Insieme alla vittoria di Mezőkeresztes ottenuta due settimane dopo, il 1596 fu l'anno più riuscito degli Ottomani nella Lunga Guerra.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Perdita di Yanıkkale (Győr)", "b4ccc679"], "d": ["Le truppe al comando di Miklós Pálffy e Adolf von Schwarzenberg, facendo saltare con un attacco le porte della fortezza, ripresero Yanıkkale. La perdita della fortezza, ottenuta quattro anni prima con grandi fatiche da Koca Sinan Paşa, fece crollare la linea avanzata ottomana in Ungheria. Benché nello stesso anno le forze nemiche che assediavano Buda fossero respinte, l'equilibrio della guerra si trasformò progressivamente in una guerra di logoramento.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Rivolta di Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, che raccolse i sekban e i levend fuggiti dall'esercito nella Lunga Guerra, prese sotto il proprio controllo una vasta regione dell'Anatolia centrale, si impadronì della fortezza di Urfa (novembre 1599) e, proclamatosi sultano con il titolo di «Halim Şah», inviò firmani recanti il proprio tuğra. Considerato il primo capo della grande ondata dei Celâlî, Karayazıcı morì nel 1602 e il suo movimento fu proseguito dal fratello Deli Hasan. La rivolta è l'inizio del periodo della «grande fuga», in cui i contadini d'Anatolia abbandonarono in massa le terre.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Difesa di Kanije da parte di Tiryaki Hasan Paşa", "d56a5e6a"], "d": ["L'arciduca Ferdinando e i suoi alleati, che volevano riprendere Kanije, conquistata un anno prima, assediarono la fortezza per più di due mesi; Tiryaki Hasan Paşa resistette con una forza di 9000 uomini. Pur senza aiuti dall'esterno respinse gli assalti generali e con le sortite costrinse il nemico a ritirarsi con gravi perdite. La difesa è divenuta epica nella storiografia ottomana e l'«Assedio di Kanije» è diventato un genere letterario a sé.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Morte di Mehmed III e ascesa di Ahmed I", "da735fde"], "d": ["Alla morte di Mehmed III il 20 dicembre salì al trono il figlio quattordicenne Ahmed I. Il fatto che fosse il primo sultano ad assumere il trono in età infantile e senza essere stato inviato in sancak mostra che la prassi di far crescere i principi in provincia era di fatto finita. Sotto il regno di Ahmed I il fratricidio sarebbe stato abbandonato e si sarebbe passati al principio dell'«ekberiyet» (salita al trono del membro maschio più anziano).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Ripresa di Esztergom", "7330f273"], "d": ["Il gran visir Lala Mehmed Paşa assediò Esztergom, perduta dieci anni prima, e la riunì di nuovo all'amministrazione ottomana. Nella stessa campagna furono liberate anche Pest e Vác e gli Ottomani riordinarono la loro linea in Ungheria. Questo successo permise di sedersi al tavolo di Zsitvatorok l'anno seguente in posizione relativamente forte; Esztergom sarebbe rimasta in mano ottomana fino al 1683.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Vittoria della piana di Oruç e repressione della rivolta di Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Paşa, che aveva fondato un beylik indipendente ad Aleppo e cercava un'alleanza con la Toscana, fu duramente sconfitto nella piana di Oruç dal gran visir Kuyucu Murad Paşa. Con il ristabilimento dell'autorità centrale in Siria fu spezzato il ramo più pericoloso dell'ondata dei Celâlî. La spietata epurazione di due anni di Kuyucu Murad Paşa assicurò, almeno temporaneamente, l'ordine in Anatolia.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Vittoria di Alaçayır e repressione della rivolta di Kalenderoğlu", "55db0485"], "d": ["Kalenderoğlu, capo dei Celâlî che aveva sottoposto a tributo le zone di Manisa e Bursa, fu sconfitto ad Alaçayır da Kuyucu Murad Paşa e fu costretto a fuggire in Iran. Con questa vittoria fu disperso l'ultimo dei grandi eserciti dei Celâlî in Anatolia. La dura epurazione di Kuyucu Murad Paşa, che secondo la tradizione fece riempire di ribelli uccisi i pozzi fatti scavare, benché assicurasse l'ordine a breve termine, non poté compensare la perdita di popolazione e di produzione dell'Anatolia.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Concessione del primo ahidnâme all'Olanda", "5d9d117e"], "d": ["L'ambasciatore della Repubblica delle Province Unite Cornelis Haga riuscì a ottenere da Ahmed I un ahidnâme di contenuto uguale a quelli dati a Francia e Inghilterra. L'Olanda ottenne così il diritto di aprire un'ambasciata a Costantinopoli e consolati negli scali ottomani, nonché di commerciare con la propria bandiera. Questo ahidnâme simboleggia l'ingresso nel mercato ottomano delle potenze marittime del nord che avevano preso il posto di Venezia nel commercio mediterraneo.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Morte di Ahmed I e ascesa di Mustafa I — sistema dell'ekberiyet", "9901c09e"], "d": ["Dopo una malattia di stomaco durata cinquantun giorni morì Ahmed I, ventottenne, e al trono, al posto del figlio, fu portato il fratello Mustafa I. Così, abbandonato il sistema di successione di padre in figlio, si passò di fatto al sistema dell'«ekberiyet», in cui sale al trono il membro maschio più anziano della dinastia. Questo primo sultanato di novantasei giorni è anche l'inizio dell'epoca in cui i principi crescevano nel «kafes».", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Deposizione di Mustafa I e ascesa di Genç Osman (Osman II)", "e0f552f2"], "d": ["Con la motivazione che non era in buona salute mentale Mustafa I dopo novantasei giorni fu deposto e il quattordicenne figlio di Ahmed I, Osman II, divenne sultano. Secondo quanto riportato sulla base di Hasanbeyzâde, nella decisione di deposizione fu influente il capo degli eunuchi neri Mustafa Ağa. Genç Osman, con il progetto di abolire il corpo dei giannizzeri e costituire un nuovo esercito, è considerato il primo nome radicale nei dibattiti di riforma ottomani. Questo progetto quattro anni dopo gli sarebbe costato la vita.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Trattato di Serav — rinnovo della pace con l'Iran", "e778aca8"], "d": ["Il trattato di Serav, concluso con l'Iran dopo la disfatta di Pül-i Şikeste, confermò in gran parte le condizioni del trattato di Nasuh Paşa del 1612; la quantità annua di seta che i Safavidi avrebbero inviato fu ridotta da duecento a cento carichi. Si chiuse così la seconda fase delle guerre orientali in corso dal 1603. La pace non sarebbe stata longeva: con la perdita di Baghdad nel 1623 la guerra si sarebbe riaccesa.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Campagna di Chocim e trattato di Chocim", "bc4c823c"], "d": ["Contro il grande esercito comandato di persona da Osman II non si riuscì a superare il campo fortificato che Chodkiewicz aveva costruito davanti a Chocim e dopo assalti durati mesi non si ottenne alcun risultato. Con il trattato firmato il 9 ottobre il fiume Dnestr fu accettato come confine e i Polacchi si impegnarono a impedire le incursioni cosacche. La campagna, presentata come vittoria ma senza risultati, rafforzò la sfiducia del giovane sultano verso i giannizzeri e l'intenzione di epurare il corpo.", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["Presa di Hormuz ai Portoghesi", "93e5f6cf"], "d": ["Le forze safavidi assediarono e ripresero Hormuz, in mano portoghese dal 1515; anche Qeshm e Gamrun (Bandar Abbas) sulla costa passarono all'amministrazione safavide e il commercio del Golfo si spostò sul nuovo porto.", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Seconda deposizione di Mustafa I e ascesa di Murad IV", "1b3a9e74"], "d": ["Mustafa I, riportato per la seconda volta al trono dopo l'uccisione di Osman II, fu deposto di nuovo dopo un anno e tre mesi e l'undicenne Murad IV fu proclamato sultano. Per i primi nove anni lo Stato fu governato di fatto dalla madre Kösem Sultan e dai notabili di palazzo. Murad IV dal 1632 avrebbe preso in mano di persona il governo, inaugurando un periodo di dura centralizzazione.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Perdita di Baghdad a favore dei Safavidi", "db81be0c"], "d": ["Al termine delle trattative che Bekir Subaşı, sollevatosi a Baghdad, aveva intrapreso con i Safavidi, il figlio Derviş Mehmed, che difendeva la cittadella, consegnò la città alle forze dello shah Abbas. La perdita di una delle città simbolo dell'eredità del califfato e di gran parte dell'Iraq suscitò grande indignazione a Costantinopoli. Riprendere Baghdad per quindici anni sarebbe stato l'unico obiettivo della politica orientale ottomana.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Repressione della rivolta di Abaza Mehmed Pascià con centro a Erzurum", "e6da2729"], "d": ["Abaza Mehmed Pascià, beylerbey di Erzurum, che con il pretesto di vendicare l'uccisione di Osman II si era sollevato contro i giannizzeri, tenne per anni l'Anatolia orientale sotto il proprio controllo e resistette al centro. Costretto ad arrendersi con l'assedio di Erzurum condotto dal gran visir Hüsrev Pascià, fu perdonato e nominato in Bosnia. La fine della rivolta fu la condizione preliminare perché Murad IV potesse intraprendere la campagna contro l'Iran.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Prima esecuzione di uno şeyhülislam: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Con l'accusa di aver mediato nei tumulti militari e di aver inviato al sultano un ammonimento scritto sulla procedura giudiziaria, lo şeyhülislam Ahîzâde Hüseyin Efendi fu giustiziato presso Büyükçekmece. Essendo il primo şeyhülislam ottomano messo a morte, l'episodio ruppe la salda tradizione secondo cui la pena più grave per i membri dell'ilmiye era l'esilio. Il fatto è considerato il simbolo dell'autorità sempre più dura di Murad IV e dello squilibrio nei rapporti tra Stato e ulema.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Conquista di Erevan da parte di Murad IV", "b65a9b73"], "d": ["Partito da Istanbul il 28 marzo 1635, Murad IV pose l'assedio a Erevan il 28-29 luglio e l'8 agosto ricevette la resa della fortezza; entrò poi nella Tabriz evacuata e la fece devastare. In ricordo della vittoria il sultano fece costruire nel Palazzo di Topkapı il Padiglione di Erevan. Fu, dopo un intervallo di trent'anni, la prima grande campagna orientale in cui il sultano comandò personalmente l'esercito.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Perdita di Erevan a favore dei Safavidi", "fbb8dd25"], "d": ["Dopo il ritiro dell'esercito ottomano, le forze dello shah Safi assediarono Erevan e la ripresero entro otto mesi. La rapidità con cui la fortezza andò perduta mostrò quanto fosse difficile, sul piano logistico, un dominio stabile nel Caucaso. Erevan sarebbe stata lasciata all'Iran anche con il Trattato di Qasr-i Şirin del 1639, e l'Impero ottomano avrebbe rinunciato alle pretese sull'Azerbaigian.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Riconquista di Baghdad", "4d2f27f3"], "d": ["Partito da Istanbul l'8 maggio 1638, Murad IV, dopo un violento assedio di quaranta giorni, riprese Baghdad, da quindici anni in mano safavide; durante l'assedio cadde martire il visir Tayyar Mehmed Pascià. Con la conquista della città l'amministrazione ottomana fu ristabilita in Iraq e il sultano assunse il titolo di 'Conquistatore di Baghdad'. La conquista, consolidata l'anno seguente dal Trattato di Qasr-i Şirin, pose le basi dell'attuale confine tra Turchia e Iran.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Morte di Murad IV e ascesa al trono del sultano Ibrahim", "e2ca1ca0"], "d": ["Dopo la morte di Murad IV, a ventisette anni (ventotto secondo il computo hegirico), salì al trono il fratello Ibrahim, unico membro maschio superstite della dinastia. Nel regno del nuovo sultano, vissuto per anni nel kafes, le spese di palazzo e le lotte d'influenza a corte scossero l'ordine dello Stato. Otto anni dopo, la sua deposizione e uccisione avrebbe segnato il secondo regicidio della storia ottomana.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Riconquista della fortezza di Azak dai cosacchi", "e5fcf160"], "d": ["La fortezza di Azak, occupata nel 1637 dai cosacchi del Don, fu evacuata di fronte all'operazione congiunta di Sultanzâde Mehmed Pascià e del khan di Crimea Mehmed Giray IV; i cosacchi si ritirarono dando fuoco alla fortezza. La riconquista della porta settentrionale del Mar Nero chiuse il pericoloso periodo in cui le incursioni cosacche arrivavano fino al Bosforo. Nel 1696 la fortezza sarebbe stata però perduta a favore dello zar russo Pietro I.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Inizio della campagna di Creta e conquista di La Canea", "a1b0c77f"], "d": ["Con il pretesto che corsari maltesi avevano colpito una nave ottomana dei pellegrini rifugiandosi a Creta, fu dichiarata guerra a Venezia e la flotta al comando di Yûsuf Pascià sbarcò truppe sull'isola. Dopo cinquantaquattro giorni d'assedio la fortezza di La Canea fu presa e a Creta venne fondata la prima base ottomana stabile. Iniziò così la guerra più lunga della storia ottomana; l'isola sarebbe stata conquistata per intero solo ventiquattro anni dopo, nel 1669.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Conquista di Rettimo — Creta divisa in due", "8f2c4353"], "d": ["Un anno dopo la presa di La Canea cadde anche la fortezza di Rettimo, nel centro dell'isola, e la metà occidentale di Creta passò interamente sotto amministrazione ottomana. A Venezia rimasero soltanto la capitale Candia e l'estremità orientale; l'isola visse per ventitré anni divisa in due. La presa di Rettimo fu il passo che diede inizio all'assedio di Candia — l'assedio più lungo della storia iniziò qui.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Perdita di Clissa a favore di Venezia", "5473c22c"], "d": ["Sul fronte dalmata della Guerra di Creta (Candia), la controffensiva del comandante veneziano Leonardo Foscolo investì anche Clissa, capoluogo di sanjak dal 1537; la fortezza passò a Venezia. La concentrazione di tutte le forze ottomane su Creta rese impossibile recuperare questa perdita al confine dalmata: Clissa non sarebbe più tornata sotto amministrazione ottomana e il capoluogo del sanjak fu trasferito a Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Inizio dell'assedio di Candia", "13016b10"], "d": ["Dopo la presa di La Canea e Rettimo, l'esercito ottomano pose l'assedio a Candia, ultimo grande caposaldo di Venezia sull'isola. Questo blocco, destinato a durare ventun anni, è registrato come uno degli assedi più lunghi della storia militare mondiale. Durante l'assedio i tentativi della flotta veneziana di chiudere i Dardanelli avrebbero portato la guerra nel cuore dell'Egeo.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Uccisione della grande valide Kösem Sultan", "9d763f79"], "d": ["Kösem Sultan, di circa sessantadue anni, fu trovata in una stanza dell'harem e uccisa da Başlala Uzun Süleyman Ağa e dai suoi uomini, che agivano per ordine di Turhan Sultan, madre di Mehmed IV. La morte di questa potente donna della dinastia, che aveva orientato la politica dello Stato sotto tre sultani, è considerata la fine di fatto del cosiddetto 'Sultanato delle donne'. L'autorità rimasta vacante aprì la strada alla nomina, cinque anni dopo, di Köprülü Mehmed Pascià a gran visir con poteri straordinari.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Disfatta dei Dardanelli e perdita di Tenedo e Lemno", "e01a1f7e"], "d": ["La grande vittoria navale ottenuta dall'ammiraglio veneziano Mocenigo davanti ai Dardanelli nel giugno 1656 distrusse quasi del tutto la flotta ottomana; seguì l'occupazione di Tenedo, Lemno e Samotracia. Con lo Stretto sottoposto al blocco veneziano, i prezzi dei viveri a Istanbul schizzarono e nella capitale si diffuse il timore di un attacco. Questa catastrofe fu la causa diretta della nomina, nel settembre 1656, di Köprülü Mehmed Pascià a gran visir con condizioni e poteri straordinari.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Vittoria dei Dardanelli e riconquista di Tenedo", "603da863"], "d": ["La flotta mobilitata da Köprülü Mehmed Pascià sconfisse la flotta veneziana davanti allo Stretto il 19 luglio 1657; poi le forze al comando di Kurd Pascià ripresero Tenedo il 25 agosto e il 30 agosto i Veneziani evacuarono completamente l'isola. A novembre fu liberata anche Lemno, il blocco dei Dardanelli fu spezzato e la via dei rifornimenti di Istanbul fu riaperta. Köprülü si recò personalmente sull'isola e fece riparare le fortificazioni; il successo è il primo grande guadagno militare dell'epoca dei Köprülü.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Conquista di Yanova (Ineu) e campagna di Transilvania", "d1089616"], "d": ["Per punire il principe di Transilvania György II Rákóczi, che con una campagna non autorizzata in Polonia aveva violato la protezione ottomana, Köprülü Mehmed Pascià si mise in marcia e, passando per Belgrado, prese la strategica fortezza di Yanova. In Transilvania fu nominato un nuovo principe e il vincolo di vassallaggio fu ricordato con durezza. Questa campagna fu il primo anello del tentativo ottomano di ristabilire la propria autorità in Europa centrale. La Transilvania era già un principato tributario dell'Impero ottomano; la presa di Yanova non fu la conquista di un territorio di uno Stato straniero, ma sottrasse questa fortezza all'amministrazione del principato tributario e la annetté direttamente a un sanjak ottomano; il resto del principato rimase in condizione di vassallo.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Repressione della rivolta di Abaza Hasan Pascià", "4ba74321"], "d": ["Abaza Hasan Pascià, che contro le dure epurazioni di Köprülü Mehmed Pascià si era assicurato l'appoggio dei beylerbey anatolici e degli ağa dei sekban, diede inizio a una grande sollevazione chiedendo la destituzione del gran visir. La rivolta fu repressa ad Aleppo e i capi furono eliminati; fu l'ultima resistenza collettiva dei pascià di provincia contro il centro. L'autorità di Köprülü divenne così incontestata e la carica di gran visir tornò a essere il vero centro esecutivo dello Stato.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Conquista di Varad (Oradea)", "0e6ad300"], "d": ["Nel quadro della campagna condotta contro il principe di Transilvania György II Rákóczi, che aveva dichiarato guerra agli Ottomani, furono prese la fortezza e la città di Varad. Con la caduta di una delle fortezze chiave della Transilvania fu istituita nella regione una nuova provincia ottomana (eyalet di Varad). La conquista mise in allarme gli Asburgo e fu una delle cause dirette della guerra ottomano-austriaca che sarebbe iniziata tre anni dopo. Altri luoghi annessi alla stessa data: Varat. Anche qui il territorio non fu tolto a uno Stato straniero: la Transilvania era già un principato ottomano tributario; l'istituzione dell'eyalet di Varad sottrasse soltanto l'amministrazione di questa città al principato tributario per legarla direttamente al sultano, come due anni prima a Yanova.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Battaglia di San Gottardo (Szentgotthárd)", "61ebc1f2"], "d": ["Le forze ottomane che avevano attraversato il fiume Raab furono fermate dall'esercito europeo alleato al comando di Montecuccoli e subirono gravi perdite. La battaglia è considerata una svolta nella storia militare perché mostrò per la prima volta in modo chiaro la superiorità del tiro di fucileria della fanteria disciplinata sulla carica della cavalleria ottomana. Nonostante la sconfitta, nove giorni dopo l'Impero ottomano riuscì a ottenere condizioni vantaggiose nel Trattato di Vasvár.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Trattato di Vasvár", "089c978c"], "d": ["Firmato nonostante la disfatta di San Gottardo, il trattato stabilì che Uyvar e Varad rimanessero agli Ottomani, che la Transilvania restasse neutrale sotto la protezione ottomana e che l'Austria pagasse un 'dono' di 200.000 kuruş. Questa pace ventennale è uno dei rari esempi in cui la parte che ha perso la guerra ha guadagnato al tavolo delle trattative. Il malcontento suscitato dal trattato nell'opinione pubblica asburgica avrebbe alimentato il movimento dell'Ungheria centrale e, indirettamente, la campagna di Vienna del 1683.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Inizio del governo dei dey ad Algeri", "e99faa51"], "d": ["Il corpo di Algeri e la taife-i reîs (capitani corsari) deposero l'ultimo agha ed elessero dey, a vita, Hacı Mehmed. Da questa data Algeri fu governata non da un beylerbey nominato da Costantinopoli ma da un dey eletto dal corpo locale tra i propri membri; il legame ottomano si limitò alla lettura del nome del sultano nella khutba, al sancak e all'obbligo di campagna. Algeri passò così da eyalet a odjak — la stessa trasformazione la visse Tunisi nel 1705 con gli Husseinidi e Tripoli nel 1711 con i Karamanli.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Inizio della campagna di Polonia — Mehmed IV e Fâzıl Ahmed Pascià alla testa dell'esercito", "75e15a39"], "d": ["Poiché gli attacchi della Polonia contro l'atamano ucraino Petro Doroshenko, passato sotto la protezione ottomana, continuavano, Istanbul chiese al re polacco di rinunciare alle aggressioni; non giungendo risposta positiva, si decise la campagna contro la Polonia. Il gran visir Fâzıl Ahmed Pascià partì il 4 giugno 1672 alla volta della Polonia con l'esercito, accompagnato anche dal sultano. La campagna si sarebbe conclusa con la conquista di Kamianets e con il Trattato di Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Conquista di Kamianets e istituzione dell'eyalet di Podolia", "c3f4f6d0"], "d": ["Dopo un assedio di nove giorni fu ricevuta la resa di Kamianets, considerata la fortezza più forte della Polonia orientale; il 2 settembre Mehmed IV recitò la prima preghiera del venerdì nella cattedrale trasformata in moschea. Fatta della fortezza il centro, fu istituito l'eyalet di Podolia e la bandiera ottomana raggiunse il punto più settentrionale nei territori dell'odierna Ucraina. Kamianets sarebbe rimasta l'estremità nordoccidentale dell'Impero fino al Trattato di Karlowitz del 1699.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pascià riceve Uman dalla Polonia", "0d3543a0"], "d": ["Kara Mustafa Pascià, inviato contro la Polonia, ricevette la resa di Uman, una delle fortezze in mano polacca; la città rimase sotto amministrazione ottomana fino a Karlowitz.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Conquista della fortezza di Čyhyryn", "a17cedd0"], "d": ["Dopo l'operazione dell'anno precedente, in cui Melek İbrahim Pascià non aveva ottenuto risultati, il gran visir Merzifonlu Kara Mustafa Pascià, assumendo personalmente il comando, assediò la munita fortezza di Čyhyryn (19/21 luglio) e la prese il 21 agosto. La caduta della fortezza, simbolo della rivalità ottomano-russa sull'atamanato cosacco in Ucraina, costrinse la Russia alla pace. Questo successo fu anche una delle fonti della sicurezza di sé che avrebbe spinto Merzifonlu verso Vienna.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Trattato di Bakhchisaraj — prima pace ufficiale con la Russia", "df82bc0b"], "d": ["Al termine dei negoziati condotti con la mediazione del khan di Crimea dopo le campagne di Čyhyryn, fu firmata una pace ventennale tra l'Impero ottomano e la Russia, con il fiume Özü (Dnepr) riconosciuto come confine. Essendo il primo trattato di ampia portata tra i due Stati, è considerato il documento d'inizio delle relazioni ottomano-russe. Grazie alla pace il fronte orientale fu messo in sicurezza e l'esercito poté essere indirizzato verso l'Europa centrale.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Concessione del berat di re dell'Ungheria centrale a Imre Thököly", "3cd8d51d"], "d": ["Il nobile ungherese protestante Imre Thököly, sollevatosi contro la pressione asburgica, dall'aprile 1682 cominciò a essere considerato 're eletto dell'Ungheria centrale' e il 16 settembre il beylerbey di Buda İbrahim Pascià gli presentò le insegne principesche. Fu così fondato, sotto protezione ottomana, un nuovo Stato vassallo ungherese. Questo intervento rese inevitabile la guerra con l'Austria e avviò la catena che portò al secondo assedio di Vienna dell'anno seguente.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Perdita di Santa Maura (Leucade) a favore di Venezia", "e6905fee"], "d": ["La flotta di Venezia, entrata nella Lega Santa, dopo aver bombardato la città occupò l'isola di Santa Maura (Ayamavra) nel Mar Ionio. Con la caduta di Prevesa nello stesso anno, il controllo ottomano sull'imbocco dell'Adriatico fu spezzato. Queste perdite furono i passi iniziali dell'operazione con cui Morosini avrebbe conquistato l'intera Morea nell'arco di tre anni.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Perdita di Corone a favore di Venezia", "2ed762bc"], "d": ["Le forze veneziane al comando di Morosini presero la fortezza di Corone, all'estremità sudoccidentale della penisola di Morea; da allora la città sarebbe rimasta per trent'anni sotto amministrazione veneziana. La caduta di Corone fu il primo grande guadagno dell'operazione veneziana per la conquista della Morea. La fortezza poté essere ripresa solo nel 1715 dall'esercito ottomano al comando di Silâhdar Ali Pascià.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Ripresa di Atene — ritiro di Venezia", "03393b46"], "d": ["Morosini, che nel settembre 1687 aveva bombardato l'Acropoli e fatto saltare il Partenone, dopo aver trascorso l'inverno ad Atene capì che non poteva reggere in città. Per l'epidemia di peste, le difficoltà di rifornimento e la ripresa delle forze ottomane, la guarnigione veneziana evacuò la città ritirandosi in Morea. Atene tornò così sotto amministrazione ottomana senza combattere, ma la distruzione subita dal Partenone non poté essere recuperata.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) si arrese a Caraffa — passò in mano austriaca", "7f0a8d38"], "d": ["Dopo l'assedio di tre giorni di Antonio Caraffa, Lipova si arrese tra il 12 e il 22 giugno 1688 e passò in mano austriaca. Gli Ottomani ripresero poi la città, l'Austria la riprese nel 1691; nella campagna del 1695 gli Ottomani ristabilirono il controllo. Altri insediamenti che nell'atlante passarono dagli Ottomani agli Asburgo nella stessa data: Arad e Világos (Şiria). Per Arad la fonte dà solo l'anno (MKL, Arad: in mano ottomana tra il 1551 e il 1688); il giorno è stato preso da Lipova e Világos segue la catena di Arad (approssimazione dichiarata). Anche le fortezze di Lugos (Lugoj) e Karánsebes (Caransebeş) passarono all'Austria a fine giugno (Bánlaky 0016/1302 «Jenővel elveszett Lugos és Karánsebes»; 0017/1443 «június végén»).", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Respinto l'assedio veneziano di Negroponte", "aae7e6a0"], "d": ["Dopo aver conquistato la Morea, Morosini, rivolgendosi all'Egeo, tentò con un assedio di oltre tre mesi di prendere Negroponte; ma di fronte alle fortificazioni rafforzate e alla resistenza della guarnigione nell'inverno 1687-1688 dovette ritirarsi con gravi perdite. Il fallimento fermò l'avanzata veneziana nell'Egeo e scosse il prestigio militare di Morosini. Negroponte sarebbe rimasta in mano ottomana anche a Karlowitz.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Perdita della fortezza di Kanije a favore dell'Austria", "553b45f3"], "d": ["Posta dal gennaio 1690 sotto lo stretto blocco di un esercito asburgico di 60.000 uomini, Kanije, dopo aver resistito per mesi senza ricevere aiuti, fu perduta con l'accordo di resa firmato dal suo ultimo comandante Mustafa Pascià. Con ciò ebbe fine nella fortezza, ricordata per l'epica difesa di Tiryaki Hasan Pascià, un dominio ottomano di novant'anni. La perdita di Kanije fu il crollo dell'ultimo grande caposaldo ottomano nell'Ungheria occidentale.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Morte di Süleyman II", "d2478080"], "d": ["Süleyman II, fatto salire al trono nel 1687 dopo aver passato circa quarant'anni nel kafes, mentre malato seguiva i preparativi dell'esercito morì a Edirne verso mezzogiorno di venerdì 22 giugno 1691; il suo regno era durato tre anni, otto mesi e due giorni. Il gran visir aveva dato in anticipo le istruzioni necessarie perché, in caso di morte del sultano, salisse al trono il fratello Ahmed. La preghiera funebre fu fatta lo stesso giorno nel Padiglione di Alay; la salma fu portata a Istanbul e sepolta nel mausoleo di Solimano il Legislatore, alla sua destra.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Ascesa al trono di Ahmed II", "52947b14"], "d": ["Alla morte di Süleyman II, il fratello Ahmed II, di quarantanove anni, salì al trono a Edirne. Il suo regno coincise con gli anni più duri delle guerre della Lega Santa; due mesi dopo l'ascesa il gran visir Fâzıl Mustafa Pascià cadde martire a Slankamen. In compenso, il sistema del mâlikâne introdotto nel suo periodo fu una delle riforme più importanti che modificarono la struttura a lungo termine delle finanze ottomane.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Morte di Mehmed IV a Edirne", "17388b7e"], "d": ["Avcı Mehmed, deposto nel 1687, durante la campagna d'Ungheria di Süleyman II del 1689 fu portato a Edirne e vide anche il regno dell'altro fratello Ahmed II. Morì in questa città che amava molto. La salma fu portata a Istanbul e sepolta nel mausoleo della madre Turhan Sultan presso Yenicami.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Morte di Ahmed II a Edirne", "c6306c08"], "d": ["Ahmed II, il cui regno di quattro anni era trascorso in guerra, morì a Edirne a cinquantadue anni per istiskā (idropisia). La salma fu portata a Istanbul e sepolta nel mausoleo di Solimano il Legislatore. Gli successe il nipote Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Presa di Bassora da parte degli Iraniani", "a9cdf3a3"], "d": ["Mentre l'Impero ottomano era impegnato a ovest nelle guerre della Lega Santa, Bassora, dopo l'epidemia di peste del 1690, fu saccheggiata prima dallo sceicco dei Muntafiq Mani e poi da Faraj Allah, khan di Huwayza. Gli Iraniani, approfittando di questo disordine, nel 1696 presero la città e lasciarono a Bassora una guardia.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Trattato di Istanbul — cessione di Azak alla Russia", "79db4724"], "d": ["A Karlowitz con la Russia era stato possibile concludere soltanto una tregua di due anni; la pace duratura fu firmata a Istanbul dopo un anno e mezzo di aspre trattative. L'Impero ottomano cedette ufficialmente alla Russia la fortezza di Azak, perduta nel 1696, con i territori circostanti, e rinunciò al tributo annuo che il khan di Crimea riceveva da Mosca. In cambio la Russia ottenne il diritto di mantenere un ambasciatore permanente a Istanbul; la presenza russa sulla costa settentrionale del Mar Nero fu così sancita giuridicamente.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Pascià riprende Qurna e Bassora", "7adb777d"], "d": ["Daltaban Mustafa Pascià, nominato dopo il Trattato di Karlowitz governatore di Baghdad e seraschiere di Bassora, marciò verso sud con le forze di Aleppo, Raqqa, Sivas e Karaman e con una flotta fluviale discesa da Birecik. Gli sceicchi delle tribù circostanti si sottomisero uno a uno, il comandante della guardia iraniana di Bassora Davud Khan abbandonò la città e Qurna e Bassora tornarono sotto amministrazione ottomana.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Morte di Mustafa II", "626c394d"], "d": ["Mustafa II, che con l'Episodio di Edirne lasciò il trono al fratello Ahmed III, morì a Edirne, che amava molto, circa cinque mesi dopo la deposizione. Alla sua malattia si era aggiunto anche il dolore per gli ultimi sviluppi. Alcune fonti occidentali scrivono che tra la gente era diffusa l'opinione che fosse stato avvelenato.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Inizio del governo kölemen (mamelucco) a Baghdad", "abe52618"], "d": ["Con la nomina a governatore di Baghdad di Hasan Pascià, di origine georgiana, iniziò in Iraq il periodo in cui, al posto dei governatori nominati dal centro, predominò un ceto dirigente formatosi tra i suoi stessi schiavi. Con il governatorato di Süleyman Pascià nel 1749 il sistema si consolidò e la Sublime Porta fu costretta a nominare non più chi voleva, ma uno dei kölemen che avevano preso in mano l'influenza. Se questa struttura semiautonoma fu utile alla difesa del confine iraniano, indebolì per un secolo e mezzo il controllo dell'autorità centrale sull'Iraq.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Fondazione della dinastia husainide in Tunisia", "cb1a98f9"], "d": ["Nel vuoto di autorità creatosi dopo l'invasione della Tunisia da parte delle forze algerine, Hüseyin b. Ali, sipahi ağası di origine turca, si impadronì del beylicato e ottenne legittimità dichiarando la propria fedeltà al sultano ottomano. La dinastia da lui fondata governò la Tunisia nel 1705-1735 e nel 1756-1957; all'amministrazione degli ocak subentrò un ordinamento beylicale trasmesso di padre in figlio. Nacque così il primo esempio, negli ocak d'Occidente (Garp ocakları), di strutture dinastiche legate al centro ma di fatto autonome.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Presa di Orano e Mers el-Kébir agli Spagnoli", "b67ce06a"], "d": ["Le forze del beylerbey dell'Ocak di Algeri, dopo un lungo assedio, presero Orano e il porto di Mers el-Kébir, da due secoli in mano alla guarnigione spagnola. Fu il maggior successo ottenuto contro la Spagna nel Mediterraneo occidentale dagli ocak d'Occidente (Garp ocakları) posti sotto protezione ottomana e mise in sicurezza il fianco occidentale di Algeri. La città avrebbe subito una nuova occupazione spagnola nel 1732, ma sarebbe stata ripresa definitivamente nel 1792.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Trattato del Prut — restituzione di Azak e Taganrog", "bac5d2a1"], "d": ["Il trattato in sette articoli, firmato con la resa dell'esercito russo accerchiato sul Prut, stabilì la restituzione agli Ottomani della fortezza di Azak con il suo territorio e le munizioni. Le fortificazioni di Taganrog, Kamenka e Yenikale sarebbero state demolite e le parti non avrebbero costruito nuove fortezze in queste zone. L'assetto di flotta e basi creato da Pietro I nel corso di sedici anni a Voronež e Azak crollò; l'accesso della Russia al Mar Nero fu ritardato di circa cinquant'anni.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Fondazione della dinastia caramanlide in Tripolitania", "e1105d4a"], "d": ["In Tripolitania, esausta per le contese tra gli ağa dell'ocak, l'ufficiale di cavalleria Ahmed Karamanlı prese il potere e regolarizzò la propria posizione con il berat di beylerbey ottenuto da Istanbul. Con Ahmed Pascià, il figlio Mehmed Pascià e il nipote Yûsuf Pascià nacque una dinastia durata dal 1711 al 1835; emerse una struttura semi-indipendente, che creò una propria flotta e firmò trattati direttamente con gli Stati europei. Questo periodo sarebbe finito solo nel 1835, con il collegamento diretto della provincia al centro.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Trattato di Edirne con la Russia", "14901a70"], "d": ["Poiché le promesse fatte sul Prut non erano state mantenute, la guerra era stata dichiarata altre due volte; infine, con l'accettazione degli impegni da parte dei Russi, fu firmata a Edirne una pace duratura. Il trattato confermò le condizioni del Prut; la Russia non si sarebbe immischiata negli affari polacchi, si sarebbe ritirata dalle terre cosacche e non avrebbe ostacolato il ritorno in patria del re di Svezia Carlo XII. La chiusura del fronte settentrionale permise all'Impero ottomano di rivolgere lo sguardo ai fronti della Morea e di Venezia. Altri luoghi annessi alla stessa data: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Dichiarazione di guerra a Venezia — preparativi della campagna di Morea", "d970b122"], "d": ["Con la motivazione che Venezia sosteneva i ribelli montenegrini, sequestrava navi mercantili ottomane e opprimeva con pesanti imposte la Morea ottenuta a Karlowitz, il Divan decise la guerra. La campagna preparata dal gran visir Silâhdar Damad Ali Pascià si sarebbe conclusa l'anno seguente con la riconquista dell'intera penisola di Morea in meno di cento giorni. Ma questo successo avrebbe messo in moto l'Austria e nel 1716 avrebbe aperto la porta a una guerra ben più grave.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tino (İstendil): resa dell'ultima isola di Venezia nell'Egeo", "4abec891"], "d": ["La flotta partita per la campagna di Morea gettò l'ancora lungo la via davanti a Tino, l'unica isola rimasta a Venezia nell'Egeo. L'isola, che grazie alla popolazione latina aveva continuato per altri centocinquant'anni a battere bandiera veneziana nonostante la caduta del Ducato di Nasso nel 1566, si arrese dopo un breve assedio senza spargimento di sangue. Così fu cancellata l'ultima impronta di Venezia nel Mar Egeo e il mare divenne interamente un mare interno ottomano.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Conquista di Nauplia (Anabolu) — fortezza chiave della Morea", "62a5808a"], "d": ["Anabolu, capitale di Venezia in Morea e sua fortificazione più forte, cadde con la presa del bastione di Palamidi dopo nove giorni di bombardamento. La presa così rapida della fortezza spezzò la resistenza nel resto della penisola. La riconquista della Morea, perduta a Karlowitz, si completò di fatto qui. Altro insediamento che nell'atlante passa alla stessa data da Venezia agli Ottomani: Argos — segue la catena del suo centro di riferimento, Anabolu (TDV anabolu; approssimazione dichiarata).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Resa di Modone", "43faa909"], "d": ["Dopo la caduta di Nauplia la fortezza di Modone, all'estremità sudoccidentale della Morea, fu assediata dall'esercito da terra e dalla flotta dal mare e si arrese in breve tempo. Questo porto, usato per duecento anni da Venezia nelle sue campagne del Mediterraneo orientale, era il punto di approdo obbligato in cui le navi prendevano acqua e viveri. La sua perdita pose fine alla libertà di movimento della flotta veneziana nell'Egeo.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Resa di Corone — completamento della campagna di Morea", "e4b9c8a4"], "d": ["Con la resa della fortezza di Corone, che tiene l'imboccatura del golfo di Messenia, l'amministrazione veneziana nella penisola di Morea ebbe interamente fine. La penisola, perduta a Karlowitz, fu interamente ripresa a soli tre mesi dall'apertura della campagna. Nella prosecuzione della stessa campagna, nel settembre 1715, fu tolta a Venezia anche l'isola di Santa Maura (Leucade) nel Mar Ionio. Questa rapidità costrinse Venezia a trascinare l'Austria in guerra e tre anni dopo si aprì la strada verso Passarowitz.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Presa dell'isola di Citera (Çuha)", "494de6c6"], "d": ["L'isola di Citera, all'estremità meridionale della Morea, fu ricevuta in resa dalla flotta dopo il completamento della conquista della penisola. L'isola, che sorveglia il passaggio tra Mar Ionio ed Egeo, era l'avamposto che Venezia usava per controllare queste acque. Ma non rimase l'unica isola ottomana tenuta: tre anni dopo fu restituita a Venezia a Passarowitz.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Alleanza tra Austria e Venezia — la porta della guerra ottomano-austriaca del 1716-1718", "99511ca2"], "d": ["Dopo la ripresa della Morea da Venezia da parte degli Ottomani, l'Austria, sostenendo che il Trattato di Karlowitz era stato violato, firmò un trattato d'alleanza con Venezia; il principe Eugenio, in una lettera al gran visir, chiese la restituzione dei luoghi tolti a Venezia. Nelle consultazioni all'accampamento di Davutpaşa, per l'insistenza del gran visir Ali Pascià, fu dichiarata guerra all'Austria e per questo si ottenne la fatwa dallo şeyhülislam.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Il gran visir Ali Pascià parte per la campagna d'Austria", "2fbdce42"], "d": ["Dopo la dichiarazione di guerra all'Austria, il serdâr-ı ekrem Ali Pascià partì per la campagna d'Austria con un esercito di oltre 100.000 uomini; la flotta si diresse nella stessa estate verso Corfù. L'esercito avrebbe marciato da Belgrado su Varadino e nella disfatta dei primi di agosto il gran visir sarebbe caduto martire.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Disfatta di Varadino (Petrovaradin) — martirio di Damad Ali Pascià", "265c1d81"], "d": ["L'esercito ottomano, attraversato il Danubio da Belgrado, si scontrò davanti a Varadino con le forze austriache al comando del principe Eugenio; al primo slancio la carica dei giannizzeri forzò le trincee nemiche, ma con il crollo dell'ala di cavalleria le file si sbandarono. Il gran visir Silâhdar Damad Ali Pascià cadde martire, colpito alla fronte, e l'accampamento e il parco d'artiglieria passarono interamente in mano nemica. Questa disfatta, che le cronache ottomane ricordano come 'l'anno di Varadino', fu il primo anello della catena che portò alla perdita di Timișoara e, l'anno seguente, di Belgrado.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Fallimento dell'assedio di Corfù", "b2aa7011"], "d": ["Il seraschiere di Morea Kara Mustafa Pascià da terra e il kapudan pascià Canım Hoca Mehmed Pascià dal mare con la flotta si gettarono su Corfù; l'isola era la base chiave di Venezia nell'Adriatico. Ma la fortificazione estremamente robusta della fortezza, i rinforzi portati dalla flotta veneziana e le notizie della disfatta dal fronte del Danubio portarono a togliere l'assedio. La mancata presa di Corfù spense il clima di entusiasmo seguito alla riconquista della Morea e spostò il baricentro della guerra in Ungheria.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Perdita di Timișoara (Temeşvar) a favore dell'Austria", "27fe1365"], "d": ["Dopo la disfatta di Varadino il principe Eugenio marciò direttamente su Timișoara e la fortezza, al termine di un assedio di oltre quaranta giorni, si arrese con capitolazione. La città, conquistata nel 1552 al tempo di Solimano il Legislatore e considerata per 164 anni, come sede di beylerbeylik, il pilastro orientale della difesa dell'Ungheria, andò così perduta. Con la caduta di Timișoara l'intera regione del Banato passò all'Austria e il confine ottomano fu respinto a sud del Danubio. Altri insediamenti che nell'atlante passano alla stessa data dagli Ottomani agli Asburgo: Csákóvár, Facset e Karánşebeş (Caransebeş) — insieme alla cessione dell'eyalet di Timișoara (TDV timisvar; la fonte non dà il giorno per le singole località, catena del centro di riferimento, approssimazione dichiarata).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Resa della fortezza di Haram (Yeni Palanka) all'Austria — il Banato perde la riva del Danubio", "38ee4c6d"], "d": ["Dopo la caduta di Timișoara, il generale di cavalleria austriaco Mercy, incaricato di prendere il resto del Banato, il 14 novembre marciò su Haram (Yeni Palanka) sulla riva del Danubio; quando il 16 novembre giunse alla fortezza, la guarnigione ottomana di 200 uomini alzò bandiera bianca e si arrese a condizione di ritirarsi liberamente. Così anche la linea danubiana del Banato meridionale, in mano ottomana dal 1552, passò all'Austria. Altro insediamento che nell'atlante passa alla stessa data dagli Ottomani agli Asburgo: Versec — segue la catena del suo centro di riferimento, Haram (Bánlaky 0019/1703; approssimazione dichiarata).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Trattato di Passarowitz (Pasarofça) — la Morea guadagnata, Belgrado e il Banato perduti", "d46aa216"], "d": ["La Morea era stata ripresa a Venezia, ma l'Austria, entrata in guerra, con le vittorie ottenute a Petrovaradin e Belgrado ebbe il sopravvento al tavolo. Il trattato firmato con la mediazione di Inghilterra e Olanda lasciò la Morea agli Ottomani, ma in cambio, insieme a Belgrado, furono ceduti all'Austria la Serbia settentrionale, il Banato e la Piccola Valacchia; nelle parole del TDV 'la Bosnia settentrionale è stata lasciata interamente all'Austria' — fortezze come Bosanska Dubica e Bosanski Brod sulla Sava sulla mappa passano all'Austria da questo giorno (il confine preciso fu tracciato uno per uno dai commissari, il TDV non nomina queste fortezze); Venezia conservò invece le posizioni sulla costa ionica come Prevesa e Çuha. Con l'ahidnâme commerciale firmato lo stesso giorno il dazio riscosso sulle merci austriache fu ridotto dal cinque al tre per cento. Il trattato, sancendo il ripiegamento dell'Impero ottomano in Europa centrale, gettò con la pace ventisettenne che aprì le basi dell'Età dei Tulipani (1718-1730): sotto Nevşehirli Damad İbrahim Pascià la prima stamperia ottomana (1727, İbrahim Müteferrika), i comitati di traduzione, le osservazioni sull'inoculazione del vaiolo e una nuova vita di palazzo e di cultura sono frutto di questi anni di pace. Altri insediamenti che nell'atlante cambiano mano lo stesso giorno: Craiova, Râmnicu Vâlcea e Turnu Severin (Piccola Valacchia/Oltenia, dagli Ottomani all'Austria) e Santa Maura (Leucade) (dagli Ottomani a Venezia; TDV ayamavra: nel 1718 l'isola fu ceduta a Venezia con il Trattato di Passarowitz). Nella Piccola Valacchia passa inoltre all'Austria Târgu Jiu; Vonitsa (Voniçe, TDV pasarofca-antlasmasi) e l'isola di Cerigo (Citera, TDV cuka-adasi: articolo 3 di Passarowitz) passano a Venezia.", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Campagna orientale: presa di Tiflis e inizio della guerra con l'Iran", "78343dc2"], "d": ["Con il crollo dello Stato safavide per l'invasione afghana e la discesa della Russia sulle coste del Caspio, l'Impero ottomano inviò un esercito verso oriente perché il vuoto non cadesse interamente sotto l'influenza russa. Con la presa di Tiflis la Georgia fu legata all'amministrazione ottomana; poi l'avanzata proseguì in direzione di Ganja, Erevan e Nakhchivan. Questa campagna, condotta dietro l'apparenza pacifica dell'Età dei Tulipani, fu l'inizio di una lunga avventura orientale che sarebbe durata tredici anni e si sarebbe conclusa con la restituzione di tutto ciò che era stato conquistato.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Campagna d'Iran del 1723: ingresso nello Shirvan e in Georgia", "c81189fc"], "d": ["Con il crollo dello Stato safavide per l'invasione afghana, fu aperta una campagna verso oriente con la motivazione di impedire la discesa della Russia sulle coste del Caspio. L'esercito di Erzurum, attraverso la Georgia, entrò a Tiflis e il ramo dello Shirvan a Shamakhi, riprendendo i territori perduti centotrenta anni prima. Questa campagna fu l'ultima grande avanzata ottomana nel Caucaso.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Presa di Kermanshah — la porta degli Zagros", "ad14799f"], "d": ["L'esercito di Baghdad, superati i passi dei monti Zagros, prese Kermanshah, considerata la porta occidentale dell'Iran. La città si trovava sulla via delle carovane e dell'esercito da Baghdad a Isfahan e la sua presa assicurava la sicurezza orientale della provincia dell'Iraq. Questa avanzata diede inizio, nel dissolto paese safavide, alla corsa alla spartizione tra Ottomani e Russia.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Mukasemenâme di Istanbul — spartizione dell'Iran con la Russia", "fce8eec2"], "d": ["Per evitare lo scontro tra Ottomani e Russia sul territorio del crollato Stato safavide, con la mediazione dell'ambasciatore francese fu firmato un trattato di spartizione. Le coste occidentali e meridionali del Mar Caspio furono lasciate alla Russia; la Georgia, lo Shirvan, l'Azerbaigian e le città dell'Iran occidentale all'Impero ottomano. Questa spartizione, che sulla carta sembrava un grande guadagno, sarebbe divenuta di fatto nulla poco dopo con l'ascesa di Nadir Shah. Secondo il trattato, le fertili terre dello Shirvan come Şabran e Müşkür furono lasciate dalla parte russa (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Presa di Nakhchivan", "bdf14d0a"], "d": ["Le forze ottomane, avanzando lungo l'Aras, presero Nakhchivan e Ordubad; anche Julfa fu aggregata al livâ di Nakhchivan. La città fu legata, come porta nordoccidentale dell'Iran, al nuovo eyalet di Erevan. Il confine ottomano raggiunse così di nuovo la linea più orientale dell'epoca di Solimano il Legislatore.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Conquista di Hamadan", "e1339a97"], "d": ["L'esercito, marciato da Kermanshah verso est, dopo un lungo assedio prese Hamadan, alla soglia occidentale dell'altopiano iranico. La città era l'ultima grande tappa sulla via di Isfahan, il punto più orientale che gli eserciti ottomani avessero potuto raggiungere dalla Campagna dei Due Iraq. La Convenzione di Istanbul, firmata lo stesso anno con la Russia, mise su carta la spartizione dell'Iran dissolto tra Ottomani e Russia.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Nuova conquista di Erevan", "88acabef"], "d": ["Dopo un duro assedio di novanta giorni la fortezza chiave della valle dell'Aras, Erevan, entrò di nuovo sotto amministrazione ottomana. La fortezza, costruita nel 1583 e perduta nel 1604, fu questa volta fortificata con una guarnigione più forte. La lunghezza dell'assedio era un indicatore che l'esercito ottomano non avanzava più facilmente. Anche i nahiye di Karpi (Üçkilise), Şerür, Maku e Şüregel furono legati all'eyalet di Erevan.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Presa di Tabriz — conquista dell'Azerbaigian", "e502a4f7"], "d": ["Tabriz, assediata di nuovo dopo il tentativo fallito dell'anno precedente, si arrese all'esercito ottomano dopo un aspro combattimento strada per strada. Anche Merend, Marāgheh e Sovukbulak (Mahabad), dipendenti dalla provincia di Tabriz, passarono sotto amministrazione ottomana. Nello stesso anno furono prese anche Lori, Ganja, Ardabil e Khorramabad, e le regioni spettanti agli Ottomani secondo il Mukasemenâme di Istanbul furono di fatto occupate. L'estensione raggiunta a oriente fu il confine più avanzato dopo il periodo del Trattato di Ferhad Pascià; tuttavia mantenerla gravò pesantemente sull'esercito e sul tesoro.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Conquista di Ganja — fine della campagna del Caucaso", "875bca7a"], "d": ["Ganja, ultimo obiettivo dell'operazione nel Caucaso, fu ricevuta in resa come centro del Karabakh tra Kura e Aras. Con il completamento della linea Shirvan, Erevan, Nakhchivan e Ganja l'Impero ottomano raggiunse nel Caucaso l'estensione del 1590. Ma questo guadagno ebbe vita breve: l'ascesa di Nadir Shah entro dieci anni avrebbe ripreso tutta la regione.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Trattato di Hamadan — annessione dell'Iran occidentale all'Impero ottomano", "94a29dc3"], "d": ["Con il trattato firmato con il sovrano afghano Ashraf Shah ebbe fine la guerra di quattro anni e i territori dell'Iran occidentale occupati dall'Impero ottomano furono riconosciuti giuridicamente. In cambio Ashraf Shah riconobbe il califfato del sultano ottomano e si impegnò a far recitare in Iran la khutba a nome del sultano. Questa vittoria diplomatica ebbe breve durata; la controffensiva lanciata nel 1730 da Nadir Shah avrebbe cancellato in pochi anni i guadagni del trattato.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hekimoğlu Ali Pascià prende Urmia (Rûmiye)", "eac7f64d"], "d": ["Nella campagna d'Iran Hekimoğlu Ali Pascià prese prima Urmia (Rûmiye), poi Tabriz, evacuata a favore degli Ottomani, il 15 novembre 1731. Il TDV non dà il giorno della presa di Urmia; si sa solo l'anno e che venne prima di Tabriz.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Trattato di Ahmed Pascià — restituzione della maggior parte dell'Iran occidentale", "590d839f"], "d": ["In seguito alla vittoria di Nadir Shah a Malayer e agli attacchi iraniani susseguitisi, il governatore di Baghdad Ahmed Pascià firmò un testo di pace senza consultare il centro. Secondo il trattato fu riconosciuto come confine il fiume Aras; le città dell'Iran occidentale come Hamadan, Kermanshah, Ardalan, Ardabil e Tabriz furono restituite all'Iran, mentre Ganja e Tiflis rimasero agli Ottomani. Accolto con reazioni negative a Istanbul, il testo fu ritenuto insufficiente anche da Nadir Shah e la guerra si riaccese prima che il 1732 terminasse. L'atlante considera passata in questo giorno dagli Ottomani ai Safavidi anche Kotur, che segue la catena di Hoy (TDV hoy; la fonte non dà un giorno specifico per Kotur — approssimazione dichiarata).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Nuova perdita di Orano a favore della Spagna", "20485027"], "d": ["La grande flotta di sbarco inviata dal re di Spagna Filippo V, giunta davanti a Orano al comando del conte di Montemar, sconfisse le forze dell'Ocak di Algeri e riprese la città. Il porto, conquistato ventiquattro anni prima, sarebbe rimasto per sessant'anni in mano a una guarnigione spagnola. Questa perdita, che mostrò i limiti della potenza degli ocak del Maghreb ottomano (Garp ocakları) nel Mediterraneo occidentale, poté essere compensata solo con la conquista definitiva di Orano nel 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Riforma all'europea dell'Ocak degli humbaracı e fondazione dell'Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pascià, di origine francese, entrato al servizio ottomano, con il sostegno del gran visir Hekimoğlu Ali Pascià fece del corpo degli humbaracı un'unità salariata e ordinata all'europea. A trecento soldati reclutati in Bosnia fu impartita una formazione regolare basata su calcolo e geometria; furono preparati nuovi regolamenti per organizzazione, equipaggiamento e pensionamento e con tecnica moderna furono fabbricati cento mortai e cinquantamila bombe. L'Humbarahâne, dove si insegnava la geometria, è considerato il primo nucleo dell'istruzione di ingegneria militare moderna nell'Impero ottomano.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Morte di Ahmed III", "455f7fba"], "d": ["Ahmed III, deposto nel 1730 con la rivolta di Patrona Halil, trascorse gli ultimi sei anni di vita nell'appartamento del Palazzo di Topkapı riservato ai sultani deposti e morì a sessantatré anni. Fu sepolto a Bahçekapı, nel mausoleo della nonna Turhan Sultan presso Yenicami.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Trattato di Istanbul — cessione del Caucaso meridionale all'Iran", "8c205aab"], "d": ["La seconda guerra con l'Iran, durata quattro anni, si concluse con il trattato firmato dopo la disfatta di Arpaçay e la perdita di Ganja e Tiflis. L'Impero ottomano si ritirò da tutti i territori del Caucaso meridionale e dell'Iran occidentale conquistati dal 1723; il confine tornò alla linea di Qasr-i Şîrin del 1639. Dalle campagne orientali durate tredici anni rimasero un pesante onere finanziario e un tesoro svuotato; in compenso, per la nuova guerra iniziata con la Russia la chiusura del fronte orientale fu un vantaggio vitale.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Caduta della fortezza di Özi (Očakiv) in mano russa", "f93e61f3"], "d": ["L'esercito russo al comando del maresciallo Münnich assediò la fortezza di Özi alla foce del Dnepr; con l'esplosione del deposito di munizioni la difesa crollò e la fortezza cadde con gravi perdite. La perdita di Özi, considerata la chiave della costa nordoccidentale del Mar Nero, aprì ai Russi la via per la Crimea e provocò grande panico a Istanbul. L'anno seguente la fortezza, evacuata dai Russi per epidemia e difficoltà di rifornimento, sarebbe tornata agli Ottomani.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Vittoria di Banja Luka — liberazione della Bosnia", "f603865a"], "d": ["Quando le forze austriache entrarono in Bosnia e assediarono Banja Luka, il governatore di Bosnia Hekimoğlu Ali Pascià accorse in aiuto con le forze raccolte tra la popolazione locale e inflisse una grave sconfitta al nemico superiore di numero. Questa vittoria fece crollare fin dalla prima mossa il piano austriaco di occupare la Bosnia e il nord della provincia fu interamente riconquistato. Banja Luka fu uno dei punti di svolta che risollevarono il morale dell'esercito ottomano, in continua ritirata di fronte all'Austria dopo il 1683.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Vittoria di Hisarcık (Grocka) — apertura della strada per Belgrado", "2101cdff"], "d": ["L'esercito austriaco, che avanzava per proteggere Belgrado, fu attirato in un'imboscata in una stretta gola sulla riva del Danubio e subì gravi perdite in un combattimento durato tutto il giorno. Mentre le forze del maresciallo Wallis si ritiravano disordinatamente verso Belgrado, l'esercito ottomano giunse davanti alla fortezza e iniziò l'assedio. Hisarcık fu la vittoria in campo aperto più netta ottenuta contro l'Austria dopo Karlowitz e rese possibile direttamente la riconquista di Belgrado.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Trattato di Niš — pace con la Russia, neutralizzazione di Azov e cessazione delle incursioni in Crimea", "674f974e"], "d": ["La Russia, rimasta sola dopo che l'Austria aveva acconsentito alla pace a Belgrado, fu costretta a porre fine alla guerra con la mediazione dell'ambasciatore francese Villeneuve. Le fortificazioni della fortezza di Azov furono demolite e la regione fu dichiarata territorio neutrale tra i due Stati; la Russia accettò la condizione di non tenere navi da guerra e mercantili sul Mar Nero. L'obiettivo russo di aprirsi al mare fu così rinviato di una generazione e l'Impero ottomano si alzò dal tavolo da vincitore per l'ultima volta nel XVIII secolo.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi ritorna dopo l'occupazione russa: consegnata dopo la demolizione della fortezza con la pace del 1739", "7ecc2bef"], "d": ["I Russi avevano preso Özi l'11 luglio 1737. In forza della pace conclusa con la Russia nel 1739, le fortificazioni furono demolite e la fortezza fu consegnata di nuovo agli Ottomani; gli Ottomani la tennero fino al 1788, prima del Trattato di Iași.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Difesa di Mosul — respinto Nadir Shah", "c03ffbc1"], "d": ["Nadir Shah, giunto davanti a Mosul dopo aver preso Kirkuk e Erbil, bombardò la città per quaranta giorni e lanciò attacchi generali successivi. La difesa condotta dal governatore Hüseyin Pascià al-Jalili, che armò anche la popolazione cittadina, costrinse l'esercito iraniano a togliere l'assedio con gravi perdite. La tenuta di Mosul evitò la perdita dell'intero Iraq e consolidò per un secolo l'influenza della famiglia al-Jalili nella città.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Alleanza di Dir'iyya — fondazione del primo Emirato saudita nel Najd", "188751bf"], "d": ["L'emiro Muhammad b. Saud, che a Dir'iyya prese sotto la propria protezione lo studioso Muhammad b. Abd al-Wahhab, cacciato da Uyayna, stipulò con lui un'alleanza che metteva l'autorità politica al servizio della predicazione religiosa. Questo accordo inaugurò una nuova storia per la famiglia Saud e riunì intorno a un solo movimento gli emirati di oasi sparsi del Najd. Questa forza, che nel giro di mezzo secolo si sarebbe estesa fino a Kerbela, alla Mecca e a Medina, avrebbe costretto l'Impero ottomano a difendere il proprio dominio nell'Hijaz.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Trattato di Kerden — fine delle guerre ottomano-iraniane", "1d3a919e"], "d": ["Con il trattato firmato dopo l'ultima guerra, durata quattro anni, il confine di Qasr-i Şîrin del 1639 fu rinnovato tale e quale; nessuna delle due parti ottenne guadagni territoriali. La richiesta insistente di Nadir Shah che il giafarismo fosse riconosciuto come quinta scuola giuridica rimase senza risposta; in cambio si decise che i pellegrini iraniani potessero compiere liberamente il hajj e che vi fosse scambio reciproco di ambasciatori. Le guerre ottomano-iraniane, durate oltre due secoli, si chiusero così di fatto; questo confine è rimasto in larga parte invariato fino a oggi.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Morte di Mahmud I e ascesa al trono di Osman III", "30203700"], "d": ["Mahmud I, che nel suo regno di ventiquattro anni aveva recuperato i territori perduti con il Trattato di Belgrado e aveva sostenuto la riforma dell'Ocak degli humbaracı, morì al ritorno dal selâmlık del venerdì. Gli successe il fratello Osman III, che aveva vissuto la vita del kafes fino a cinquantotto anni. Iniziò un regno breve e inquieto; sotto Osman III, che in tre anni cambiò sei gran visir, negli affari di Stato dominò una marcata stagnazione.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Morte di Osman III e ascesa al trono di Mustafa III", "3ac10f85"], "d": ["Dopo il regno di tre anni, con la morte di Osman III salì al trono Mustafa III, aperto alle idee di riforma e attento da vicino agli affari di Stato. Il nuovo sultano, fondandosi sull'esperienza del gran visir Koca Râgıb Pascià, cercò di risanare le finanze e di rinnovare l'esercito; in questo periodo furono creati i sürat topçuları (artiglieri a tiro rapido) del barone de Tott. Ma la guerra con la Russia, intrapresa nel 1768, avrebbe oscurato tutti i risultati del regno di diciassette anni.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Dichiarazione di guerra alla Russia — l'episodio di Balta e inizio della guerra del 1768-1774", "9c6aabe0"], "d": ["Quando i reparti russi e cosacchi, inseguendo la Confederazione di Bar in Polonia, assalirono e incendiarono la cittadina di Balta al confine ottomano, il Divan decise la guerra e l'ambasciatore russo fu imprigionato a Yedikule. La guerra, intrapresa senza seri preparativi militari e dichiarata con sei mesi di anticipo, andò male fin dall'inizio. Questo conflitto, destinato a durare sei anni, si sarebbe trasformato, con l'incursione di Çeşme, la disfatta di Kartal e l'occupazione della Crimea, in una delle più gravi serie di sconfitte della storia ottomana.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Perdita della fortezza di Chotyn (Hotin) a favore dei Russi", "66d43ea4"], "d": ["Respinti due tentativi dell'esercito russo al comando del principe Golicyn, dopo la disfatta subita dal gran visir tra Kamianets e Hotin l'esercito si ritirò e la guarnigione evacuò la fortezza. La perdita senza resistenza della più forte fortificazione ottomana a nord del Danubio aprì ai Russi le porte di Valacchia e Moldavia. I due principati furono occupati nello stesso anno; Hotin poté essere recuperata soltanto nel 1774 con il Trattato di Küçük Kaynarca.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Disfatta della piana di Kartal (Kagul)", "6f408eaf"], "d": ["Tre settimane dopo l'incendio della flotta a Çeşme, il principale esercito ottomano sul Danubio si disperse nella piana di Kartal di fronte alle truppe, numericamente molto più piccole ma disciplinate, del maresciallo Rumjancev. Accampamento, salmerie e centinaia di cannoni caddero in mano nemica; le truppe in fuga subirono gravi perdite nell'attraversare il Danubio. La distruzione, nella stessa estate, sia della flotta sia dell'esercito di terra portò alla caduta una dopo l'altra di Kilia, Akkerman, Ismail e Bender e all'occupazione della Crimea.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Occupazione russa della penisola di Crimea", "217837b0"], "d": ["Le armate russe, che un anno prima avevano preso il Bucak, al comando del principe Dolgorukov superarono Or Kapı e invasero l'intera penisola di Crimea. Il khan fu deposto e, con l'insediamento del filorusso Sahib Giray, fu compiuto il primo passo verso il distacco del khanato dagli Ottomani. La perdita della Crimea, da tre secoli scudo settentrionale dell'Impero ottomano, fu l'inizio del processo che portò all'indipendenza nel 1774 e all'annessione diretta nel 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Morte di Mustafa III e ascesa al trono di Abdülhamid I", "42cba8e2"], "d": ["Al posto di Mustafa III, morto nel momento più critico della guerra con la Russia, salì al trono a quarantanove anni il fratello Abdülhamid I, che aveva trascorso quarantatré anni nel kafes del palazzo. Il nuovo sultano, ereditando uno dei periodi più difficili dello Stato, dovette affrontare le dure condizioni del Trattato di Küçük Kaynarca che sarebbe stato firmato nello stesso anno. Il suo regno di quindici anni sarebbe trascorso tra la perdita della Crimea e una nuova guerra con la Russia, e si sarebbe concluso nel 1789 con la paralisi che lo colpì mentre leggeva la notizia della caduta di Özi.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Disfatta di Kozluca — la sconfitta che portò a Küçük Kaynarca", "8e0542f9"], "d": ["Le forze ottomane riunite davanti a Şumnu furono sconfitte a Kozluca dalle colonne congiunte di Suvorov e Kamenskij e gran parte dell'esercito si disperse. Con questa disfatta nei Balcani non rimase alcuna forza in grado di resistere; le avanguardie russe assediarono Şumnu e il quartier generale del gran visir fu minacciato. Il fatto che in meno di un mese ci si sia seduti al tavolo a Küçük Kaynarca e siano state accettate condizioni straordinariamente pesanti è conseguenza diretta di questa sconfitta.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Cessione della Bucovina (Moldavia settentrionale) all'Austria", "190f9caa"], "d": ["L'Austria, approfittando della debolezza causata da Küçük Kaynarca, chiese la regione della Bucovina, che assicurava il collegamento tra Moldavia e Transilvania, e ottenne questo territorio senza entrare in guerra, con minacce e corruzione. La perdita di questa regione fertile e strategica a sud-ovest di Hotin divise di fatto in due il voivodato di Moldavia. Questa cessione, avvenuta senza sparare un colpo, fu considerata uno degli indicatori più chiari che l'Impero ottomano aveva ormai perso la capacità di deterrenza. Con la cessione della Bucovina nel 1775 Suceava e Černivci passarono all'Austria (giorno non confermato).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Occupazione iraniana di Bassora", "0161e709"], "d": ["Sadiq Khan, fratello del sovrano zand Karim Khan, dopo un assedio durato un anno prese Bassora, e l'Impero ottomano perse il suo porto più importante nel Golfo Persico. L'occupazione colpì direttamente la via commerciale dell'India, le entrate dei datteri e delle perle e la difesa meridionale dell'Iraq. La città poté essere ripresa solo nel 1779, durante le lotte per il trono scoppiate in Iran con la morte di Karim Khan.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Tenkihnâme di Aynalıkavak — intesa provvisoria sulla Crimea", "9b3b0468"], "d": ["I due Stati, giunti sull'orlo della guerra per la questione di chi dovesse salire al vertice del khanato di Crimea, con la mediazione della Francia firmarono un testo esplicativo nel Palazzo di Aynalıkavak. La Russia accettò di ritirare le truppe dalla Crimea e l'Impero ottomano di riconoscere il khanato del filorusso Şahin Giray; fu confermato il diritto di califfato religioso del sultano sulla Crimea. Questo fragile equilibrio, destinato a durare quattro anni, sarebbe crollato del tutto nel 1783 con l'annessione diretta della penisola da parte della Russia.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Costruzione della fortezza di Anapa — linea di difesa caucasica", "be92a80f"], "d": ["Quando con Küçük Kaynarca la Crimea andò perduta, per mantenere l'influenza ottomana nel Caucaso si intraprese la costruzione di una nuova fortezza alla foce del fiume Kuban. Anapa, fondata sui resti di una colonia genovese, con il suo bazar, i suoi bagni e più di duecentocinquanta botteghe divenne presto una città che assicurava il collegamento con le tribù circasse. La fortezza rimase per quarantotto anni l'avamposto più avanzato degli Ottomani contro la discesa della Russia nel Caucaso.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Destituzione ed esecuzione del gran visir Halil Hamîd Pascià", "c44001ca"], "d": ["Il gran visir riformatore Halil Hamîd Pascià, di cui Abdülhamid I aveva mostrato in varie occasioni la soddisfazione per i servigi, verso la mattina del 31 marzo 1785 fu improvvisamente destituito ed esiliato a Gallipoli e tutti i suoi beni furono confiscati. Gli furono dapprima dati l'eyalet d'Abissinia, il sanjak di Gedda e lo şeyhülharemlik della Mecca; mentre trascorreva l'aprile 1785 a Bozcaada preparando il viaggio, fu destituito anche da questa carica e con il firmano di esecuzione emesso fu ucciso da Karakethüdâzâde Ali, uno degli uomini di Cezayirli Gazi Hasan Pascià. La sua testa mozzata fu inviata a Istanbul ed esposta a Ortakapı. Secondo il TDV questa caduta improvvisa è stata interpretata con l'accusa di un complotto per deporre il sultano e metterne al posto lo şehzade Selim, ma le vere cause furono verosimilmente l'indignazione per il suo silenzio sull'annessione della Crimea, l'ostilità degli ambienti colpiti dalle sue riforme e l'opposizione di Gazi Hasan Pascià.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Dichiarazione di guerra alla Russia — inizio della guerra ottomano-russa del 1787-1792", "3bfb870c"], "d": ["Dopo il fastoso viaggio in Crimea di Caterina II e dopo che ella ebbe posto la Georgia sotto la propria protezione, il Divan decise la guerra con l'obiettivo di annullare l'annessione e l'ambasciatore russo fu di nuovo rinchiuso a Yedikule. Ma l'esercito non era pronto, il tesoro era vuoto e la ricerca di alleati era stata vana. La guerra, destinata a durare cinque anni, si sarebbe conclusa con la caduta di Özi con massacro, la perdita di Ismail e le dure condizioni del Trattato di Iași.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Entrata in guerra dell'Austria — lotta su due fronti", "ae912290"], "d": ["In forza dell'alleanza segreta stipulata con la Russia nel 1781, l'imperatore austriaco Giuseppe II dichiarò guerra all'Impero ottomano e mosse in direzione di Belgrado e della Bosnia. L'esercito ottomano si trovò all'improvviso a dover combattere su due fronti, la Russia a nord e l'Austria a ovest. Nonostante le vittorie sugli Austriaci a Lazarethane, Mehadia e Șebeș, con la perdita di Belgrado nel 1789 anche il fronte occidentale sarebbe crollato.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Alleanza ottomano-prussiana", "03b88e51"], "d": ["Selim III, che cercava alleati in Europa appena salito al trono, firmò con la Prussia un trattato d'alleanza che prevedeva mutuo soccorso; la Prussia si impegnava a dichiarare guerra a Russia e Austria, e l'Impero ottomano a non fare la pace finché la Crimea non fosse stata recuperata. Fu il primo vero testo di alleanza reciproca firmato nella storia ottomana con uno Stato europeo e mostrava l'abbandono della concezione classica secondo cui 'non c'è alleanza con gli infedeli'. La Prussia non entrò in guerra, ma costringendo l'Austria alla pace spianò la strada al Trattato di Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Caduta e massacro della fortezza di Ismail", "6a296b0c"], "d": ["La fortezza di Ismail, considerata la più forte fortificazione del delta del Danubio, fu presa in un giorno con un sanguinoso assalto generale organizzato dal generale Suvorov; la guarnigione e la popolazione della città furono in gran parte passate a fil di spada. Questo massacro, che ebbe vasta eco in Europa, provocò un profondo shock nell'opinione pubblica ottomana e spezzò la spina dorsale della linea di difesa danubiana. La fortezza sarebbe stata restituita un anno dopo con il Trattato di Iași, ma il destino della guerra era ormai segnato.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Trattato di Sistova — chiusura del fronte austriaco", "58741f1d"], "d": ["Grazie alla pressione della Prussia e al fatto che la Rivoluzione francese impegnava l'Austria a ovest, i due Stati giunsero alla pace sulla base dei confini prebellici. L'Austria restituì tutti i luoghi occupati, compresa Belgrado; l'Impero ottomano accettò soltanto piccole rettifiche al confine croato. La chiusura del fronte occidentale a queste condizioni permise all'Impero ottomano di concentrare tutte le forze contro la Russia e limitò la perdita a Iași. Con queste rettifiche al confine croato Cetin (Cetingrad) e Drežnik Grad passano dagli Ottomani agli Asburgo (TDV zistovi-antlasmasi; Korić 2016, n. 118, art. 4). Orsova (Eski Orsova) è invece l'unico luogo non restituito (Bánlaky 0019/1796); l'atlante scrive in questo giorno il trasferimento giuridico (occupazione di fatto il 16 aprile 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Trattato di Iași — perdita definitiva della Crimea e confine sul Dnestr", "a56fd194"], "d": ["Con il trattato firmato al termine della guerra di cinque anni il fiume Turla (Dnestr) fu riconosciuto come confine; la riva sinistra del fiume rimase alla Russia, la destra agli Ottomani, e Özi con i dintorni andò perduta definitivamente. L'Impero ottomano abbandonò del tutto la speranza di riprendere la Crimea e riconobbe giuridicamente l'annessione del 1783; Valacchia e Moldavia furono restituite con due anni di esenzione fiscale. Accettato anche l'obbligo di un'indennità di guerra di dodici milioni di kuruş, il nord del Mar Nero fu lasciato in modo permanente alla Russia. Altri luoghi annessi alla stessa data: İsmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Evacuazione di Orano (Vehrân) da parte degli Spagnoli e cessione ad Algeri", "9f95cee6"], "d": ["Quando nel terremoto del 1790 fortezza e città furono in gran parte distrutte, la Spagna, che non poteva più sostenere la costosa guarnigione mantenuta da tre secoli, accordandosi con l'ocak di Algeri cedette Orano e Mers el-Kébir senza guerra. Fu così liquidata anche l'ultima posizione europea sulla costa nordafricana. L'Algeria ottomana, per i trentotto anni che passarono fino all'occupazione francese, dominò l'intera costa.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Governo di fatto di Osman Pazvandoğlu a Vidin", "0ce70361"], "d": ["Osman Pazvandoğlu, sollevatosi contro le disposizioni del Nizâm-ı Cedîd, fece fuggire il governatore di Vidin, si impadronì della città e la fortificò con profondi fossati lungo il Danubio. Nel 1797, all'apice della potenza, radunò una forza di quasi ottantamila uomini e prese il controllo di Nicopoli, Sistova, Ruse, Sofia e Niš; si presentava non come ribelle ma come riformatore. L'assedio della Sublime Porta del 1798-1799, durato mesi, non ebbe esito e Osman governò in modo semi-indipendente la Bulgaria settentrionale fino alla morte nel 1807.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Apertura della Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Per formare ufficiali di artiglieria, genio e cartografi per l'esercito del Nizâm-ı Cedîd fu aperta a Hasköy la scuola di ingegneria terrestre, corrispettivo nell'esercito di terra della Scuola di ingegneria navale fondata nel 1773. Nel programma si insegnarono algebra, geometria, meccanica, fortificazione e balistica, e furono tradotti dalle lingue europee libri di matematica e artiglieria. Questa scuola, considerata la radice dell'istruzione ingegneristica moderna in Turchia, è ritenuta l'inizio dell'odierna Università Tecnica di Istanbul.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Dichiarazione di guerra alla Francia e alleanza con Russia e Inghilterra", "80e95bd7"], "d": ["In seguito all'occupazione dell'Egitto da parte di Napoleone, l'Impero ottomano ruppe la tradizionale amicizia francese di due secoli e mezzo e dichiarò guerra alla Francia. Nello stesso processo, per la prima volta nella sua storia, si alleò con la Russia e permise alla flotta russa di passare dagli Stretti verso il Mediterraneo; poi fu firmata un'alleanza anche con l'Inghilterra. Grazie a queste alleanze le isole Ionie furono tolte ai Francesi, ma l'apertura degli Stretti a una flotta straniera creò un precedente dal prezzo gravoso per il futuro.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Presa di Prevesa ai Francesi — Battaglia di Nicopoli", "d8e5e892"], "d": ["Quando nel 1797 la Repubblica di Venezia fu abbattuta, le isole Ionie e sulla terraferma Prevesa, Parga e Vonitsa passarono alla Francia. Il governatore di Ioannina Alì Pascià di Tepedelen, approfittando della guerra aperta dall'occupazione francese dell'Egitto, marciò su Prevesa e nelle rovine di Nicopoli fuori città inflisse una grave sconfitta alla guarnigione francese. Così questo porto, lasciato a Venezia a Passarowitz, ottanta anni dopo entrò sotto amministrazione ottomana. Butrinto cadde il 25 ottobre con la guarnigione francese che fece saltare le fortificazioni e si ritirò a Corfù (Curlin, Preveza B, 2010; l'atlante riprende il giorno da Prevesa) e passò sotto amministrazione ottomana.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Difesa di Acri — respinto Napoleone", "56b5c45b"], "d": ["Napoleone, avanzato dall'Egitto verso la Siria, assediò Acri e per due mesi lanciò assalti successivi; la città fu difesa da Cezzâr Ahmed Pascià con il sostegno della flotta inglese e delle truppe del Nizâm-ı Cedîd inviate da Istanbul. Costretto a togliere l'assedio e a ritirarsi in Egitto, Napoleone seppellì davanti a queste mura il sogno di spingersi verso oriente. La notizia fu accolta a Istanbul con grande gioia e considerata la prova che l'esercito addestrato appena creato aveva superato la sua prima seria prova.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Incursione wahhabita a Kerbela", "522341ed"], "d": ["Le forze wahhabite partite dal Najd entrarono a Kerbela, saccheggiarono la città, distrussero il mausoleo dell'imam Husayn e uccisero più di tremila persone. I governatori kölemen dell'Impero ottomano in Iraq non poterono impedire l'attacco; il fatto suscitò grandi reazioni sia in Iran sia a Istanbul. Questo attacco fu la proclamazione che il movimento saudita non era più un emirato di oasi, ma si era trasformato in una potenza regionale che minacciava le città sante ottomane.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Annessione alla Russia del Kartli-Kakheti (Georgia orientale)", "3b650c5e"], "d": ["Il regno di Kartli-Kakheti, che nel 1783 aveva accettato la protezione russa e nel 1795 aveva subìto la devastante campagna iraniana, fu sciolto; con l'ordine del 12 settembre 1801 fu proclamato provincia della Russia e si iniziò a stabilirvi il sistema amministrativo russo. La Georgia da questa data perse l'indipendenza; nel giro di pochi anni anche la Mingrelia (1803), l'Imerezia e la Guria (1804) entrarono sotto il dominio russo e la Russia giunse al confine caucasico ottomano. Con questo fatto Gori, Dusheti (Kartli) e Telavi (Kakheti) passarono alla Russia.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Evacuazione dell'Egitto dai Francesi", "00cfdc8c"], "d": ["In seguito all'operazione congiunta delle forze ottomane e inglesi da terra e da mare furono prese prima il Cairo, poi Alessandria, e le forze francesi furono rimandate in patria per nave. Con la fine dell'occupazione triennale l'Egitto tornò sulla carta all'amministrazione ottomana, ma la lotta per il predominio tra i bey kölemen e i reparti albanesi precipitò il paese nel caos. Questo vuoto avrebbe preparato, nel giro di pochi anni, il terreno per l'ascesa di Mehmed Ali di Kavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Trattato di Parigi — ristabilimento della pace con la Francia", "1b76991f"], "d": ["Con il trattato firmato dopo l'evacuazione dell'Egitto lo stato di guerra tra l'Impero ottomano e la Francia terminò ufficialmente e le antiche capitolazioni furono rinnovate. Alle navi mercantili francesi fu consentito l'ingresso nel Mar Nero; in cambio la Francia riconobbe l'integrità territoriale ottomana. Il ristabilimento della pace restituì uno spazio di manovra alla politica estera di Selim III, stretta tra Russia e Inghilterra.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Presa di Ta'if da parte dei wahhabiti", "7b791359"], "d": ["Le forze wahhabite al comando di Saud b. Abd al-Aziz, nella prima mossa verso l'Hijaz, assediarono e saccheggiarono Ta'if; la città cadde come prima porta verso le terre sante. Per il sultano ottomano, che portava il titolo di protettore dei Haramayn, fu un colpo che scuoteva direttamente la legittimità del sultanato. Due mesi e mezzo dopo lo stesso esercito avrebbe marciato sulla Mecca.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Prima presa della Mecca da parte dei wahhabiti", "21157c05"], "d": ["Due mesi e mezzo dopo la caduta di Ta'if le forze wahhabite entrarono alla Mecca, abbatterono i mausolei e stabilirono un ordine secondo la propria concezione; lo sharif Ghalib dovette ritirarsi a Gedda. La chiusura delle vie del pellegrinaggio ebbe eco in tutto il mondo islamico e costrinse Istanbul a chiedere aiuto militare al governatore d'Egitto Mehmed Ali. Questo primo dominio sarebbe durato soltanto tre mesi.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Ripresa della Mecca da parte dello sharif Ghalib", "83d08dff"], "d": ["Lo sharif Ghalib, ritiratosi a Gedda, con le forze raccolte assediò la Mecca e, dopo un assedio di venticinque giorni, la riprese ai wahhabiti; la khutba fu di nuovo recitata a nome ottomano. Anche questo secondo dominio non sarebbe stato duraturo: le forze saudite avrebbero ripreso la città nel 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Inizio della Prima rivolta serba", "0f6e8767"], "d": ["Quando i dahi giannizzeri ribelli, impadronitisi del governo a Belgrado, massacrarono in massa i notabili serbi, iniziò una resistenza armata guidata da Karađorđe. Condotto inizialmente nella fedeltà al sultano e solo contro i dahi, il movimento si trasformò presto in una rivolta nazionale che chiedeva autonomia e indipendenza. Le forze serbe presero Belgrado nel 1806; questa sollevazione fu il primo anello dei movimenti nazionalisti di indipendenza nei Balcani.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Occupazione di Medina da parte dei wahhabiti", "84e310d7"], "d": ["Dopo la Mecca anche Medina cadde in mano alle forze wahhabite; il tesoro della Rawda al-Mutahhara fu disperso e i mausolei con cupola della città furono distrutti. Così le due città sante uscirono insieme dal controllo ottomano e le carovane di pellegrini da Damasco e dall'Egitto non poterono mettersi in cammino per anni. Medina poté essere ripresa solo sette anni dopo, nel 1812, dall'esercito egiziano al comando di Tosun Pascià, figlio di Mehmed Ali Pascià.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Inizio della guerra con la Russia (guerra ottomano-russa del 1806-1812) e chiusura degli Stretti", "ea170804"], "d": ["Quando Selim III, avvicinatosi alla Francia dopo la vittoria di Napoleone ad Austerlitz, destituì i voivodi di Valacchia e Moldavia nonostante la pressione russa, gli eserciti russi occuparono i due principati e iniziò la guerra. L'Impero ottomano chiuse gli Stretti alla flotta russa; in risposta anche l'Inghilterra si schierò con la Russia e inviò una flotta a Istanbul. Questa guerra, destinata a durare sei anni, intrecciatasi con la rivolta di Kabakçı e la deposizione di Selim III, si sarebbe conclusa con la perdita della Bessarabia nel Trattato di Bucarest del 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Arrivo della flotta inglese davanti a Istanbul (operazione Duckworth)", "195bb58f"], "d": ["L'Inghilterra, che voleva costringere l'Impero ottomano a rompere con la Francia, fece passare dai Dardanelli la flotta al comando dell'ammiraglio Duckworth e la ancorò davanti a Istanbul. Con la spinta anche dell'ambasciatore francese Sébastiani la popolazione di Istanbul si mobilitò, le batterie costiere furono rinforzate in pochi giorni e la flotta dovette ritirarsi senza poter bombardare la città; al ritorno subì gravi perdite ai Dardanelli. La minaccia così ravvicinata alla capitale da parte di una flotta straniera, per la prima volta, collocò la questione degli Stretti al centro della diplomazia europea.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Strangolamento di Mustafa IV", "eeb75c20"], "d": ["Quando Alemdar Mustafa Pascià fu sorpreso da un attacco e morì e i ribelli volevano marciare sul palazzo, Mustafa IV, deposto, fu strangolato per ordine del fratello Mahmud II. La salma fu sepolta a Bahçekapı nel mausoleo del padre Abdülhamid I; tra i ribelli si diffuse la voce che la bara fosse vuota.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Trattato di Kal'a-i Sultâniyye — pace con l'Inghilterra e regola degli Stretti", "fe282117"], "d": ["Con il trattato firmato con l'Inghilterra dopo il fallimento dell'operazione Duckworth la guerra tra i due Stati terminò e furono restituiti gli antichi privilegi dei mercanti inglesi. La disposizione contenuta nel testo, detta 'antica regola', stabilì che in tempo di pace nessuna nave da guerra straniera potesse passare dagli Stretti. Questo principio divenne il fondamento giuridico di tutte le disposizioni internazionali che avrebbero plasmato il regime degli Stretti nel corso dell'Ottocento.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Disfatta di Slobozia — accerchiamento dell'esercito del Danubio", "54b60fd1"], "d": ["Gran parte dell'esercito ottomano che aveva attraversato il Danubio davanti a Ruse fu stretta a Slobozia dalla manovra di accerchiamento di Kutuzov dalla riva opposta del fiume e lasciata alla fame. Migliaia di soldati dovettero arrendersi; la forza in mano al gran visir si sciolse di fatto e la Sublime Porta un mese dopo fu costretta a chiedere l'armistizio. Questa sconfitta è la causa diretta dell'accettazione della cessione della Bessarabia nel Trattato di Bucarest del 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Ripresa di Belgrado e repressione della Prima rivolta serba", "06f56f52"], "d": ["I ribelli serbi, privati dell'appoggio russo dal Trattato di Bucarest, non poterono resistere all'operazione congiunta delle forze giunte da Bosnia e Rumelia; Hurşid Ahmed Pascià entrò a Belgrado e la sollevazione di nove anni fu repressa del tutto. Karađorđe fuggì in Austria e il sanjak di Smederevo fu di nuovo legato direttamente all'amministrazione ottomana. Tuttavia le dure misure applicate avrebbero provocato due anni dopo una seconda rivolta, duratura, guidata da Miloš Obrenović.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Seconda rivolta serba e principato di Miloš Obrenović (başknez)", "e6e82ad2"], "d": ["Contro le pesanti misure applicate dopo la repressione della prima rivolta scoppiò una nuova sollevazione guidata da Miloš Obrenović; stavolta la Sublime Porta preferì la conciliazione alla forza. Con l'accordo stipulato Miloš fu riconosciuto con il titolo di 'başknez' e il potere di riscuotere le imposte e di condurre gli affari interni fu lasciato ai knez serbi. Questo primo nucleo di autonomia di fatto fu il punto di partenza del processo che condusse al firmano del 1830 e all'indipendenza del 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Rivolta di Valacchia — Ypsilanti attraversa il Prut e sollevazione di Vladimirescu", "67d46a98"], "d": ["Aleksandros Ypsilantis, generale nell'esercito russo, a nome della Filikí Etería attraversò il Prut e tentò di avviare una sollevazione greca generale in Valacchia e Moldavia; negli stessi giorni anche Tudor Vladimirescu mise in movimento i contadini locali. I due movimenti non poterono unirsi: Vladimirescu rispose all'invito di Ypsilantis a combattere insieme contro i Turchi con 'Io non mi sono sollevato contro i Turchi, ma contro i Greci' e poco dopo fu ucciso dagli uomini di Ypsilantis. La rivolta fu repressa dalle forze ottomane a maggio, ma l'ordinamento dei voivodati fanarioti ebbe fine e il fuoco della rivolta si propagò alla Morea.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Fondazione del Secondo Stato saudita a Riyad", "34dad3bd"], "d": ["Sei anni dopo la caduta di Dir'iyya nel 1818 e la distruzione del primo Stato saudita, Turki b. Abdallah scacciò le guarnigioni egiziane dal Najd e fondò un nuovo emirato saudita con centro a Riyad. La nuova struttura evitò di estendersi all'Hijaz, preferì restare nel Najd e si tenne lontana da scontri diretti con le forze ottomano-egiziane. Questo secondo Stato sarebbe durato fino alla fine del secolo e avrebbe costituito il secondo anello della catena che porta alla fondazione dell'odierna Arabia Saudita. Altri insediamenti perduti alla stessa data: Dir'iye (Necid).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Convenzione di Akkerman — concessioni alla Serbia e ai principati", "c75f15d0"], "d": ["Subito dopo l'abolizione del Corpo dei giannizzeri, l'Impero ottomano, rimasto senza esercito, fu costretto ad accettare di fronte all'ultimatum della Russia un trattato a condizioni pesanti. Fu confermata l'autonomia promessa alla Serbia, si accettò che i voivodi di Valacchia e Moldavia non potessero essere destituiti senza il consenso russo e fu concessa alle navi mercantili russe piena libertà negli Stretti. Quando la Sublime Porta due anni dopo dichiarò di non riconoscere la convenzione a causa della questione greca, la Russia l'avrebbe considerata un motivo di guerra.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Liquidazione del sistema del timar", "84d5d1d6"], "d": ["Un anno dopo l'abolizione del Corpo dei giannizzeri, circa 5.200 sipahi titolari di timar nei cinquantatré sanjak di Rumelia e Anatolia furono trasformati, con le rendite dei timar, in cavalleria degli Asâkir-i Mansûre. Così il regime del timar, spina dorsale quadricentenaria dell'ordinamento ottomano di terra, imposte ed esercito, ebbe fine di fatto. I timar rimasti vacanti furono trasferiti al tesoro e si aprì la strada al passaggio a un esercito centrale salariato e a un sistema fiscale in denaro.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Fondazione della Tıphâne-i Âmire — inizio dell'istruzione medica moderna", "ac3e57c0"], "d": ["Per formare medici e chirurghi per il nuovo esercito degli Asâkir-i Mansûre, su proposta del capo dei medici Mustafa Behçet Efendi fu aperta a Şehzadebaşı la Tıphâne-i Âmire. Le lezioni furono organizzate secondo il programma europeo e l'insegnamento fu inizialmente in francese; pochi anni dopo fu fondata anche la Cerrahhâne-i Âmire e le due istituzioni furono unite. Questa scuola, considerata l'inizio dell'insegnamento medico moderno in Turchia, è ritenuta l'origine dell'odierna Facoltà di Medicina di Istanbul.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Inizio della guerra ottomano-russa del 1828-1829", "9dff4e05"], "d": ["Dopo l'incendio della flotta a Navarino e la dichiarazione della Sublime Porta di non riconoscere la Convenzione di Akkerman, la Russia aprì la guerra su due fronti contemporaneamente. Poiché il Corpo dei giannizzeri era stato appena abolito e il nuovo esercito era ancora in formazione, la difesa ottomana fu debole fin dall'inizio; mentre i Russi attraversavano il Danubio, a oriente presero Kars e Akhaltsikhe. L'esercito russo, avanzato nel giro di un anno fino a Edirne, avrebbe imposto le dure condizioni del Trattato di Edirne del 1829 e l'indipendenza della Grecia.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Primo trattato con gli Stati Uniti d'America", "d737516f"], "d": ["Con il trattato di commercio e navigazione firmato dopo anni di contatti, gli Stati Uniti ottennero nel territorio ottomano lo status di nazione più favorita e il diritto di transito commerciale dagli Stretti. Un articolo segreto separato prevedeva che l'Impero ottomano, se lo desiderava, facesse costruire navi nei cantieri americani e acquistasse navi pronte e legname; il Senato degli Stati Uniti ratificò il trattato ma respinse questo articolo segreto con 27 voti contro 18. La via delle navi non si chiuse comunque: Henry Eckford nel 1831 vendette agli Ottomani la nave che aveva portato e i maestri americani che lavoravano ad Aynalıkavak procurarono alla flotta navi di nuovo tipo. Questo trattato fu il documento della prima relazione di ampia portata dell'Impero ottomano con uno Stato fuori dall'Europa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Fine del governo kölemen a Baghdad", "7e1d38a3"], "d": ["Mahmud II, che perseguiva una politica di centralizzazione, dichiarò ribelle il governatore di Baghdad Dâvud Pascià, che non inviava il denaro richiesto e aveva fatto uccidere il funzionario giunto dal centro. La forza al comando di Ali Rızâ Pascià, dopo un assedio di novanta giorni, prese la città e quasi tutti i kölemen furono eliminati. Così il governo semi-indipendente dei Kölemen, in vigore dal 1704, ebbe fine e l'Iraq fu di nuovo legato direttamente al centro.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Fondazione della Mekteb-i Harbiye nella caserma di Maçka", "bf31c7d9"], "d": ["Per fornire agli Asâkir-i Mansûre-i Muhammediyye ufficiali formati all'europea fu aperta nella caserma di Maçka la Mekteb-i Fünûn-ı Harbiyye. Agli studenti furono insegnati matematica, cartografia, fortificazione e lingue straniere; poco dopo furono inviati studenti a Vienna e a Parigi per rafforzare i quadri. Questa scuola fu il luogo in cui nacquero, nell'esercito ottomano, la tradizione dell'ufficiale formato nelle scuole e dunque la nuova generazione di militari-intellettuali che sarebbe emersa alla fine dell'Ottocento.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["La Tripolitania legata direttamente al centro — fine della dinastia caramanlide", "faabcb96"], "d": ["In seguito alle lotte per il trono all'interno della famiglia Karamanlı e alla crescente pressione europea dopo l'occupazione di Algeri da parte della Francia nel 1830, la Sublime Porta intervenne direttamente in Tripolitania. La flotta inviata da Istanbul entrò in città, l'ultimo bey caramanlide fu destituito e portato a Istanbul e la provincia fu consegnata a un governatore nominato dal centro. Con la fine del periodo dinastico di 124 anni fu consolidato l'ultimo lembo di territorio nordafricano amministrato direttamente dall'Impero ottomano.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Abolizione del defterdarlık e fondazione del Ministero delle Finanze (Maliye Nezâreti)", "89f8125e"], "d": ["Abolita la carica di defterdar, capo del classico ordinamento finanziario ottomano, fu istituito il Maliye Nezâreti, ministero di tipo europeo, e i tesori dispersi furono riuniti in un'unica mano. Nello stesso anno le altre unità della Sublime Porta furono riorganizzate sotto il nome di nezâret e si passò a una struttura moderna di consiglio dei ministri. Questo riordino fu uno dei passi più importanti nella preparazione dell'infrastruttura amministrativa dell'Editto di Tanzimat che sarebbe stato proclamato un anno dopo.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Insediamento degli Inglesi ad Aden", "ddbd556b"], "d": ["L'Inghilterra, basandosi sul trattato di commercio e amicizia firmato nel 1802 con il sultano di Lahej Ahmed b. Abd al-Karim, sbarcò truppe nel porto di Aden e ne prese il controllo. Questo porto, che tiene l'imbocco del Mar Rosso, divenne come base di rifornimento di carbone sulla rotta dell'India il punto chiave della strategia imperiale inglese. Anche se la pretesa dell'Impero ottomano sullo Yemen continuò sulla carta, il suo dominio di fatto sulla costa meridionale non tornò più dopo questa data.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Ritorno alla costa della Tihama: presa di Hodeida, Zabid e Mocha", "353982d2"], "d": ["Sulla costa dello Yemen rimasta senza padrone dopo il ritiro dell'esercito egiziano nel 1840, forze al comando di Tevfik Pascià, sotto la supervisione dello sharif della Mecca, sbarcarono e legarono all'amministrazione ottomana i porti di Hodeida, Zabid e Mocha. Si voleva avanzare fino a Sana'a, ma per la resistenza della popolazione si tornò a Hodeida; così gli altopiani rimasero agli imam zaiditi e il dominio ottomano per ventitré anni proseguì soltanto nella fascia della Tihama. Lo Yemen interno sarebbe stato ripreso solo nel 1872 con la campagna di Ahmed Muhtar Pascià.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Convenzione di Balta Limanı: protettorato congiunto ottomano-russo su Valacchia e Moldavia", "d3bb22e9"], "d": ["Dopo che le rivoluzioni del 1848 si erano estese a Valacchia e Moldavia, forze ottomane e russe avevano occupato insieme i principati. Con la convenzione firmata a Balta Limanı si stabilì che i voivodi non fossero eletti ma nominati dal sultano per sette anni e che i due Stati esercitassero un controllo congiunto sulla regione. L'accordo, pur conservando la sovranità ottomana sulla carta, riconobbe alla Russia un diritto di compartecipazione di fatto e accelerò il distacco dei principati danubiani dall'Impero ottomano.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Questione dei rifugiati ungheresi: Kossuth e compagni si rifugiano nell'Impero ottomano", "1c7d7ef4"], "d": ["Dopo la repressione della rivoluzione ungherese del 1848-1849 con l'intervento russo-austriaco, Lajos Kossuth e migliaia di rifugiati ungheresi e polacchi si rifugiarono in territorio ottomano. Austria e Russia chiesero duramente l'estradizione dei rifugiati; la Sublime Porta, con il sostegno di Inghilterra e Francia, rifiutò l'estradizione e sistemò il gruppo a Kütahya. L'entourage di Kossuth vi rimase circa diciotto mesi e centinaia di rifugiati si convertirono all'islam ed entrarono al servizio ottomano. L'episodio fu considerato una delle rare vittorie diplomatiche che innalzarono il prestigio dell'Impero ottomano del Tanzimat presso l'opinione pubblica europea.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Fondazione dell'Encümen-i Dâniş: prima accademia ottomana a Istanbul", "6fda1365"], "d": ["L'Encümen-i Dâniş, fondato per decisione del Meclis-i Maârif-i Umûmiyye, è la prima accademia scientifica ottomana costituita per preparare opere scientifiche e libri di testo in turco. Fu inaugurato con una cerimonia il 18 luglio 1851 nell'edificio del Dârülmaârif; tra i suoi membri locali e stranieri c'era anche Ahmed Cevdet Pascià. Sebbene di breve durata, l'istituzione produsse opere come il Târih di Cevdet Pascià e il Kavâid-i Osmâniyye ed è considerata una pietra angolare nella trasformazione del turco in lingua scientifica.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Vittoria di Oltenița: primo successo ottomano sul fronte del Danubio", "a660ad2f"], "d": ["Nella fase iniziale della Guerra di Crimea il serdâr-ı ekrem Ömer Lütfi Pascià attraversò il Danubio e a Oltenița respinse le forze russe con gravi perdite. La vittoria, fermando l'avanzata russa subito all'inizio della guerra, mostrò all'Europa la forza che l'esercito ottomano aveva acquisito con l'addestramento dopo il Tanzimat. Questo successo preparò il terreno psicologico che facilitò la decisione di Inghilterra e Francia di entrare in guerra al fianco degli Ottomani.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Trattato d'alleanza con Inghilterra e Francia a Istanbul", "04809278"], "d": ["Il trattato d'alleanza firmato nella Guerra di Crimea contro la Russia tra l'Impero ottomano, l'Inghilterra e la Francia stabilì che i tre Stati conducessero operazioni comuni e che gli alleati non facessero pace separata prima della fine della guerra. Così l'Impero ottomano entrò per la prima volta nella sua storia in un'alleanza militare con le grandi potenze europee come parte paritaria. Questo trattato costituì anche il fondamento giuridico dell'ammissione ufficiale dell'Impero ottomano al sistema degli Stati europei a Parigi due anni dopo.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Fondazione dello Şehremaneti di Istanbul: prima organizzazione municipale moderna", "be4af27f"], "d": ["La crisi infrastrutturale causata dai soldati alleati affluiti a Istanbul durante la Guerra di Crimea e dalla popolazione in aumento rivelò l'insufficienza dell'amministrazione cittadina classica incentrata sul kadı. Con lo Şehremaneti, fondato sul modello europeo, pulizia, narh, controllo dei mercati e lavori urbanistici furono riuniti in un'unica mano; l'anno seguente a Beyoğlu-Galata fu costituito come zona pilota il Sesto Distretto Municipale (Altıncı Daire-i Belediye). Questo passo è considerato l'inizio dell'amministrazione municipale moderna nell'Impero ottomano.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Trattato di Parigi: fine della Guerra di Crimea e ammissione dell'Impero ottomano al sistema degli Stati europei", "4aee0e2a"], "d": ["Con il Trattato di Parigi che pose fine alla Guerra di Crimea l'Impero ottomano fu dichiarato membro paritario del diritto degli Stati europei e la sua integrità territoriale fu posta sotto la garanzia comune delle grandi potenze. Il Mar Nero fu neutralizzato, la pretesa russa di protezione sui sudditi ortodossi, ottenuta dal Trattato di Küçük Kaynarca, fu dichiarata nulla, e la Bessarabia meridionale (distretti di Kilia, Cahul, Ismail e Bolgrad) fu data alla Moldavia. Ma lo stesso trattato, facendo dell'Editto di Riforma (Islahat Fermanı) un impegno internazionale, aprì anche la porta all'ingerenza negli affari interni.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Apertura del Palazzo di Dolmabahçe: il centro amministrativo lascia Topkapı", "71ad26d0"], "d": ["Il palazzo commissionato da Abdülmecid nel 1842 alla famiglia Balyan fu aperto dopo quattordici anni di costruzione e il centro amministrativo dello Stato si trasferì dal Topkapı quadricentenario alla riva del Bosforo. Con lo stile europeo, lo scalone di cristallo e la Sala delle Cerimonie (Muayede Salonu), il palazzo fu l'espressione in pietra della pretesa occidentalizzatrice del Tanzimat. Il suo enorme costo divenne una delle voci più criticate degli anni in cui le finanze ottomane entrarono nella spirale dell'indebitamento estero.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Unione di Valacchia e Moldavia sotto Cuza: nascita della Romania", "baef4da5"], "d": ["Nelle elezioni tenute dopo il Trattato di Parigi i due principati elessero entrambi voivoda il colonnello Alexandru Ioan Cuza, realizzando l'unione di fatto. Anche se la Sublime Porta e l'Austria si opposero, il fatto compiuto, sostenuto dalla Francia, dovette essere accettato. Quest'unione, rimasta sulla carta legata agli Ottomani, nel 1862 avrebbe assunto il nome di Romania e nel 1877 avrebbe dichiarato unilateralmente l'indipendenza; è un punto di svolta nello sgretolarsi del dominio ottomano lungo il Danubio.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Episodio di Kuleli: primo tentativo di colpo di Stato contro Abdülmecid a Istanbul", "e3653b21"], "d": ["Una società segreta mista di militari e civili, che reagiva alla politica del Tanzimat e all'uguaglianza concessa ai non musulmani dall'Editto di Riforma, mentre progettava di deporre il sultano fu scoperta durante una riunione nella moschea di Kılıç Ali Pascià. Poiché gli imputati furono processati nella caserma di Kuleli, il fatto è ricordato con questo nome; le condanne a morte furono commutate in esilio. È considerato il primo tentativo di colpo di palazzo, nella storia ottomana, di un'organizzazione costituita per motivi ideologici.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Guerra civile drusa-maronita sul Monte Libano e fatti di Damasco", "5595fdd6"], "d": ["Gli scontri scoppiati nel maggio 1860 con l'uccisione di due drusi presso Sidone si trasformarono nella più sanguinosa guerra civile drusa-maronita della montagna e a luglio si estesero a Damasco, con la morte di migliaia di cristiani. Dopo lo sbarco di truppe francesi la Sublime Porta inviò nella regione Fuad Pascià con poteri straordinari; fu condotta una dura azione repressiva. Gli eventi costituirono il pretesto dell'intervento europeo e furono la causa diretta dell'acquisizione da parte del Libano di uno statuto speciale.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Inizio delle pubblicazioni del Tercümân-ı Ahvâl: primo giornale turco privato a Istanbul", "24792957"], "d": ["Il Tercümân-ı Ahvâl, pubblicato da Agâh Efendi e con Şinâsi alla direzione redazionale, è il primo giornale turco pubblicato senza sostegno statale. Nella premessa del primo numero fu difeso il diritto del popolo di parlare dei propri affari e il giornale, pubblicando a puntate il Şair Evlenmesi di Şinâsi, aprì la porta anche alla letteratura turca moderna. La nascita nell'Impero ottomano del concetto di opinione pubblica e della stampa di opposizione è fatta risalire a questa data.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Regolamento del Monte Libano: statuto di mutasarrıflık privilegiata per il Libano", "bf375603"], "d": ["Il regolamento preparato dopo i massacri del 1860 con la pressione delle grandi potenze fece del Monte Libano un mutasarrıflık privilegiato, legato direttamente alla Sublime Porta e governato da un consiglio amministrativo costituito secondo l'equilibrio tra le confessioni. Si stabilì che il mutasarrıf fosse un suddito ottomano cristiano cattolico e che la sua nomina fosse sottoposta all'approvazione delle grandi potenze; il primo mutasarrıf fu Dâvud Pascià. Questo ordinamento sarebbe durato fino al 1915 e avrebbe costituito il nucleo dello Stato libanese moderno.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Morte di Abdülmecid e ascesa al trono del sultano Abdülaziz", "27204d7c"], "d": ["Quando Abdülmecid, che nel suo regno di ventidue anni aveva firmato gli editti di Tanzimat e di Riforma, soccombette alla tubercolosi, salì al trono il fratello Abdülaziz. Il nuovo sultano nei primi anni diede speranze con misure di risparmio e una vita sobria; fece della flotta una delle più potenti del mondo. Ma alla fine del suo regno il pesante debito estero, la bancarotta del 1875 e le rivolte balcaniche, accumulandosi, avrebbero preparato il terreno al movimento di deposizione del 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["I principati uniti assumono il nome di Romania", "d960e3fc"], "d": ["Valacchia e Moldavia, di fatto unite nel 1859 con la doppia elezione di Cuza, nel 1862, riunendo a Bucarest sotto un unico tetto assemblee e governi, assunsero ufficialmente il nome di Romania. Anche se l'Impero ottomano conservava giuridicamente la qualità di sovrano e il tributo annuo, perse di fatto il controllo sul principato. La fine dell'influenza ottomana quadricentenaria a nord del Danubio è simboleggiata da questa data.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Annessione di Suakin, Massaua e Dahlak all'Egitto", "a0924860"], "d": ["Massaua, data nel 1846 dal sultano Abdülmecid al khedivé d'Egitto Mehmed Ali Pascià insieme a Suakin come sâlyâne (assegnazione di rendite), fu inclusa, al tempo del khedivé İsmâil Pascià, nei possedimenti dell'Egitto insieme a Dahlak e Suakin e organizzata con lo statuto di kaymakamlık. Così questi tre porti sulla costa africana del Mar Rosso, pur restando giuridicamente territorio ottomano, passarono sul piano amministrativo direttamente dalla Sublime Porta al Cairo — rientrando nello stesso strato di dipendenza dell'Egitto e del Sudan, loro vicini.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Inizio della rivolta di Creta (1866-1869)", "3679b861"], "d": ["La sollevazione di vasta portata scoppiata sull'isola con l'aperto sostegno della Grecia fece per la prima volta della richiesta di enosis (unione alla Grecia) dei Greci di Creta una questione internazionale. L'aspra guerra di montagna, durata tre anni, inflisse gravi perdite all'esercito ottomano e suscitò grande eco nell'opinione pubblica europea. La rivolta poté spegnersi soltanto nel 1868, quando Âlî Pascià si recò sull'isola e mise in vigore il regolamento che concedeva ampi privilegi.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Ritiro delle ultime guarnigioni ottomane dalle fortezze di Belgrado e Serbia", "b34217db"], "d": ["Per la pressione delle grandi potenze e l'insistente richiesta del principe Mihailo, la Sublime Porta accettò di evacuare le ultime basi militari rimaste in Serbia; il 18 aprile 1867 fu ammainata la bandiera ottomana nella Fortezza di Belgrado e le chiavi furono consegnate al principe. Così ebbe fine la presenza militare ottomana di fatto, in vigore dal 1521, e fu rimosso l'ultimo grande ostacolo sulla via dell'indipendenza della Serbia. La sovranità del sultano fu ridotta a una semplice questione di bandiera simbolica e tributo.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Concessione del titolo di khedivé ai governatori d'Egitto", "09e10c12"], "d": ["In seguito alla fitta attività di lobby di İsmâil Pascià, della terza generazione della dinastia di Kavala, e al denaro da lui fatto affluire a Istanbul, al governatore d'Egitto fu concesso il titolo di khedivé, che sottolineava la sua superiorità sugli altri governatori. Negli stessi anni anche il sistema di successione fu cambiato in modo che passasse di padre in figlio e all'Egitto furono riconosciuti poteri di natura sovrana come contrarre debiti esteri, conferire decorazioni, tenere consolati. Questi passi sono il primo anello della catena che accelerò il distacco giuridico dell'Egitto dall'Impero ottomano.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Regolamento di Creta: ampi privilegi amministrativi all'isola", "12052262"], "d": ["Per porre fine alla rivolta di tre anni il gran visir Âlî Pascià si recò personalmente sull'isola e con il regolamento pubblicato con l'approvazione del sultano furono concessi ai Cretesi consigli amministrativi misti, tribunali locali, l'uso del greco negli atti ufficiali e agevolazioni fiscali. Questo ordinamento mantenne in piedi per altri trent'anni il dominio ottomano sull'isola. Ma i privilegi concessi alla popolazione cristiana indebolirono la posizione dei Cretesi musulmani e gettarono i semi della crisi del 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Apertura dello Şûrâ-yı Devlet: fondazione del Consiglio di Stato ottomano", "70b16497"], "d": ["Con l'irade del 5 marzo 1868 il Meclis-i Ahkâm-ı Adliyye fu diviso in due: gli affari amministrativo-legislativi furono lasciati allo Şûrâ-yı Devlet, quelli giudiziari al Dîvân-ı Ahkâm-ı Adliyye; l'istituzione fu aperta con cerimonia alla Sublime Porta e alla presidenza fu posto Midhat Pascià. Fu incaricata di preparare i progetti di legge, di risolvere le controversie amministrative e di condurre i processi ai funzionari. Con la sua struttura mista di membri musulmani e non musulmani è considerata la prima applicazione istituzionale dell'idea di separazione dei poteri nell'Impero ottomano.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Apertura del Canale di Suez: accorciamento della rotta dell'India attraverso l'Egitto", "377ccd04"], "d": ["La costruzione, iniziata nel 1859, durò dieci anni e il canale di 163 chilometri che collega il Mediterraneo al Mar Rosso entrò in servizio con una cerimonia sfarzosa. Quando la via che collega l'Europa all'India si accorciò di migliaia di miglia, l'Egitto divenne di colpo il punto chiave del commercio mondiale. Questo valore geostrategico sarebbe stato la principale ragione dell'occupazione dell'Egitto da parte dell'Inghilterra tredici anni dopo l'apertura del canale; il debito che il canale gravò sull'Egitto avrebbe portato il khedivato alla bancarotta.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Fondazione dell'Esarcato bulgaro: la chiesa bulgara si separa dal Fanar", "33a8272c"], "d": ["Con un firmano del sultano fu istituita una chiesa bulgara autonoma (esarcato), separata dal Patriarcato greco, e quali distretti dovessero essere legati all'esarcato fu lasciato a un voto popolare. La Sublime Porta compì questo passo per spezzare l'influenza greca, ma il risultato fu opposto: la chiesa si trasformò nel centro organizzato dell'identità nazionale bulgara e della pretesa bulgara sulla Macedonia. Fu così gettata la base istituzionale della rivalità bulgaro-greco-serba nei Balcani e delle rivolte del 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Presa in amministrazione diretta dell'Asir", "4559e099"], "d": ["Quando con l'apertura del Canale di Suez crebbe il valore strategico del Mar Rosso, si vide che i monti dell'Asir, a metà della via di terra verso lo Yemen, non potevano essere lasciati incontrollati. Le forze di Redif Pascià, partite per la campagna dello Yemen, entrarono ad Abha e legarono la regione all'amministrazione ottomana diretta e fu fondato il sanjak di Asir. A causa della geografia montuosa e dell'influenza idrisida questo dominio non si assestò mai pienamente.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Campagna di Midhat Pascià nel Najd: ristabilimento del dominio ottomano ad al-Hasa", "7db51461"], "d": ["Il governatore di Baghdad Midhat Pascià, approfittando della lotta per il trono all'interno della famiglia saudita, inviò truppe sulla costa occidentale del Golfo Persico e legò la regione di al-Hasa alla provincia di Bassora con il nome di sanjak di Najd. Abdallah b. Faysal fu nominato mutasarrıf e il dominio ottomano fu stabilito sulla carta. La campagna aveva lo scopo di fermare la diffusione dell'influenza inglese nel Golfo e nello stesso anno portò anche al passaggio del Qatar sotto controllo ottomano.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Morte del gran visir Âlî Pascià: fine del quadro dirigente del Tanzimat", "1cf0141c"], "d": ["Con la morte di Âlî Pascià, che dopo la scomparsa di Fuad Pascià nel 1869 aveva portato da solo sulle spalle la politica del Tanzimat, si esaurì la generazione di abili diplomatici che per trent'anni aveva guidato la politica estera dello Stato. Il governo filorusso e arbitrario di Mahmud Nedim Pascià, che gli succedette, consolidò la gestione personale di Abdülaziz. Nei cinque anni successivi alla morte di Âlî Pascià le finanze fallirono, i Balcani si sollevarono e il cambio di sultano divenne inevitabile.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Instaurazione del controllo ottomano in Qatar", "3b453165"], "d": ["Su invito dello sceicco Qasim b. Thani, sotto pressione inglese, forze ottomane sbarcarono nella penisola del Qatar e nell'autunno del 1871 fu assicurato nella regione il controllo ottomano. Il Qatar fu organizzato come kaza dipendente dal sanjak di Najd e lo sceicco fu nominato kaymakam. Questa mossa fu il risultato più concreto della politica avanzata condotta da Midhat Pascià nel Golfo contro l'Inghilterra; la bandiera ottomana sventolò nella penisola fino al 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Firmano di successione per la Tunisia — il beylicato alla famiglia di Mehmed Sadık Pascià", "1509ebb0"], "d": ["Con il firmano emesso grazie alle iniziative di Hayreddin Pascià, inviato a Istanbul dal bey di Tunisi Mehmed Sadık Pascià, che aveva colto l'occasione della sconfitta della Francia contro la Prussia, la Tunisia fu data a Mehmed Sadık Pascià e ai suoi discendenti con sistema di successione, restando direttamente legata a Istanbul. Non si sarebbero condotti negoziati di guerra e di pace senza il permesso del sultano, nessun territorio del paese sarebbe stato dato ad altri e la richiesta ottomana di soldati sarebbe stata soddisfatta. La Francia non riconobbe il firmano; dieci anni dopo occupò la Tunisia.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Presa di Sana'a: ristabilimento dell'autorità ottomana nello Yemen", "978e20a0"], "d": ["Quando con l'apertura del Canale di Suez crebbe il valore strategico del Mar Rosso, la Sublime Porta inviò nello Yemen l'esercito della fırka-i ihtiyâtiyye al comando di Ahmed Muhtar Pascià. Con la presa di Sana'a l'autorità dello Stato fu ristabilita nello Yemen interno, di fatto perso da due secoli, e la regione fu fatta provincia. Ma la lotta con gli imam zaiditi non finì mai; le rivolte del 1891, 1898 e 1904 costituirono il fronte interno più costoso e più lungo dell'Impero ottomano. Altri luoghi annessi alla stessa data: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Inizio della rivolta d'Erzegovina: nuova fiammata della Questione d'Oriente", "571b18ec"], "d": ["La sollevazione dei contadini cristiani intorno a Nevesinje, causata dalle imposte pesanti e dalla pressione degli ayan, si estese presto a tutta l'Erzegovina e fu alimentata dai volontari giunti da Serbia e Montenegro. La rivolta, che portò Austria e Russia a imporre riforme, l'anno seguente provocò le sollevazioni bulgare e le dichiarazioni di guerra di Serbia e Montenegro. Così si spezzò il primo anello della grande catena che condusse alla Guerra del '93 e, con il Trattato di Berlino, alla perdita dei Balcani.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Bancarotta delle finanze ottomane: dimezzamento dei pagamenti del debito estero", "2cac2fa5"], "d": ["I prestiti contratti di continuo dal 1854, le spese della Guerra di Crimea, le costruzioni di palazzi e la carestia anatolica del 1873-74 trasformarono il disavanzo di bilancio in un abisso superiore a cinque milioni di lire. Il governo di Mahmud Nedim Pascià, dichiarando che i pagamenti di interessi e capitale del debito sarebbero stati dimezzati per cinque anni, dichiarò di fatto una moratoria. Questa decisione, che suscitò grandi reazioni nelle borse europee, avviò il processo che sei anni dopo si sarebbe concluso con il Decreto di Muharrem e la fondazione dell'Amministrazione del Debito Pubblico (Düyûn-ı Umûmiyye).", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Deposizione di Murad V e ascesa al trono di Abdülhamid II", "cffb2271"], "d": ["Murad V, salito al trono dopo la deposizione di Abdülaziz, divenne incapace di esercitare la carica a causa della sua salute mentale, scossa dalla morte dello zio e dall'episodio di Çerkes Hasan; solo in sette giorni del suo regno di novantatré giorni il suo giudizio fu lucido. Deposto con fatwa dello şeyhülislam, gli subentrò il fratello Abdülhamid II. Il nuovo sultano salì al trono dando a Midhat Pascià la promessa di proclamare la monarchia costituzionale; iniziava un'epoca destinata a durare trentatré anni.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Conferenza dei Cantieri (Tersane Konferansı): imposizione di riforme balcaniche da parte delle grandi potenze", "b5006a2c"], "d": ["La conferenza riunita a Istanbul dalle grandi potenze per risolvere la crisi balcanica chiese la divisione della Bulgaria in due province autonome e l'applicazione in Bosnia-Erzegovina di riforme sotto controllo internazionale. La Sublime Porta, annunciando con salve di cannone il giorno stesso dell'apertura della conferenza la proclamazione del Kanûn-ı Esâsî, cercò di rispondere alle imposizioni con una riforma costituzionale. I delegati, considerandola una manovra dilatoria, si dispersero il 20 gennaio 1877; quattro mesi dopo la Russia dichiarò guerra.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Apertura a Dolmabahçe del primo Meclis-i Meb'ûsan", "429bb279"], "d": ["I 115 deputati eletti in base al Kanûn-ı Esâsî si riunirono per la prima volta il 19 marzo 1877 con una cerimonia nella Sala delle Cerimonie del Palazzo di Dolmabahçe; iniziò così nella storia ottomana il periodo dell'assemblea rappresentativa. I deputati musulmani e non musulmani interrogarono duramente il governo e discussero la conduzione della guerra e la responsabilità dei ministri. Questa coraggiosa opposizione sarebbe stata la principale causa dell'abbreviarsi della vita dell'assemblea.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Inizio della difesa di Plevna: la resistenza di Gazi Osman Pascià", "0e04a878"], "d": ["Osman Pascià, marciato da Vidin a Plevna per tagliare la strada di Istanbul all'esercito russo che aveva attraversato il Danubio nella Guerra del '93, fortificò la cittadina con tabya e trincee e diede inizio a una leggendaria difesa di cinque mesi. Tre grandi attacchi successivi russo-romeni furono respinti con gravi perdite e l'esercito diretto personalmente dallo zar Alessandro II fu costretto all'assedio. Plevna è entrata nella storia come il più brillante successo difensivo dell'esercito ottomano nel XIX secolo.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Caduta di Plevna: crollo del fronte del Danubio", "185e7602"], "d": ["Osman Pascià, esaurite le provviste dopo cinque mesi d'assedio, tentò una sortita attraverso il fiume Vit; quando fu ferito e fatto prigioniero, la città si arrese. I comandanti russi salutarono il pascià prigioniero restituendogli la spada e a Osman Pascià fu dato il titolo di 'Gazi'. Con la caduta di Plevna la strada dell'esercito russo fu aperta; in due mesi caddero Sofia, Filippopoli ed Edirne e le avanguardie russe raggiunsero Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Occupazione di Sofia da parte delle forze russe", "ef369d22"], "d": ["Dopo la caduta di Plevna l'esercito russo, valicati i Balcani, entrò in Sofia rimasta senza difesa. La città non sarebbe più tornata all'amministrazione ottomana e alla fine del 1878 sarebbe diventata la capitale del Principato autonomo di Bulgaria, di fatto nel 1879. Sulla mappa Sofia da questa data esce dall'amministrazione diretta ottomana e passa a un'occupazione russa temporanea e poi all'amministrazione autonoma bulgara.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Armistizio di Edirne: il silenzio delle armi nella Guerra del '93", "1f899180"], "d": ["Con la caduta in rapida successione di Sofia, Filippopoli ed Edirne e l'esercito russo giunto alle coste del Marmara, la Sublime Porta fu costretta a chiedere l'armistizio. La tregua firmata a Edirne fece accettare agli Ottomani condizioni preliminari di pace quali l'autonomia della Bulgaria, l'indipendenza di Montenegro, Serbia e Romania e una pesante indennità di guerra. Queste condizioni un mese dopo sarebbero diventate il testo del trattato di Santo Stefano.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Sospensione a tempo indeterminato del Meclis-i Meb'ûsan da parte di Abdülhamid II", "e770b540"], "d": ["Alle aspre critiche dei deputati, che ritenevano governo e palazzo responsabili del disastroso esito della guerra, Abdülhamid II, in base al potere conferitogli dal Kanûn-ı Esâsî, sospese l'assemblea a tempo indeterminato. Il primo parlamento ottomano, attivo per circa undici mesi, si chiuse così e iniziò l'epoca dell'istibdat (assolutismo), destinata a durare trent'anni. L'assemblea avrebbe potuto riunirsi di nuovo solo dopo la Rivoluzione del 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Trattato di Santo Stefano (Ayastefanos): progetto della Grande Bulgaria", "2c7cc611"], "d": ["Il Trattato di Santo Stefano, che pose fine alla Guerra del '93, istituiva una gigantesca Bulgaria autonoma che si estendeva fino all'Egeo e comprendeva la Macedonia; riconosceva l'indipendenza di Serbia, Montenegro e Romania; lasciava alla Russia Kars, Ardahan, Batum e Doğubayazıt e imponeva inoltre un'indennità di guerra impossibile da pagare. Questo testo, che portava la Russia al Mediterraneo, suscitò la violenta reazione di Inghilterra e Austria. Senza essere applicato fu riordinato nel giro di quattro mesi dal Congresso di Berlino; rimase tuttavia il documento che proclamò la fine della Rumelia ottomana.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan e Batum lasciate alla Russia — elviye-i selâse", "99bdfad2"], "d": ["Con il Trattato di Berlino l'Impero ottomano lasciò alla Russia Kars, Ardahan e Batum in corrispondenza di una parte dell'indennità di guerra; Doğubayazıt e la valle di Eleşkirt, date alla Russia a Santo Stefano, rimasero invece agli Ottomani. Batum fu data come porto franco, ma poté conservare questo status solo fino al 1886. I Russi fecero di Kars una provincia dipendente dal governatorato generale della Transcaucasia con centro a Tiflis; una popolazione dell'elviye-i selâse che arrivava a 100.000 persone fu costretta a emigrare verso Erzurum. Con lo stesso trattato la Bessarabia meridionale (Kilia, Cahul, Bolgrad) fu restituita dalla Romania alla Russia.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Occupazione di Bosnia-Erzegovina e Novi Pazar da parte dell'Austria-Ungheria", "e5f901df"], "d": ["In base all'autorizzazione data dal Trattato di Berlino, gli eserciti austro-ungarici entrarono in Bosnia; sebbene il governo ottomano avesse accettato di non resistere, la popolazione locale musulmana e ortodossa di Sarajevo e Mostar prese le armi e oppose per tre mesi una dura resistenza. L'occupazione poté essere completata solo il 20 ottobre 1878. La sovranità giuridica del sultano continuò sulla carta fino al 1908, ma la Bosnia ottomana, quadricentenaria, andò di fatto perduta e iniziò una grande ondata migratoria musulmana. Altri insediamenti perduti alla stessa data: Banaluka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Decreto di Muharrem e fondazione dell'Amministrazione del Debito Pubblico (Düyûn-ı Umûmiyye)", "02b7cc03"], "d": ["I negoziati condotti con i rappresentanti degli Stati creditori dopo la bancarotta del 1875 si conclusero con il decreto datato 28 Muharram 1299 (20 dicembre 1881): il capitale del debito fu ridotto di oltre la metà e in cambio le voci di reddito più redditizie, come le imposte su sale, tabacco, seta, bollo e pesca, furono cedute all'Amministrazione del Debito Pubblico (Düyûn-ı Umûmiyye), gestita direttamente dai creditori. Questa amministrazione, che impiegava migliaia di funzionari, si trasformò in un'organizzazione finanziaria distinta all'interno dello Stato. È considerata la data in cui l'indipendenza finanziaria ottomana terminò di fatto.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — l'unico porto non caduto in mano al Mahdi", "5a37b198"], "d": ["Mentre dal febbraio 1884 tutte le regioni del Sudan orientale tranne Suakin passavano sotto il dominio di Muhammad Ahmad al-Mahdi, il porto rimase in piedi grazie alla protezione militare di una forza britannica di tre battaglioni al comando del generale Graham. Fu l'inizio di un periodo in cui situazione di fatto e di diritto si separarono: sebbene la costa fosse di fatto sotto controllo militare britannico, il suo legame amministrativo nel 1885 sarebbe stato tolto all'Egitto e legato direttamente alla provincia dello Yemen, cioè alla Sublime Porta — quell'ordinamento durò fino al 1888, quando terminò con l'occupazione di Zeila da parte della Francia.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Uccisione di Midhat Pascià nella prigione di Ta'if", "f4562261"], "d": ["Midhat Pascià, architetto del Kanûn-ı Esâsî e nome simbolo della Prima monarchia costituzionale, giudicato colpevole dal Tribunale di Yıldız in relazione alla morte di Abdülaziz e con la pena capitale commutata in esilio, era stato inviato a Ta'if. Secondo la scheda TDV, nella notte del 7-8 maggio 1884 fu strangolato nella sua cella e come causa ufficiale fu indicata la malattia 'şîrpençe'. La sua morte divenne il simbolo della liquidazione dell'opposizione costituzionale sotto Abdülhamid II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Concessione ai Tedeschi della ferrovia Haydarpaşa-Ankara", "5705b163"], "d": ["Con irade del sultano la concessione di costruzione e gestione della linea Haydarpaşa-Ankara fu data al banchiere Alfred von Kaulla, rappresentante della Deutsche Bank, e fu fondata la Società delle Ferrovie Anatoliche. Questa concessione fu il punto di svolta che spezzò il monopolio anglo-francese nei trasporti e nella politica estera ottomana e radicò l'influenza tedesca. Con la concessione della linea di Baghdad che sarebbe stata data alla stessa società undici anni dopo, sarebbe nato il sogno 'Berlino-Baghdad', che sarebbe divenuto uno degli assi principali della rivalità tra grandi potenze prima della Prima guerra mondiale.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Fondazione a Istanbul dell'Ittihad-ı Osmânî Cemiyeti", "b7187939"], "d": ["Quattro studenti della Scuola Militare di Medicina (Askerî Tıbbiye) fondarono come organizzazione segreta contro il regime dell'istibdat l'İttihâd-ı Osmânî Cemiyeti; questa struttura si trasformò presto nel Comitato Unione e Progresso (İttihat ve Terakkî Cemiyeti), che avrebbe riunito sotto il proprio tetto tutti gli elementi di opposizione del movimento dei Giovani Turchi. L'organizzazione, basata su cellule, si unì agli esuli in Europa e agli ufficiali di Salonicco. Da questa piccola cellula di studenti uscì il gruppo che nel 1908 avrebbe fatto proclamare la Seconda monarchia costituzionale e che dopo il 1913 avrebbe governato da solo lo Stato.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Irruzione alla Banca Ottomana: azione degli attivisti Dashnak a Galata", "08b3095f"], "d": ["Un gruppo armato dell'organizzazione armena Dashnaktsutyun, con lo scopo di attirare l'attenzione dell'Europa sulla questione armena, fece irruzione nella sede centrale della Banca Ottomana a Galata, prese ostaggi e minacciò di far saltare l'edificio. La crisi si concluse, con l'intervento degli ambasciatori, in cambio dell'allontanamento degli attivisti dal paese su una nave. I sanguinosi eventi verificatisi a Istanbul nei giorni successivi all'irruzione furono determinanti nella trasformazione della questione armena in una leva di intervento internazionale.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Inizio della guerra ottomano-greca del 1897: fronte di Tessaglia", "33e490ab"], "d": ["In seguito allo sbarco di flotta e truppe della Grecia a Creta e agli attacchi di bande al confine della Rumelia, l'Impero ottomano dichiarò guerra. L'esercito ottomano, addestrato dalla missione tedesca di riforma, avanzò rapidamente in Tessaglia e in un mese prese Yenişehir (Larissa), Çatalca e Dömeke; l'esercito greco si disperse. Con l'intervento delle grandi potenze i territori conquistati furono restituiti, ma la guerra rimase l'unica vittoria militare netta dell'epoca di Abdülhamid II e non poté evitare la perdita di fatto di Creta.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Concessione ai Tedeschi della linea Konya-Baghdad", "fd8b6cbd"], "d": ["Dopo la visita del Kaiser Guglielmo II a Istanbul e Damasco nel 1898, alla Società delle Ferrovie Anatoliche fu data la concessione preliminare per la linea che da Konya si sarebbe estesa a Baghdad e Bassora. Il progetto della Ferrovia di Baghdad significava per gli Ottomani il rafforzamento del controllo centrale sulle province arabe, per la Germania il raggiungimento del Golfo Persico. Questo progetto, a cui Inghilterra e Russia si opposero con forza, divenne uno dei dossier più controversi della rivalità imperialista che portò alla Prima guerra mondiale.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Inizio a Damasco della costruzione della Ferrovia dell'Hijaz", "62f58f68"], "d": ["La linea ordinata con l'irade di Abdülhamid II del 2 maggio 1900 vide l'inizio dei lavori il 1° settembre 1900 con una cerimonia ufficiale a Damasco. Il progetto, realizzato interamente con donazioni raccolte nel mondo islamico e con il lavoro di ingegneri-soldati ottomani, ridusse il viaggio dei pellegrini Damasco-Medina da quaranta giorni a cinque. Fu allo stesso tempo un'opera di prestigio che rafforzava l'autorità spirituale del califfato e un investimento strategico che consolidava il controllo militare sull'Hijaz.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Programma di Mürzsteg: controllo internazionale delle riforme in Macedonia", "4c7464da"], "d": ["Dopo la rivolta di Ilinden gli imperatori russo e austriaco, incontratisi a Mürzsteg, prepararono un nuovo pacchetto di riforme per la Macedonia. Il programma prevedeva l'affiancamento di due agenti civili stranieri all'ispettore generale ottomano, la riorganizzazione della gendarmeria da parte di ufficiali europei e la modifica dei confini amministrativi secondo il criterio della nazionalità. La Sublime Porta oppose resistenza ritenendo lesi i diritti di sovranità, ma di fronte alla pressione comune dovette accettare; il programma fu uno dei fattori fondamentali che accelerarono l'organizzazione unionista tra i giovani ufficiali.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Morte di Murad V", "396659a7"], "d": ["Murad V, rimasto sul trono circa tre mesi nel 1876 e deposto, dopo i tentativi di rimetterlo sul trono visse ventotto anni prigioniero sotto stretta sorveglianza e morì di diabete. Fu sepolto accanto alla madre nel Mausoleo Cedîd Havâtîn di Yenicami. Entrò nella storia come il sultano ottomano rimasto meno tempo sul trono.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Perdita di Sana'a a favore dell'imam Yahya", "e7f876cb"], "d": ["La rivolta avviata nel 1904 dall'imam zaidita Yahya Hamid al-Din si concluse nell'aprile 1905 con la caduta di Sana'a al termine dell'assedio; la città uscì dall'amministrazione ottomana e durante l'assedio si diffusero fame ed epidemia. La geografia montuosa dello Yemen, la lunghezza delle linee di rifornimento e la legittimità locale dell'imamato zaidita rendevano fragile il dominio ottomano fin dalla sua fondazione. La città sarebbe stata ripresa cinque mesi dopo a costo di gravi perdite, ma la questione dello Yemen non si sarebbe chiusa fino al 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Attentato di Yıldız: attacco con bomba ad Abdülhamid II", "1ee2e1a6"], "d": ["L'organizzazione Dashnaktsutyun compì un attentato facendo esplodere un landò con bomba a orologeria davanti alla carrozza del sultano all'uscita dal selâmlık del venerdì; il ritardo di qualche minuto di Abdülhamid, che parlava con lo şeyhülislam, gli salvò la vita. Nell'esplosione morirono ventisei persone e più di cinquanta furono ferite. Il fatto inasprì ulteriormente l'ossessione per la sicurezza del sultano e il regime dell'istibdat fondato sulla rete di spie; fu anche il soggetto della poesia 'Bir Lahza-i Taahhur' di Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Ripresa di Sana'a: repressione della rivolta dell'imam Yahya", "dec3b8f9"], "d": ["La rivolta avviata nel 1904 sotto la guida dell'imam zaidita Yahya si concluse nell'aprile 1905 con la caduta di Sana'a e in città si diffusero fame ed epidemia. Gli eserciti di rinforzo al comando di Ali Rızâ Pascià e Ahmed Feyzi Pascià, con un'operazione condotta tra il 15 luglio e il 1° settembre 1905 e sostenuta anche dalle forze di Taiz, ripresero la città a costo di gravi perdite e la rivolta fu repressa. La campagna dello Yemen costò all'esercito ottomano decine di migliaia di perdite e un onere finanziario enorme; tra gli ufficiali della Rumelia la paura dell'\"esilio nello Yemen\" era tra i primi motivi di lamentela che alimentavano l'organizzazione unionista.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Riunione del primo Meclis-i Meb'ûsan della Seconda monarchia costituzionale", "e7fd2716"], "d": ["L'assemblea formata con elezioni a due gradi tenute dopo un intervallo di trent'anni fu aperta il 17 dicembre 1908 con il discorso del sultano e alla presidenza fu eletto Ahmed Rızâ Bey, leader del movimento dei Giovani Turchi. Composta da deputati turchi, arabi, albanesi, greci, armeni ed ebrei, l'assemblea fu l'ultimo grande tentativo dell'ideale ottomanista. Ma l'indipendenza della Bulgaria, l'annessione della Bosnia e la proclamazione dell'unione di Creta alla Grecia avevano offuscato questo ottimismo prima ancora dell'apertura dell'assemblea.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Hareket Ordusu e deposizione di Abdülhamid II: ascesa al trono di Mehmed V Reşad", "6a65a704"], "d": ["L'Hareket Ordusu (Esercito d'Azione), partito da Salonicco dopo l'episodio del 31 marzo, entrò a Istanbul su quattro colonne nella notte del 22-23 aprile e il 24 aprile il Palazzo di Yıldız si arrese. Il Meclis-i Umûmî-i Millî il 27 aprile decise la deposizione di Abdülhamid II; il sultano fu inviato a Salonicco e al suo posto fu fatto salire al trono il fratello Mehmed V Reşad. Il governo personale di trentatré anni ebbe così fine, ma fu sostituito da una nuova epoca in cui il sultano era diventato un simbolo e il Comitato Unione e Progresso governava con il sostegno dell'esercito.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Rivolta albanese: resistenza armata in Kosovo e a Scutari", "93ed30c6"], "d": ["La politica fiscale centralista del governo unionista, la campagna di raccolta delle armi e il dibattito sull'alfabeto latino fecero sollevare le tribù albanesi, fino ad allora considerate tra gli elementi più fedeli allo Stato. Anche se l'esercito al comando di Mahmud Şevket Pascià represse duramente la rivolta, l'inquietudine si riaccese nel 1911 e nel 1912. Queste rivolte logorarono l'esercito ottomano alla vigilia della Guerra balcanica e accelerarono la nascita del movimento nazionale albanese.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Trattato di Ouchy (Uşi): cessione di Tripolitania e Bengasi all'Italia", "4ffa1fd2"], "d": ["La Sublime Porta, che di fronte ai preparativi bellici degli Stati balcanici non poteva permettersi di affrontare un conflitto su due fronti, firmò con l'Italia nella cittadina svizzera di Ouchy una pace segreta e cedette Tripolitania e Bengasi. L'Impero ottomano perse così il suo ultimo territorio in Africa; in cambio fu promessa la restituzione di Rodi e delle Dodecaneso occupate dall'Italia, ma la promessa non fu mai mantenuta. Quando il trattato fu firmato la Guerra balcanica era già iniziata. Con questo fatto Murzuq (Fezzan), Ghat, Sebha, Ubari, Tırgan (Traghan), Zevîle (Zawila) e el-Katrûn (Fezzan, sangiaccato del vilayet di Tripolitania) passarono sotto amministrazione italiana.", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Occupazione greca di Lemno", "9555af1d"], "d": ["Nella Prima guerra balcanica la flotta greca occupò Lemno; il porto di Mudros dell'isola divenne base per il blocco dei Dardanelli. L'isola fu lasciata alla Grecia a Losanna (24 luglio 1923).", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Occupazione greca di Taso", "6c03c7f0"], "d": ["Nella Prima guerra balcanica la Grecia occupò Taso e Samotracia.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Occupazione greca di Samotracia", "911e82a3"], "d": ["Nella Prima guerra balcanica la Grecia occupò Samotracia.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Occupazione greca di Mitilene (Lesbo)", "6b2b07ba"], "d": ["La flotta greca sbarcò a Mitilene; l'isola alla fine della Prima guerra balcanica fu presa dall'esercito e dalla flotta greci. La Conferenza di Londra (maggio 1913) confermò la situazione.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Sbarco greco a Chio", "901c6539"], "d": ["A Chio, bombardata il 7 aprile 1912 nella Prima guerra balcanica, i Greci effettuarono lo sbarco; la guarnigione ottomana si arrese il 3 gennaio 1913. L'isola fu lasciata alla Grecia con il Trattato di Losanna (24 luglio 1923).", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Uccisione per attentato a Istanbul del gran visir Mahmud Şevket Pascià", "68e60e63"], "d": ["Mahmud Şevket Pascià, nominato gran visir dopo l'irruzione alla Sublime Porta, fu ucciso dai colpi sparati contro la sua carrozza presso Çarşıkapı mentre si recava al Ministero della Guerra. Il Comitato Unione e Progresso, addossando l'attentato all'opposizione, avviò una vasta ondata di arresti ed esecuzioni e il Partito della Libertà e dell'Intesa fu di fatto liquidato. Con questo fatto fu stabilita in modo definitivo la dittatura a partito unico degli unionisti, fondata sul triumvirato Enver-Talat-Cemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Inizio della Seconda guerra balcanica: lite degli alleati per la spartizione", "48d088a2"], "d": ["Gli alleati balcanici, che non riuscivano a spartirsi i territori tolti agli Ottomani con il Trattato di Londra, si scontrarono tra loro; con l'attacco della Bulgaria alle posizioni serbe e greche iniziò la seconda guerra. Quando anche Romania e Montenegro entrarono in campo contro la Bulgaria l'esercito bulgaro crollò. L'Impero ottomano, approfittando dell'occasione, superò la linea Midye-Enez tracciata dal Trattato di Londra e riprese la Tracia orientale con Edirne.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Trattato di Istanbul: pace con la Bulgaria e registrazione di Edirne", "c8c18b2d"], "d": ["Il trattato firmato tra l'Impero ottomano e la Bulgaria dopo la Seconda guerra balcanica, riconoscendo il fiume Maritza (Meriç) come confine, sancì giuridicamente che Edirne, Kırklareli, Dimetoka e la Tracia orientale restassero agli Ottomani. Dedeağaç fu lasciata alla Bulgaria (Kavala invece era passata alla Grecia nel luglio 1913 dopo l'occupazione bulgara dell'autunno 1912 ed era stata registrata come greca con il Trattato di Bucarest del 10 agosto 1913), furono regolati uno scambio reciproco di popolazione tra i due paesi e i diritti dei musulmani in Bulgaria. Questo testo è la garanzia dell'unico lembo di territorio che fu possibile riprendere dal disastro balcanico. Altri luoghi annessi alla stessa data: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Ripresa di Tenedo e Imbro — Trattato di Atene", "ec084d09"], "d": ["Tenedo (Bozcaada) e Imbro, che tengono l'imboccatura dello Stretto, tra le isole dell'Egeo settentrionale occupate dalla Grecia nella Guerra balcanica, furono considerate indispensabili per la difesa di Çanakkale nei negoziati del Trattato di Atene e furono restituite agli Ottomani. Le altre isole restarono alla Grecia. Queste due isole furono gli ultimi territori che l'Impero tenne nell'Egeo e furono lasciate alla Turchia anche a Losanna.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Trattato di Atene: pace con la Grecia e cessione di Salonicco e Ioannina", "8e94def7"], "d": ["Il trattato firmato tra l'Impero ottomano e la Grecia riconobbe ufficialmente il passaggio alla Grecia di Salonicco, Ioannina e Macedonia meridionale, perdute nella Guerra balcanica, e fu abbandonato ogni diritto ottomano su Creta. Furono regolati in dettaglio i diritti di religione e proprietà dei musulmani rimasti in Grecia, lo statuto dei vakıf e la nomina dei müftü. Lo statuto delle isole dell'Egeo fu invece lasciato irrisolto e rimase una fonte di tensione continua tra i due Stati.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Firma a Istanbul del trattato segreto d'alleanza ottomano-tedesco", "0472efb3"], "d": ["Non appena scoppiò la guerra in Europa, nel palazzo del gran visir Said Halim Pascià fu firmato un trattato segreto d'alleanza tra l'Impero ottomano e la Germania; il testo prevedeva che, nel caso la Russia fosse entrata in guerra contro la Germania, gli Ottomani si schierassero con la Germania. Il trattato fu nascosto persino al gabinetto ed era noto solo a quattro persone. Tre mesi dopo, con l'incursione nel Mar Nero, l'Impero ottomano sarebbe stato di fatto trascinato in guerra e il destino dell'Impero sarebbe stato legato a questo documento.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Abolizione unilaterale delle capitolazioni", "ec773d18"], "d": ["Il governo ottomano, in un momento in cui l'Europa era impegnata nella guerra, dichiarò di abolire unilateralmente dal 1° ottobre 1914 le capitolazioni, che riconoscevano agli stranieri privilegi giudiziari, finanziari e doganali. La fine di questo ordinamento di privilegi quadricentenario fu accolta nel paese con grande entusiasmo d'indipendenza e a Istanbul si tennero celebrazioni. Tutti gli Stati, compresa l'alleata Germania, protestarono contro la decisione; le capitolazioni sarebbero state definitivamente consegnate alla storia solo nel 1923 a Losanna.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Incursione nel Mar Nero: bombardamento dei porti russi da parte della flotta ottomana", "8ad4ef61"], "d": ["Il Goeben e il Breslau (Yavuz e Midilli), fuggiti dalla Germania e uniti alla flotta ottomana come se fossero stati 'acquistati', al comando dell'ammiraglio Souchon si spinsero nel Mar Nero, bombardarono i porti russi e affondarono navi. Questo ordine, dato da Enver Pascià all'insaputa del gabinetto, pose fine di fatto alla neutralità. Entro una settimana Russia, Inghilterra e Francia dichiararono guerra e l'Impero ottomano entrò nella Prima guerra mondiale in modo irreversibile.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Presa di Fao da parte delle forze anglo-indiane — apertura del fronte iracheno", "08663813"], "d": ["La mattina successiva al giorno in cui gli Stati dell'Intesa dichiararono guerra all'Impero ottomano, la brigata anglo-indiana in attesa a Bahrein sbarcò a Fao, alla foce dello Shatt al-Arab. Il piccolo reparto ottomano nella fortezza in rovina di Fao si ritirò sotto il fuoco delle navi da guerra e la stazione della linea telegrafica dell'India passò in mano agli Inglesi. Il fronte iracheno fu così aperto.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proclamazione del Cihâd-ı Ekber: lettura della fatwa del jihad nella moschea di Fatih", "2a6174e8"], "d": ["Le cinque fatwa emesse dallo şeyhülislam Ürgüplü Hayri Efendi furono lette nella moschea di Fatih a nome del sultano-califfo e tutti i musulmani furono chiamati al jihad contro gli Stati dell'Intesa. Questa mossa, su cui la Germania riponeva grandi speranze, mirava a sollevare i musulmani delle colonie inglesi e francesi. La sollevazione generale attesa non avvenne; al contrario, la rivolta dell'emiro della Mecca Sharif Husayn con il sostegno inglese, due anni dopo, mostrò amaramente i limiti dell'influenza politica del califfato.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Resa di Qurna agli Inglesi", "621d36b0"], "d": ["Le forze del governatore di Bassora Subhi Bey, ritiratesi dopo la caduta di Bassora a Qurna, dove si uniscono Tigri ed Eufrate, dopo gli scontri del 4-8 dicembre si arresero la mattina del 9 dicembre 1914.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Operazione di Sarıkamış: disastro sul fronte del Caucaso", "5cbde7f0"], "d": ["Enver Pascià, con lo scopo di riprendere Kars-Ardahan-Batum, perduti nel 1878, e di sollevare i Turchi del Caucaso, spinse in inverno la III Armata, attraverso i monti Allahuekber, in una manovra per accerchiare le forze russe. Per l'equipaggiamento invernale insufficiente, i rifornimenti esauriti e le tormente fino a trenta gradi sotto zero, l'armata si sciolse prima ancora di entrare in battaglia; decine di migliaia di soldati morirono assiderati. L'operazione fu uno dei più gravi disastri ottomani nella guerra e lasciò il fronte orientale indifeso per due anni.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Prima Operazione del Canale: attacco a Suez attraverso il deserto del Sinai", "02dd72f5"], "d": ["Il comandante della IV Armata Cemal Pascià, con lo scopo di liberare l'Egitto dall'occupazione britannica e di chiudere il Canale di Suez alla navigazione, organizzò un attacco attraverso il deserto del Sinai. Anche se le unità ottomane raggiunsero la riva orientale del canale e alcune riuscirono ad attraversarlo, si ritirarono per la superiorità britannica e per il mancato verificarsi della sollevazione popolare egiziana attesa. L'operazione non raggiunse l'obiettivo, ma creò un effetto strategico indiretto costringendo l'Inghilterra a mantenere in Egitto una grande forza.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Emanazione della Legge di Deportazione e Insediamento (Sevk ve İskân / Tehcir)", "2f2bc22c"], "d": ["Dopo la rivolta di Van e l'avanzata russa, il governo emanò la legge provvisoria che permetteva ai comandanti d'armata di trasferire in altre regioni la popolazione ritenuta pericolosa per la sicurezza nelle retrovie, e il sultano la ratificò il 27 maggio 1915. Come conseguenza dell'applicazione, gran parte della popolazione armena delle province orientali e meridionali dell'Anatolia fu avviata in direzione di Siria e Mosul; durante i trasferimenti si ebbero perdite di vite umane molto gravi a causa di malattie, fame e aggressioni. La decisione è rimasta la questione più grave e ancora oggi più controversa degli ultimi anni ottomani.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Le unità ottomane riprendono Muş all'occupazione russa", "fb1be113"], "d": ["Sei mesi dopo la prima occupazione russa di Muş, il XVI Corpo d'armata ottomano entrò nella cittadina nella controffensiva di Bitlis-Muş.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muş passa di nuovo in mano russa", "43ad8a03"], "d": ["Per la controffensiva russa il distaccamento ottomano evacuò Muş; la cittadina tra il 22 e il 25 agosto 1916 entrò di nuovo sotto occupazione russa e vi rimase fino alla primavera del 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muş liberata definitivamente dall'occupazione russa", "f0e89703"], "d": ["Muş, passata sotto occupazione russa nella Prima guerra mondiale, fu ripresa in modo definitivo dalle forze ottomane il 1° maggio 1917.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Morte di Abdülhamid II nel Palazzo di Beylerbeyi", "c9662582"], "d": ["Abdülhamid II, deposto nel 1909 e portato prima a Salonicco e poi, per la perdita della città nella Guerra balcanica, a Istanbul, dove era tenuto agli arresti nel Palazzo di Beylerbeyi, morì. Nei trentatré anni del suo regno aveva cercato di guadagnare tempo tenendo lo Stato lontano dalle guerre, ma era anche ricordato per il regime dell'istibdat. La salma fu sepolta con una grande folla nel mausoleo di Mahmud I a Divanyolu; la sua morte coincise con un anno di guerra in cui l'ordine da lui creato era da tempo liquidato.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Trattato di Brest-Litovsk: ripresa di Kars, Ardahan e Batum", "da82636f"], "d": ["Il trattato firmato tra la Russia, ritiratasi dalla guerra dopo la rivoluzione bolscevica, e gli Imperi centrali chiuse il fronte orientale e restituì all'Impero ottomano Kars, Ardahan e Batum (Elviye-i Selâse), perduti con il Trattato di Berlino del 1878. Fu l'unico guadagno territoriale ottenuto nella storia ottomana dopo un intervallo di quarant'anni. Ma dopo l'Armistizio di Mudros la regione sarebbe andata di nuovo perduta e la soluzione definitiva sarebbe venuta con il Trattato di Kars del 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Le unità ottomane entrano ad Artvin", "ca7d1778"], "d": ["Le unità ottomane, che il 25 marzo avevano superato il confine del 1914, marciarono sull'Elviye-i Selâse, di cui Brest-Litovsk restituiva il confine anteriore al 1878, ed entrarono ad Artvin il 28 marzo 1918. Artvin era stata lasciata alla Russia nel 1878 come parte del sanjak di Batum; la voce Artvin del TDV scrive il ritorno soltanto come 'marzo 1918', il giorno lo dà Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan passa in mano all'esercito turco", "7fd9e3db"], "d": ["Nell'operazione dell'Elviye-i Selâse l'esercito ottomano prese Ardahan, dopo Artvin, il 3 aprile 1918; Ardahan era caduta nella Guerra del '93 nel 1877 ed era stata lasciata alla Russia nel 1878. Kars sarebbe stata presa un mese dopo, il 25 aprile.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Ripresa di Batum", "d37a1a0d"], "d": ["L'esercito ottomano, avanzato verso est dopo il ritiro della Russia dalla guerra con il Trattato di Brest-Litovsk, riprese dopo quarant'anni il porto di Batum, perduto nel 1878. Questo porto, all'estremità orientale del Mar Nero, era lo sbocco marittimo del petrolio di Baku. Il guadagno durò soltanto sette mesi; dopo l'Armistizio di Mudros la regione sarebbe stata evacuata.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elviye-i Selâse: Kars entra sotto amministrazione ottomana", "02cbf0b3"], "d": ["A Brest-Litovsk fu deciso il ritorno dei tre sanjak perduti con il Trattato di Berlino del 1878 — Kars, Ardahan e Batum; l'esercito ottomano entrò ad Ardahan il 3 aprile, a Batum il 14 aprile, a Kars il 25 aprile 1918 e l'amministrazione fu di fatto stabilita. Questi territori, noti con il nome di 'Elviye-i Selâse', furono considerati la compensazione della perdita in corso dalla Guerra del '93. Dopo l'armistizio sarebbero andati di nuovo perduti e sarebbero stati legati alla Turchia in modo definitivo solo con il Trattato di Kars del 1921.", "83a69417"]}
});
